{
  "name": "VocabFlow - Üniversite Kelime Asistanı",
  "description": "Üniversite öğrencilerinin ders notlarından kelime analizi yaparak interaktif çalışma kartları ve testler oluşturan İngilizce pekiştirme platformu."
}

export interface VocabularyItem {
  word: string;
  meaning: string;
  pronunciation: string;
  exampleSentence: string;
  category: string;
}

export type AppState = 'upload' | 'analyzing' | 'learning' | 'quiz' | 'list';

export interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: string;
  word: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { VocabularyItem } from "../types";

export const analyzeVocabulary = async (base64Data: string, mimeType: string): Promise<VocabularyItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const prompt = `
    Analyze the provided image/document. Extract ONLY the specific English vocabulary words and phrases mentioned in the text.
    For each word:
    1. Find its Turkish meaning (primary meaning in a learning context).
    2. Provide a clear pronunciation guide (IPA or phonetic).
    3. Create a short, natural example sentence using the word.
    4. Categorize it (e.g., Noun, Verb, Academic, etc.).

    IMPORTANT: Do not add external words. Focus strictly on the content provided in the file.
    Return the result in Turkish for meanings and categorization.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              meaning: { type: Type.STRING },
              pronunciation: { type: Type.STRING },
              exampleSentence: { type: Type.STRING },
              category: { type: Type.STRING }
            },
            required: ["word", "meaning", "pronunciation", "exampleSentence", "category"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];
    return JSON.parse(text) as VocabularyItem[];
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

export const generateQuiz = async (words: VocabularyItem[]): Promise<any[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const prompt = `Based on these words: ${JSON.stringify(words)}, generate 5 multiple choice questions to test vocabulary.
  Return a JSON array of objects with 'question', 'options' (array of 4 strings), 'correctAnswer' (string), and 'word'.
  Ensure questions are in English, but the context is helping a Turkish student.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Quiz Generation Error:", error);
    return [];
  }
};

import React, { useState } from 'react';

interface FileUploadProps {
  onFileSelect: (base64: string, mimeType: string) => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect }) => {
  const [dragActive, setDragActive] = useState(false);

  const handleFile = (file: File) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const base64 = (e.target?.result as string).split(',')[1];
      onFileSelect(base64, file.type);
    };
    reader.readAsDataURL(file);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFile(e.target.files[0]);
    }
  };

  return (
    <div 
      onDragOver={(e) => { e.preventDefault(); setDragActive(true); }}
      onDragLeave={() => setDragActive(false)}
      onDrop={(e) => { e.preventDefault(); setDragActive(false); if (e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]); }}
      className={`relative w-full max-w-2xl mx-auto p-12 border-2 border-dashed rounded-3xl transition-all duration-300 flex flex-col items-center justify-center space-y-4 ${
        dragActive ? 'border-indigo-500 bg-indigo-50' : 'border-slate-300 bg-white hover:border-indigo-400'
      }`}
    >
      <div className="w-16 h-16 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-600">
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
          <path strokeLinecap="round" strokeLinejoin="round" d="M12 16.5V9.75m0 0l3 3m-3-3l-3 3M6.75 19.5a4.5 4.5 0 01-1.41-8.775 5.25 5.25 0 0110.233-2.33 3 3 0 013.758 3.848A3.752 3.752 0 0118 19.5H6.75z" />
        </svg>
      </div>
      <div className="text-center">
        <h3 className="text-xl font-semibold text-slate-800">Ders Notlarını Yükle</h3>
        <p className="text-slate-500 mt-1">Görsel veya PDF dosyasını buraya sürükle bırak</p>
      </div>
      <label className="cursor-pointer bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3 rounded-xl font-medium transition-colors shadow-lg shadow-indigo-200">
        Dosya Seç
        <input type="file" className="hidden" accept="image/*,application/pdf" onChange={handleChange} />
      </label>
      <p className="text-xs text-slate-400">Desteklenenler: JPEG, PNG, PDF</p>
    </div>
  );
};

export default FileUpload;

import React, { useState } from 'react';
import { VocabularyItem } from '../types';

interface FlashcardsProps {
  items: VocabularyItem[];
  onComplete: () => void;
}

const Flashcards: React.FC<FlashcardsProps> = ({ items, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  const current = items[currentIndex];

  const nextCard = () => {
    if (currentIndex < items.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setIsFlipped(false);
    } else {
      onComplete();
    }
  };

  const prevCard = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
      setIsFlipped(false);
    }
  };

  return (
    <div className="flex flex-col items-center space-y-8 w-full max-w-lg mx-auto p-4">
      <div className="w-full flex justify-between items-center px-4">
        <span className="text-sm font-medium text-slate-500">Kelime {currentIndex + 1} / {items.length}</span>
        <div className="h-1.5 w-32 bg-slate-200 rounded-full overflow-hidden">
          <div 
            className="h-full bg-indigo-500 transition-all duration-300" 
            style={{ width: `${((currentIndex + 1) / items.length) * 100}%` }}
          />
        </div>
      </div>

      <div 
        className="relative w-full h-80 cursor-pointer transition-all duration-500 [perspective:1000px]"
        onClick={() => setIsFlipped(!isFlipped)}
      >
        <div className={`relative w-full h-full transition-all duration-500 [transform-style:preserve-3d] ${isFlipped ? '[transform:rotateY(180deg)]' : ''}`}>
          {/* Front */}
          <div className="absolute inset-0 bg-white rounded-3xl shadow-xl flex flex-col items-center justify-center p-8 border border-slate-100 [backface-visibility:hidden]">
            <span className="text-xs font-bold text-indigo-500 uppercase tracking-widest mb-4">{current.category}</span>
            <h2 className="text-4xl font-bold text-slate-800 mb-2">{current.word}</h2>
            <p className="text-slate-400 italic mb-6">/{current.pronunciation}/</p>
            <p className="text-slate-400 text-sm mt-auto">Çevirmek için tıkla</p>
          </div>

          {/* Back */}
          <div className="absolute inset-0 bg-indigo-600 rounded-3xl shadow-xl flex flex-col items-center justify-center p-8 text-white [backface-visibility:hidden] [transform:rotateY(180deg)]">
            <h3 className="text-3xl font-bold mb-4">{current.meaning}</h3>
            <div className="bg-indigo-500/30 p-4 rounded-2xl w-full">
              <p className="text-center italic leading-relaxed text-indigo-50">"{current.exampleSentence}"</p>
            </div>
            <p className="text-indigo-200 text-sm mt-auto">Geri dönmek için tıkla</p>
          </div>
        </div>
      </div>

      <div className="flex space-x-4 w-full">
        <button 
          onClick={(e) => { e.stopPropagation(); prevCard(); }}
          disabled={currentIndex === 0}
          className="flex-1 py-4 bg-white border border-slate-200 rounded-2xl font-semibold text-slate-600 hover:bg-slate-50 disabled:opacity-50 transition-all"
        >
          Geri
        </button>
        <button 
          onClick={(e) => { e.stopPropagation(); nextCard(); }}
          className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-semibold hover:bg-indigo-700 shadow-lg shadow-indigo-100 transition-all"
        >
          {currentIndex === items.length - 1 ? 'Bitir' : 'Sıradaki'}
        </button>
      </div>
    </div>
  );
};

export default Flashcards;

import React, { useState } from 'react';
import { QuizQuestion } from '../types';

interface QuizProps {
  questions: QuizQuestion[];
  onClose: () => void;
}

const Quiz: React.FC<QuizProps> = ({ questions, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [showResult, setShowResult] = useState(false);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);

  const handleAnswer = (option: string) => {
    if (isAnswered) return;
    setSelectedOption(option);
    setIsAnswered(true);
    if (option === questions[currentIndex].correctAnswer) {
      setScore(s => s + 1);
    }
  };

  const nextQuestion = () => {
    if (currentIndex < questions.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setShowResult(true);
    }
  };

  if (showResult) {
    return (
      <div className="bg-white p-12 rounded-3xl shadow-2xl text-center max-w-md mx-auto border border-slate-100">
        <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6">
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-10 h-10">
            <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        </div>
        <h2 className="text-3xl font-bold text-slate-800 mb-2">Harika İş!</h2>
        <p className="text-slate-500 mb-6">Testi tamamladın. Başarı oranın:</p>
        <div className="text-5xl font-black text-indigo-600 mb-8">
          %{Math.round((score / questions.length) * 100)}
        </div>
        <button 
          onClick={onClose}
          className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100"
        >
          Ana Sayfaya Dön
        </button>
      </div>
    );
  }

  const current = questions[currentIndex];

  return (
    <div className="w-full max-w-xl mx-auto space-y-6">
      <div className="flex justify-between items-center mb-4">
        <span className="text-sm font-bold text-slate-400">SORU {currentIndex + 1} / {questions.length}</span>
        <span className="px-3 py-1 bg-indigo-50 text-indigo-600 text-xs font-bold rounded-full">KAZANILAN PUAN: {score}</span>
      </div>

      <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100">
        <h3 className="text-2xl font-bold text-slate-800 mb-8 leading-snug">
          {current.question}
        </h3>

        <div className="grid gap-4">
          {current.options.map((option, idx) => {
            const isCorrect = option === current.correctAnswer;
            const isSelected = option === selectedOption;
            let bgColor = 'bg-slate-50 border-slate-200 hover:border-indigo-400';

            if (isAnswered) {
              if (isCorrect) bgColor = 'bg-green-50 border-green-500 text-green-700';
              else if (isSelected) bgColor = 'bg-red-50 border-red-500 text-red-700';
              else bgColor = 'bg-slate-50 border-slate-200 opacity-50';
            }

            return (
              <button
                key={idx}
                disabled={isAnswered}
                onClick={() => handleAnswer(option)}
                className={`w-full text-left p-5 border-2 rounded-2xl font-medium transition-all ${bgColor}`}
              >
                <div className="flex items-center justify-between">
                  <span>{option}</span>
                  {isAnswered && isCorrect && (
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.857-9.809a.75.75 0 00-1.214-.882l-3.483 4.79-1.88-1.88a.75.75 0 10-1.06 1.061l2.5 2.5a.75.75 0 001.137-.089l4-5.5z" clipRule="evenodd" />
                    </svg>
                  )}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {isAnswered && (
        <button 
          onClick={nextQuestion}
          className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-bold hover:bg-indigo-700 transition-all transform hover:scale-[1.02] shadow-xl shadow-indigo-100"
        >
          {currentIndex === questions.length - 1 ? 'Sonuçları Gör' : 'Sıradaki Soru'}
        </button>
      )}
    </div>
  );
};

export default Quiz;

import React, { useState } from 'react';
import { AppState, VocabularyItem, QuizQuestion } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('upload');
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);

  const handleFileSelect = async (base64: string, mimeType: string) => {
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);
      if (items.length === 0) {
        throw new Error("Dosyada kelime bulunamadı. Lütfen daha net bir görsel yükleyin.");
      }
      setVocabItems(items);
      setState('learning');
    } catch (err) {
      setError("Kelime analizi sırasında bir hata oluştu. Lütfen tekrar deneyin.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setError("Test oluşturulamadı.");
      setState('learning');
    }
  };

  const reset = () => {
    setState('upload');
    setVocabItems([]);
    setQuizQuestions([]);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-5xl mx-auto px-6 py-4 flex justify-between items-center">
          <div className="flex items-center space-x-2 cursor-pointer" onClick={reset}>
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
              </svg>
            </div>
            <h1 className="text-xl font-bold bg-gradient-to-r from-indigo-600 to-violet-600 bg-clip-text text-transparent">VocabFlow</h1>
          </div>

          <nav className="hidden md:flex space-x-8">
            <button 
              onClick={() => setState('upload')} 
              className={`text-sm font-semibold transition-colors ${state === 'upload' ? 'text-indigo-600' : 'text-slate-500 hover:text-indigo-500'}`}
            >
              Yükle
            </button>
            <button 
              onClick={() => vocabItems.length > 0 && setState('learning')} 
              disabled={vocabItems.length === 0}
              className={`text-sm font-semibold transition-colors ${state === 'learning' ? 'text-indigo-600' : 'text-slate-500 hover:text-indigo-500'} disabled:opacity-30`}
            >
              Çalışma Kartları
            </button>
            <button 
              onClick={() => vocabItems.length > 0 && setState('list')} 
              disabled={vocabItems.length === 0}
              className={`text-sm font-semibold transition-colors ${state === 'list' ? 'text-indigo-600' : 'text-slate-500 hover:text-indigo-500'} disabled:opacity-30`}
            >
              Kelime Listesi
            </button>
          </nav>

          <button className="md:hidden text-slate-500">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
              <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
            </svg>
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-5xl mx-auto w-full px-6 py-12">
        {error && (
          <div className="mb-8 p-4 bg-red-50 border border-red-100 text-red-600 rounded-2xl text-center font-medium animate-bounce">
            {error}
          </div>
        )}

        {state === 'upload' && (
          <div className="flex flex-col items-center space-y-12">
            <div className="text-center space-y-4 max-w-2xl">
              <h2 className="text-4xl md:text-5xl font-extrabold text-slate-800 tracking-tight leading-tight">
                Notlarını Yükle, <span className="text-indigo-600">Saniyeler İçinde</span> Öğrenmeye Başla.
              </h2>
              <p className="text-lg text-slate-500 font-medium">
                Üniversitedeki İngilizce kelimeleri pekiştirmek için notlarının fotoğrafını çek veya PDF olarak yükle. 
                Yapay zeka senin için kelimeleri analiz etsin ve interaktif bir çalışma planı sunsun.
              </p>
            </div>
            <FileUpload onFileSelect={handleFileSelect} />
          </div>
        )}

        {state === 'analyzing' && (
          <div className="flex flex-col items-center justify-center py-24 space-y-6">
            <div className="relative w-24 h-24">
              <div className="absolute inset-0 border-4 border-indigo-100 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-indigo-600 rounded-full border-t-transparent animate-spin"></div>
            </div>
            <div className="text-center">
              <h3 className="text-2xl font-bold text-slate-800">Analiz Ediliyor...</h3>
              <p className="text-slate-500 mt-2">Yapay zeka notlarındaki kelimeleri çıkartıyor ve örnekler hazırlıyor.</p>
            </div>
          </div>
        )}

        {state === 'learning' && (
          <div className="space-y-12">
            <div className="flex justify-between items-end">
              <div>
                <h2 className="text-3xl font-bold text-slate-800">Öğrenme Zamanı</h2>
                <p className="text-slate-500 mt-1">Bu kelimeleri bugün pekiştirmen gerekiyor.</p>
              </div>
              <button 
                onClick={startQuiz}
                className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-indigo-100 transition-all"
              >
                Kendini Test Et
              </button>
            </div>
            <Flashcards items={vocabItems} onComplete={() => setState('list')} />
          </div>
        )}

        {state === 'quiz' && (
          <Quiz questions={quizQuestions} onClose={() => setState('learning')} />
        )}

        {state === 'list' && (
          <div className="space-y-8">
            <div className="flex justify-between items-center">
              <h2 className="text-3xl font-bold text-slate-800">Kelime Listesi</h2>
              <button 
                onClick={() => setState('upload')}
                className="text-indigo-600 font-bold hover:underline"
              >
                + Yeni Dosya Yükle
              </button>
            </div>
            <div className="grid gap-4">
              {vocabItems.map((item, idx) => (
                <div key={idx} className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow group">
                  <div className="flex flex-col md:flex-row md:items-center md:justify-between space-y-4 md:space-y-0">
                    <div>
                      <div className="flex items-center space-x-3">
                        <h4 className="text-xl font-bold text-slate-800">{item.word}</h4>
                        <span className="text-xs font-medium text-slate-400 uppercase tracking-widest">{item.category}</span>
                      </div>
                      <p className="text-indigo-600 font-semibold mt-1">{item.meaning}</p>
                    </div>
                    <div className="md:text-right max-w-md">
                      <p className="text-sm italic text-slate-500 leading-relaxed">"{item.exampleSentence}"</p>
                      <p className="text-xs text-slate-400 mt-2">/{item.pronunciation}/</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-slate-100 py-8 mt-auto">
        <div className="max-w-5xl mx-auto px-6 text-center">
          <p className="text-slate-400 text-sm">© 2024 VocabFlow - Üniversite Öğrencileri için Kelime Geliştirme Platformu</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface VocabularyItem {
  word: string;
  meaning: string;
  pronunciation: string;
  exampleSentence: string;
  exampleSentenceTurkish: string; // Added field
  category: string;
}

export type AppState = 'upload' | 'analyzing' | 'selection' | 'learning' | 'quiz' | 'list';

export interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: string;
  word: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { VocabularyItem } from "../types";

export const analyzeVocabulary = async (base64Data: string, mimeType: string): Promise<VocabularyItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const prompt = `
    Analyze the provided image/document. Extract ONLY the specific English vocabulary words and phrases mentioned in the text.
    For each word:
    1. Find its Turkish meaning (primary meaning in a learning context).
    2. Provide a clear pronunciation guide (IPA or phonetic).
    3. Create a short, natural example sentence in English.
    4. Provide the Turkish translation of that English example sentence.
    5. Categorize it (e.g., Noun, Verb, Academic, etc.).

    IMPORTANT: Do not add external words. Focus strictly on the content provided in the file.
    Return the result in Turkish for meanings, translations, and categorization.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              meaning: { type: Type.STRING },
              pronunciation: { type: Type.STRING },
              exampleSentence: { type: Type.STRING },
              exampleSentenceTurkish: { type: Type.STRING },
              category: { type: Type.STRING }
            },
            required: ["word", "meaning", "pronunciation", "exampleSentence", "exampleSentenceTurkish", "category"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];
    return JSON.parse(text) as VocabularyItem[];
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

export const generateQuiz = async (words: VocabularyItem[]): Promise<any[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const prompt = `Based on these words: ${JSON.stringify(words)}, generate 5 multiple choice questions to test vocabulary.
  Return a JSON array of objects with 'question', 'options' (array of 4 strings), 'correctAnswer' (string), and 'word'.
  Ensure questions are in English, but the context is helping a Turkish student.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Quiz Generation Error:", error);
    return [];
  }
};

import React, { useState } from 'react';
import { VocabularyItem } from '../types';

interface FlashcardsProps {
  items: VocabularyItem[];
  onComplete: () => void;
}

const Flashcards: React.FC<FlashcardsProps> = ({ items, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  const current = items[currentIndex];

  const nextCard = () => {
    if (currentIndex < items.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setIsFlipped(false);
    } else {
      onComplete();
    }
  };

  const prevCard = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
      setIsFlipped(false);
    }
  };

  return (
    <div className="flex flex-col items-center space-y-8 w-full max-w-lg mx-auto p-4">
      <div className="w-full flex justify-between items-center px-4">
        <span className="text-sm font-medium text-slate-500">Kelime {currentIndex + 1} / {items.length}</span>
        <div className="h-1.5 w-32 bg-slate-200 rounded-full overflow-hidden">
          <div 
            className="h-full bg-indigo-500 transition-all duration-300" 
            style={{ width: `${((currentIndex + 1) / items.length) * 100}%` }}
          />
        </div>
      </div>

      <div 
        className="relative w-full h-96 cursor-pointer transition-all duration-500 [perspective:1000px]"
        onClick={() => setIsFlipped(!isFlipped)}
      >
        <div className={`relative w-full h-full transition-all duration-500 [transform-style:preserve-3d] ${isFlipped ? '[transform:rotateY(180deg)]' : ''}`}>
          {/* Front */}
          <div className="absolute inset-0 bg-white rounded-3xl shadow-xl flex flex-col items-center justify-center p-8 border border-slate-100 [backface-visibility:hidden]">
            <span className="text-xs font-bold text-indigo-500 uppercase tracking-widest mb-4">{current.category}</span>
            <h2 className="text-4xl font-bold text-slate-800 mb-2">{current.word}</h2>
            <p className="text-slate-400 italic mb-6">/{current.pronunciation}/</p>
            <p className="text-slate-400 text-sm mt-auto">Anlamını görmek için tıkla</p>
          </div>

          {/* Back */}
          <div className="absolute inset-0 bg-indigo-600 rounded-3xl shadow-xl flex flex-col items-center justify-center p-8 text-white [backface-visibility:hidden] [transform:rotateY(180deg)] overflow-y-auto">
            <h3 className="text-3xl font-bold mb-6">{current.meaning}</h3>

            <div className="space-y-4 w-full">
              <div className="bg-indigo-500/30 p-4 rounded-2xl w-full">
                <p className="text-center italic leading-relaxed text-indigo-50 font-medium">"{current.exampleSentence}"</p>
              </div>

              <div className="pt-2 border-t border-indigo-400/50 w-full">
                <p className="text-center text-sm text-indigo-100 opacity-90">
                  {current.exampleSentenceTurkish}
                </p>
              </div>
            </div>

            <p className="text-indigo-200 text-xs mt-auto pt-4">Geri dönmek için tıkla</p>
          </div>
        </div>
      </div>

      <div className="flex space-x-4 w-full">
        <button 
          onClick={(e) => { e.stopPropagation(); prevCard(); }}
          disabled={currentIndex === 0}
          className="flex-1 py-4 bg-white border border-slate-200 rounded-2xl font-semibold text-slate-600 hover:bg-slate-50 disabled:opacity-50 transition-all"
        >
          Geri
        </button>
        <button 
          onClick={(e) => { e.stopPropagation(); nextCard(); }}
          className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-semibold hover:bg-indigo-700 shadow-lg shadow-indigo-100 transition-all"
        >
          {currentIndex === items.length - 1 ? 'Bitir' : 'Sıradaki'}
        </button>
      </div>
    </div>
  );
};

export default Flashcards;

