            <label className="text-xs font-bold text-slate-400 uppercase ml-2">Türkçe Anlamı</label>
            <input 
              required
              className="w-full bg-slate-50 border-none rounded-2xl p-4 focus:ring-2 focus:ring-indigo-200 outline-none text-slate-700"
              value={formData.meaning}
              onChange={e => setFormData({...formData, meaning: e.target.value})}
              placeholder="Örn: Esneklik, Direnç"
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-400 uppercase ml-2">İngilizce Örnek Cümle</label>
            <textarea 
              className="w-full bg-slate-50 border-none rounded-2xl p-4 focus:ring-2 focus:ring-indigo-200 outline-none text-slate-700 resize-none h-20"
              value={formData.exampleSentence}
              onChange={e => setFormData({...formData, exampleSentence: e.target.value})}
              placeholder="Cümle yazın..."
            />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-400 uppercase ml-2">Cümle Çevirisi</label>
            <input 
              className="w-full bg-slate-50 border-none rounded-2xl p-4 focus:ring-2 focus:ring-indigo-200 outline-none text-slate-700"
              value={formData.exampleSentenceTurkish}
              onChange={e => setFormData({...formData, exampleSentenceTurkish: e.target.value})}
              placeholder="Cümlenin Türkçe anlamı..."
            />
          </div>

          <button 
            type="submit"
            className="w-full py-4 bg-indigo-500 hover:bg-indigo-600 text-white rounded-[1.5rem] font-bold shadow-lg shadow-indigo-100 transition-all mt-4"
          >
            Listeye Ekle
          </button>
        </form>
      </div>
    </div>
  );
};

