import React, { useState } from 'react';
import { AppState, VocabularyItem, QuizQuestion } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('upload');
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleFileSelect = async (base64: string, mimeType: string) => {
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);
      if (items.length === 0) {
        throw new Error("Dosyada kelime bulunamadı. Lütfen daha net bir görsel yükleyin.");
      }
      setVocabItems(items);
      setState('selection');
    } catch (err) {
      setError("Kelime analizi sırasında bir hata oluştu. Lütfen tekrar deneyin.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (quizQuestions.length > 0) {
      setState('quiz');
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setError("Test oluşturulamadı.");
      setState('selection');
    }
  };

  const addManualWord = (newItem: VocabularyItem) => {
    setVocabItems(prev => [...prev, newItem]);
    // Reset quiz questions since the vocab list changed
    setQuizQuestions([]);
