import React, { useState } from 'react';
import { VocabularyItem } from '../types';

interface FlashcardsProps {
  items: VocabularyItem[];
  onComplete: () => void;
}

const Flashcards: React.FC<FlashcardsProps> = ({ items, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  const current = items[currentIndex];

  const speak = (text: string, lang: 'en-GB' | 'en-US') => {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = lang;
    utterance.rate = 0.9; // Slightly slower for kids
    window.speechSynthesis.speak(utterance);
  };

  const nextCard = () => {
    if (currentIndex < items.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setIsFlipped(false);
    } else {
      onComplete();
    }
  };

  const prevCard = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
      setIsFlipped(false);
    }
  };

  return (
    <div className="flex flex-col items-center space-y-8 w-full max-w-lg mx-auto p-4 animate-in fade-in duration-500">
      <div className="w-full flex justify-between items-center px-4">
        <span className="text-sm font-bold text-orange-400 bg-orange-50 px-3 py-1 rounded-full">KART {currentIndex + 1} / {items.length}</span>
        <div className="h-3 w-32 bg-slate-100 rounded-full overflow-hidden border border-slate-200">
          <div 
            className="h-full bg-gradient-to-r from-blue-400 to-indigo-400 transition-all duration-500" 
            style={{ width: `${((currentIndex + 1) / items.length) * 100}%` }}
          />
        </div>
      </div>

      <div 
        className="relative w-full h-[450px] cursor-pointer perspective-1000"
        onClick={() => setIsFlipped(!isFlipped)}
      >
        <div className={`relative w-full h-full transition-all duration-500 transform-style-3d ${isFlipped ? 'rotate-y-180' : ''}`}>

          {/* Front side: English Word & Pronunciation */}
          <div className="absolute inset-0 bg-white rounded-[3rem] shadow-[0_20px_50px_rgba(0,0,0,0.05)] flex flex-col items-center justify-center p-8 border-4 border-blue-50 backface-hidden">
            <span className="text-sm font-bold text-slate-300 uppercase tracking-widest mb-2">İNGİLİZCE</span>
            <h2 className="text-6xl font-black text-slate-800 mb-8 tracking-tight">{current.word}</h2>

            <div className="flex space-x-8 mb-12">
              {/* British English */}
              <div className="flex flex-col items-center space-y-3">
                <button 
                  onClick={(e) => { e.stopPropagation(); speak(current.word, 'en-GB'); }}
                  className="w-16 h-16 bg-blue-50 text-blue-500 rounded-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-lg shadow-blue-100/50"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-8 h-8">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" />
                  </svg>
                </button>
                <div className="flex flex-col items-center">
                  <span className="text-[10px] font-bold text-slate-400 mb-1">British</span>
                  <img src="https://flagcdn.com/w40/gb.png" className="w-6 rounded-sm shadow-sm border border-slate-100" alt="UK" />
                </div>
              </div>

              {/* American English */}
              <div className="flex flex-col items-center space-y-3">
                <button 
                  onClick={(e) => { e.stopPropagation(); speak(current.word, 'en-US'); }}
