import React, { useState } from 'react';
import { QuizQuestion } from '../types';

interface QuizProps {
  questions: QuizQuestion[];
  onClose: () => void;
}

const Quiz: React.FC<QuizProps> = ({ questions, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [showResult, setShowResult] = useState(false);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);

  const handleAnswer = (option: string) => {
    if (isAnswered) return;
    setSelectedOption(option);
    setIsAnswered(true);
    if (option === questions[currentIndex].correctAnswer) {
      setScore(s => s + 1);
    }
  };

  const nextQuestion = () => {
    if (currentIndex < questions.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setShowResult(true);
    }
  };

  if (showResult) {
    const percentage = Math.round((score / questions.length) * 100);
    let message = "Harika gidiyorsun! 🎉";
    let icon = "🌟";
    if (percentage === 100) { message = "Mükemmelsin! Şampiyon! 🏆"; icon = "🦁"; }
    else if (percentage < 50) { message = "Biraz daha çalışalım mı? 🧸"; icon = "📚"; }

    return (
      <div className="bg-white p-16 rounded-[4rem] shadow-2xl text-center max-w-lg mx-auto border-4 border-blue-50 animate-in zoom-in-95 duration-500">
        <div className="text-7xl mb-8">{icon}</div>
        <h2 className="text-4xl font-black text-slate-800 mb-4 tracking-tight">{message}</h2>
        <p className="text-slate-400 text-xl font-medium mb-10">Bugün çok şey öğrendin!</p>
        <div className="bg-blue-50 p-10 rounded-[3rem] mb-12">
          <span className="text-7xl font-black text-blue-500">%{percentage}</span>
          <p className="text-blue-400 font-bold mt-2 uppercase tracking-widest">Başarı Oranın</p>
        </div>
        <button 
          onClick={onClose}
          className="w-full py-6 bg-blue-500 text-white rounded-[2rem] font-black text-xl hover:bg-blue-600 transition-all shadow-xl shadow-blue-100"
        >
          Ana Menüye Dön
        </button>
      </div>
    );
  }

  const current = questions[currentIndex];

  return (
    <div className="w-full max-w-2xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-8">
      <div className="flex justify-between items-center mb-4 px-6">
        <span className="text-lg font-black text-slate-300">SORU {currentIndex + 1} / {questions.length}</span>
        <div className="flex items-center space-x-2 bg-yellow-50 px-5 py-2 rounded-full">
           <span className="text-lg">⭐</span>
           <span className="text-yellow-600 font-black">PUAN: {score * 10}</span>
        </div>
      </div>

      <div className="bg-white p-12 rounded-[4rem] shadow-2xl border-4 border-white">
        <h3 className="text-4xl font-black text-slate-800 mb-12 leading-tight text-center">
          {current.question}
        </h3>

        <div className="grid gap-6">
          {current.options.map((option, idx) => {
            const isCorrect = option === current.correctAnswer;
            const isSelected = option === selectedOption;
            let bgColor = 'bg-slate-50 border-slate-100 hover:border-blue-400 hover:bg-blue-50/30';

            if (isAnswered) {
              if (isCorrect) bgColor = 'bg-green-100 border-green-500 text-green-700 ring-4 ring-green-50';
              else if (isSelected) bgColor = 'bg-red-100 border-red-500 text-red-700';
              else bgColor = 'bg-slate-50 border-slate-100 opacity-30';
            }

            return (
              <button
                key={idx}
                disabled={isAnswered}
                onClick={() => handleAnswer(option)}
                className={`w-full text-left p-6 border-4 rounded-[2rem] text-xl font-black transition-all transform ${!isAnswered ? 'hover:scale-[1.03] active:scale-95' : ''} ${bgColor}`}
              >
                <div className="flex items-center justify-between">
                  <span>{option}</span>
                  {isAnswered && isCorrect && (
                    <span className="text-3xl">✅</span>
                  )}
                  {isAnswered && !isCorrect && isSelected && (
                    <span className="text-3xl">❌</span>
                  )}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {isAnswered && (
        <button 
          onClick={nextQuestion}
          className="w-full py-6 bg-orange-400 text-white rounded-[2.5rem] font-black text-2xl hover:bg-orange-500 transition-all transform hover:scale-[1.02] shadow-2xl shadow-orange-100 animate-in slide-in-from-top-4"
        >
          {currentIndex === questions.length - 1 ? 'Sonucu Gör ✨' : 'Sıradaki Soru 🚀'}
        </button>
      )}
    </div>
  );
};

