import { GoogleGenAI, Type } from "@google/genai";
import { VocabularyItem } from "../types";

export const analyzeVocabulary = async (base64Data: string, mimeType: string): Promise<VocabularyItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const prompt = `
    Analyze the provided image/document with extreme detail. 
    Your goal is to extract ALL English vocabulary words, phrases, terms, and expressions mentioned in the text. 
    Be as exhaustive as possible, aiming to find up to 250 unique items if the content allows. 
    Do not skip small words; capture every noun, verb, adjective, and adverb you find.

    For each word:
    1. Find its Turkish meaning.
    2. Provide a pronunciation guide.
    3. Create a short, simple example sentence in English (suitable for a 9-year-old).
    4. Provide the Turkish translation of that example sentence.
    5. Categorize it (e.g., Noun, Verb, etc.).

    IMPORTANT: Focus strictly on the content provided in the file, but be 100% thorough.
    Return the result as a JSON array.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              meaning: { type: Type.STRING },
              pronunciation: { type: Type.STRING },
              exampleSentence: { type: Type.STRING },
              exampleSentenceTurkish: { type: Type.STRING },
              category: { type: Type.STRING }
            },
            required: ["word", "meaning", "pronunciation", "exampleSentence", "exampleSentenceTurkish", "category"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];
    return JSON.parse(text) as VocabularyItem[];
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

export const generateQuiz = async (words: VocabularyItem[]): Promise<any[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  // Take a subset for the quiz if there are too many words, but keep it random
  const subset = [...words].sort(() => Math.random() - 0.5).slice(0, 10);

  const prompt = `Based on these words: ${JSON.stringify(subset)}, generate 10 multiple choice questions to test vocabulary.
  Return a JSON array of objects with 'question', 'options' (array of 4 strings), 'correctAnswer' (string), and 'word'.
  Ensure questions are simple for a child.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Quiz Generation Error:", error);
    return [];
  }
};

