  useEffect(() => {
    const savedUser = localStorage.getItem('sbuddy_user');
    if (savedUser) {
      const user = JSON.parse(savedUser);
      setCurrentUser(user);
      loadUserWords(user.id);
      setState('selection');
    }
  }, []);

  const loadUserWords = (userId: string) => {
    const savedWords = localStorage.getItem(`sbuddy_words_${userId}`);
    if (savedWords) {
      setVocabItems(JSON.parse(savedWords));
    }
  };

  const saveUserWords = (userId: string, words: VocabularyItem[]) => {
    localStorage.setItem(`sbuddy_words_${userId}`, JSON.stringify(words));
    setVocabItems(words);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('sbuddy_user', JSON.stringify(user));
    loadUserWords(user.id);
    setState('selection');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('sbuddy_user');
    setVocabItems([]);
    setState('home');
  };

  // Helper to shuffle items
  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);
      if (items.length === 0) {
        throw new Error("Kelimeleri bulamadım 🐣 Lütfen tekrar dene!");
      }

      const newItemsWithIds = items.map(item => ({ ...item, id: crypto.randomUUID() }));
      const updatedList = [...vocabItems, ...newItemsWithIds];

      if (currentUser) {
        saveUserWords(currentUser.id, updatedList);
      } else {
        setVocabItems(updatedList);
      }

      setState('selection');
    } catch (err) {
      setError("Bir şeyler ters gitti 🍭 Lütfen tekrar yükle.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 4) {
      setError("Test için en az 4 kelime lazım! 🎈");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setError("Oyun hazırlanamadı 🎨");
      setState('selection');
    }
  };

  const addOrUpdateWord = (item: VocabularyItem) => {
    let newList;
    if (item.id) {
      newList = vocabItems.map(v => v.id === item.id ? item : v);
    } else {
      newList = [...vocabItems, { ...item, id: crypto.randomUUID() }];
    }

    if (currentUser) {
      saveUserWords(currentUser.id, newList);
    } else {
      setVocabItems(newList);
    }
    setQuizQuestions([]);
    setEditingItem(null);
  };

  const deleteWord = (id: string) => {
    const newList = vocabItems.filter(v => v.id !== id);
    if (currentUser) {
      saveUserWords(currentUser.id, newList);
    } else {
      setVocabItems(newList);
    }
    setQuizQuestions([]);
  };

  const handleEditClick = (item: VocabularyItem) => {
    setEditingItem(item);
    setIsModalOpen(true);
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-100 selection:text-blue-700">
      {/* Header */}
      <header className="bg-white/70 backdrop-blur-md sticky top-0 z-20 py-6 border-b border-orange-50">
        <div className="max-w-6xl mx-auto px-8 flex justify-between items-center">
          <div className="flex items-center space-x-4 cursor-pointer group" onClick={() => currentUser ? setState('selection') : setState('home')}>
            <div className="w-14 h-14 bg-gradient-to-br from-yellow-400 to-orange-400 rounded-3xl flex items-center justify-center text-white shadow-xl shadow-orange-100 transform group-hover:scale-110 transition-all">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-8 h-8 animate-pulse">
                <path d="M11.644 1.59a.75.75 0 01.712 0l9.75 5.25a.75.75 0 010 1.32l-9.75 5.25a.75.75 0 01-.712 0l-9.75-5.25a.75.75 0 010-1.32l9.75-5.25z" />
                <path d="M3.265 10.602l7.668 4.129a1.25 1.25 0 001.134 0l7.668-4.13 1.515.815a.75.75 0 010 1.32l-9.75 5.25a.75.75 0 01-.712 0l-9.75-5.25a.75.75 0 010-1.32l1.515-.814z" />
                <path d="M3.265 15.477l7.668 4.129a1.25 1.25 0 001.134 0l7.668-4.13 1.515.815a.75.75 0 010 1.32l-9.75 5.25a.75.75 0 01-.712 0l-9.75-5.25a.75.75 0 010-1.32l1.515-.814z" />
              </svg>
            </div>
            <div className="flex flex-col">
              <h1 className="text-3xl font-black text-slate-800 tracking-tighter leading-none">Super Word Buddy</h1>
              <span className="text-xs font-bold text-orange-400 uppercase tracking-widest mt-1">Akıllı Kelime Arkadaşın</span>
            </div>
          </div>

          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <>
                <div className="hidden md:block mr-2 text-right">
                  <p className="text-sm font-black text-slate-800">Selam, {currentUser.name}!</p>
                  <button onClick={handleLogout} className="text-xs font-bold text-slate-400 hover:text-red-400">Çıkış Yap</button>
                </div>
                <button 
                  onClick={() => setState('upload')} 
                  className={`px-6 py-2.5 rounded-2xl text-sm font-black transition-all ${state === 'upload' ? 'bg-orange-400 text-white shadow-lg shadow-orange-100' : 'text-slate-400 hover:text-slate-600 hover:bg-white'}`}
                >
