                </button>
              </>
            ) : (
              <>
                <button onClick={() => setState('login')} className="text-slate-400 font-black text-sm hover:text-slate-800 transition-all px-4">Giriş Yap</button>
                <button onClick={() => setState('signup')} className="bg-blue-500 text-white px-6 py-2.5 rounded-2xl font-black text-sm hover:bg-blue-600 shadow-lg shadow-blue-100 transition-all">Kayıt Ol</button>
