          onClose={() => { setIsModalOpen(false); setEditingItem(null); }} 
          initialData={editingItem}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User } from '../types';

interface AuthFormProps {
  mode: 'login' | 'signup';
  onAuthSuccess: (user: User) => void;
}

const AuthForm: React.FC<AuthFormProps> = ({ mode, onAuthSuccess }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (mode === 'signup') {
      // Simulate account creation
      const users = JSON.parse(localStorage.getItem('sbuddy_all_users') || '[]');
      if (users.find((u: any) => u.email === email)) {
        setError('Bu e-posta zaten kullanımda! 🎈');
        return;
      }
      const newUser = { id: crypto.randomUUID(), email, password, name };
      users.push(newUser);
      localStorage.setItem('sbuddy_all_users', JSON.stringify(users));
      onAuthSuccess({ id: newUser.id, email: newUser.email, name: newUser.name });
    } else {
      // Simulate login
      const users = JSON.parse(localStorage.getItem('sbuddy_all_users') || '[]');
      const user = users.find((u: any) => u.email === email && u.password === password);
      if (!user) {
        setError('E-posta veya şifre yanlış! 🍭');
        return;
      }
      onAuthSuccess({ id: user.id, email: user.email, name: user.name });
    }
  };

  return (
