              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {vocabItems.map((item) => (
                  <div key={item.id} className="bg-white p-10 rounded-[3.5rem] border border-slate-50 shadow-[0_15px_50px_rgba(0,0,0,0.02)] hover:shadow-2xl transition-all group border-b-8 border-indigo-100 relative overflow-hidden flex flex-col">
                    <div className="absolute top-0 right-0 w-24 h-24 bg-indigo-50/50 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110"></div>
