                        </div>
                        <div className="flex space-x-2">
                           <button onClick={() => handleEditClick(item)} className="p-2 text-slate-300 hover:text-blue-400 transition-colors">
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                              <path strokeLinecap="round" strokeLinejoin="round" d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" />
                            </svg>
                           </button>
                           <button onClick={() => deleteWord(item.id)} className="p-2 text-slate-300 hover:text-red-400 transition-colors">
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                              <path strokeLinecap="round" strokeLinejoin="round" d="M14.74 9l-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 01-2.244 2.077H8.084a2.25 2.25 0 01-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 00-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 013.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 00-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 00-7.5 0" />
                            </svg>
                           </button>
                        </div>
                      </div>

                      <div className="pt-6 border-t border-slate-50 space-y-3">
                        <p className="text-slate-400 italic font-medium leading-relaxed text-lg">"{item.exampleSentence}"</p>
                        <p className="text-sm text-slate-300 font-bold">{item.exampleSentenceTurkish}</p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white/40 py-16 mt-auto border-t border-orange-50">
        <div className="max-w-6xl mx-auto px-8 flex flex-col items-center space-y-6 text-center">
          <div className="w-12 h-12 bg-indigo-400 rounded-2xl flex items-center justify-center text-white text-2xl">🧸</div>
          <p className="text-slate-300 text-sm font-black uppercase tracking-[0.3em]">Super Word Buddy • Senin İçin Sevgiyle Yapıldı</p>
        </div>
      </footer>

      {isModalOpen && (
        <AddWordModal 
          onAdd={addOrUpdateWord} 
          onClose={() => { setIsModalOpen(false); setEditingItem(null); }} 
          initialData={editingItem}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User } from '../types';
import { supabase } from '../services/supabaseClient';

interface AuthFormProps {
  mode: 'login' | 'signup';
  onAuthSuccess: (user: User) => void;
}

const AuthForm: React.FC<AuthFormProps> = ({ mode, onAuthSuccess }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (mode === 'signup') {
        const { data, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: { name }
          }
        });

        if (authError) throw authError;

        if (data.user) {
          onAuthSuccess({
            id: data.user.id,
            email: data.user.email!,
            name: name
          });
        }
      } else {
        const { data, error: authError } = await supabase.auth.signInWithPassword({
          email,
          password,
        });

        if (authError) throw authError;

        if (data.user) {
          onAuthSuccess({
            id: data.user.id,
            email: data.user.email!,
            name: data.user.user_metadata.name || 'Arkadaşım'
          });
        }
      }
    } catch (err: any) {
      setError(err.message || 'Bir hata oluştu. 🍭');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-md mx-auto w-full animate-in fade-in zoom-in-95 duration-500">
      <div className="bg-white rounded-[4rem] p-12 shadow-[0_30px_100px_rgba(0,0,0,0.08)] border-4 border-white">
        <div className="text-center mb-10">
          <div className="text-7xl mb-4">{mode === 'login' ? '🔑' : '🦚'}</div>
          <h2 className="text-4xl font-black text-slate-800 tracking-tight">
            {mode === 'login' ? 'Giriş Yap' : 'Kayıt Ol'}
          </h2>
          <p className="text-slate-400 font-medium mt-2">
            {mode === 'login' ? 'Kelimelerine tekrar kavuş!' : 'Arkadaşınla tanışmak için bilgileri gir.'}
          </p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-50 text-red-500 rounded-2xl text-sm font-bold text-center">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          {mode === 'signup' && (
            <div className="space-y-2">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">Adın</label>
              <input 
                required
                type="text"
                className="w-full bg-slate-50 border-4 border-transparent rounded-[2rem] p-5 focus:border-blue-100 focus:bg-white outline-none text-lg font-bold text-slate-700 transition-all"
                value={name}
                onChange={e => setName(e.target.value)}
                placeholder="Örn: Ela"
              />
            </div>
          )}

          <div className="space-y-2">
            <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">E-posta</label>
            <input 
              required
              type="email"
              className="w-full bg-slate-50 border-4 border-transparent rounded-[2rem] p-5 focus:border-blue-100 focus:bg-white outline-none text-lg font-bold text-slate-700 transition-all"
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="ela@örnek.com"
            />
          </div>

          <div className="space-y-2">
            <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">Şifre</label>
            <input 
              required
              type="password"
              className="w-full bg-slate-50 border-4 border-transparent rounded-[2rem] p-5 focus:border-blue-100 focus:bg-white outline-none text-lg font-bold text-slate-700 transition-all"
              value={password}
              onChange={e => setPassword(e.target.value)}
              placeholder="••••••••"
            />
          </div>

          <button 
            type="submit"
            disabled={loading}
            className="w-full py-6 bg-blue-500 hover:bg-blue-600 text-white rounded-[2.5rem] font-black text-2xl shadow-2xl shadow-blue-100 transition-all mt-6 active:scale-95 disabled:opacity-50"
          >
            {loading ? 'Yükleniyor...' : (mode === 'login' ? 'Giriş Yap' : 'Kayıt Ol')}
          </button>
        </form>
      </div>
    </div>
  );
};

export default AuthForm;

import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  useEffect(() => {
    // Check current session
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Arkadaşım'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      }
    });

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Arkadaşım'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchUserWords = async (userId: string) => {
    const { data, error } = await supabase
      .from('vocabulary')
      .select('*')
      .eq('user_id', userId);

    if (error) {
      console.error('Error fetching words:', error);
      return;
    }

    if (data) {
      const mappedWords: VocabularyItem[] = data.map(item => ({
        id: item.id,
        word: item.word,
        meaning: item.meaning,
        pronunciation: item.pronunciation,
        exampleSentence: item.exampleSentence,
        exampleSentenceTurkish: item.exampleSentenceTurkish,
        category: item.category
      }));
      setVocabItems(mappedWords);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) return;
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);
      if (items.length === 0) {
        throw new Error("Kelimeleri bulamadım 🐣 Lütfen tekrar dene!");
      }

      const wordsToInsert = items.map(item => ({
        user_id: currentUser.id,
        word: item.word,
        meaning: item.meaning,
        pronunciation: item.pronunciation,
        exampleSentence: item.exampleSentence,
        exampleSentenceTurkish: item.exampleSentenceTurkish,
        category: item.category
      }));

      const { data, error: insertError } = await supabase
        .from('vocabulary')
        .insert(wordsToInsert)
        .select();

      if (insertError) throw insertError;

      if (data) {
        fetchUserWords(currentUser.id);
      }

      setState('selection');
    } catch (err) {
      setError("Bir şeyler ters gitti 🍭 Lütfen tekrar yükle.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 4) {
      setError("Test için en az 4 kelime lazım! 🎈");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setError("Oyun hazırlanamadı 🎨");
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;

    if (item.id) {
      const { error } = await supabase
        .from('vocabulary')
        .update({
          word: item.word,
          meaning: item.meaning,
          pronunciation: item.pronunciation,
          exampleSentence: item.exampleSentence,
          exampleSentenceTurkish: item.exampleSentenceTurkish,
          category: item.category
        })
        .eq('id', item.id);
      if (error) console.error(error);
    } else {
      const { error } = await supabase
        .from('vocabulary')
        .insert([{
          user_id: currentUser.id,
          word: item.word,
          meaning: item.meaning,
          pronunciation: item.pronunciation,
          exampleSentence: item.exampleSentence,
          exampleSentenceTurkish: item.exampleSentenceTurkish,
          category: item.category
        }]);
      if (error) console.error(error);
    }

    fetchUserWords(currentUser.id);
    setQuizQuestions([]);
    setEditingItem(null);
  };

  const deleteWord = async (id: string) => {
    if (!currentUser) return;
    const { error } = await supabase
      .from('vocabulary')
      .delete()
      .eq('id', id);

    if (error) {
      console.error(error);
    } else {
      fetchUserWords(currentUser.id);
    }
    setQuizQuestions([]);
  };

  const handleEditClick = (item: VocabularyItem) => {
    setEditingItem(item);
    setIsModalOpen(true);
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-blue-100 selection:text-blue-700">
      {/* Header */}
      <header className="bg-white/70 backdrop-blur-md sticky top-0 z-20 py-6 border-b border-orange-50">
        <div className="max-w-6xl mx-auto px-8 flex justify-between items-center">
          <div className="flex items-center space-x-4 cursor-pointer group" onClick={() => currentUser ? setState('selection') : setState('home')}>
            <div className="w-14 h-14 bg-gradient-to-br from-yellow-400 to-orange-400 rounded-3xl flex items-center justify-center text-white shadow-xl shadow-orange-100 transform group-hover:scale-110 transition-all overflow-hidden relative">
               <div className="absolute inset-0 w-full h-full" style={{ background: 'conic-gradient(#ff5f5f 0deg 90deg, #ffdc5f 90deg 180deg, #5f99ff 180deg 270deg, #ffffff 270deg 360deg)' }}></div>
               <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 bg-white/20 rounded-full blur-sm"></div>
            </div>
            <div className="flex flex-col">
              <h1 className="text-3xl font-black text-slate-800 tracking-tighter leading-none">Super Word Buddy</h1>
              <span className="text-xs font-bold text-orange-400 uppercase tracking-widest mt-1">Akıllı Kelime Arkadaşın</span>
            </div>
          </div>

          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <>
                <div className="hidden md:block mr-2 text-right">
                  <p className="text-sm font-black text-slate-800">Selam, {currentUser.name}!</p>
                  <button onClick={handleLogout} className="text-xs font-bold text-slate-400 hover:text-red-400">Çıkış Yap</button>
                </div>
                <button 
                  onClick={() => setState('upload')} 
                  className={`px-6 py-2.5 rounded-2xl text-sm font-black transition-all ${state === 'upload' ? 'bg-orange-400 text-white shadow-lg shadow-orange-100' : 'text-slate-400 hover:text-slate-600 hover:bg-white'}`}
                >
                  Yükle
                </button>
              </>
            ) : (
              <>
                <button onClick={() => setState('login')} className="text-slate-400 font-black text-sm hover:text-slate-800 transition-all px-4">Giriş Yap</button>
                <button onClick={() => setState('signup')} className="bg-blue-500 text-white px-6 py-2.5 rounded-2xl font-black text-sm hover:bg-blue-600 shadow-lg shadow-blue-100 transition-all">Kayıt Ol</button>
              </>
            )}
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-6xl mx-auto w-full px-8 py-12">
        {error && (
          <div className="mb-8 p-6 bg-red-50 border-4 border-white text-red-500 rounded-[2.5rem] text-center font-black shadow-xl animate-bounce">
            {error}
            <button onClick={() => setError(null)} className="ml-4 text-xs underline">Tamam</button>
          </div>
        )}

        {state === 'home' && (
          <div className="flex flex-col items-center justify-center space-y-12 py-12 text-center">
            {/* Colorful Beach Ball */}
            <div 
              className="w-48 h-48 rounded-full shadow-[0_40px_80px_-15px_rgba(0,0,0,0.15)] animate-bounce relative overflow-hidden ring-8 ring-white"
              style={{ background: 'conic-gradient(#ff5f5f 0deg 90deg, #ffdc5f 90deg 180deg, #5f99ff 180deg 270deg, #ffffff 270deg 360deg)' }}
            >
              <div className="absolute top-[20%] left-[20%] w-12 h-8 bg-white/30 rounded-full blur-md -rotate-45"></div>
            </div>

            <div className="space-y-6 max-w-3xl">
              <h2 className="text-7xl font-black text-slate-800 tracking-tighter leading-tight">
                Kelimelerin <span className="text-yellow-400">Renkli</span> Dünyasına Hoş Geldin!
              </h2>
              <p className="text-2xl text-slate-400 font-medium leading-relaxed">
                Derslerindeki kelimeleri yükle, oyunlarla öğren ve asla unutma. Kayıt ol ve kelime arkadaşın her zaman yanında olsun!
              </p>
            </div>
            <div className="flex space-x-6">
