        <div className="max-w-6xl mx-auto px-8 flex justify-between items-center">
          <div className="flex items-center space-x-4 cursor-pointer group" onClick={() => currentUser ? setState('selection') : setState('home')}>
            {/* Beach Ball Logo */}
            <div className="w-14 h-14 bg-gradient-to-br from-yellow-400 to-orange-400 rounded-3xl flex items-center justify-center text-white shadow-xl shadow-orange-100 transform group-hover:scale-110 transition-all overflow-hidden relative">
               <div className="absolute inset-0 w-full h-full" style={{ background: 'conic-gradient(#ff5f5f 0deg 90deg, #ffdc5f 90deg 180deg, #5f99ff 180deg 270deg, #ffffff 270deg 360deg)' }}></div>
               <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 bg-white/40 rounded-full blur-[2px]"></div>
            </div>
            <div className="flex flex-col">
              <h1 className="text-3xl font-black text-slate-800 tracking-tighter leading-none">Super Word Buddy</h1>
              <span className="text-xs font-bold text-orange-400 uppercase tracking-widest mt-1">Akıllı Kelime Arkadaşın</span>
            </div>
          </div>

          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <>
                <div className="hidden md:block mr-2 text-right">
                  <p className="text-sm font-black text-slate-800">Selam, {currentUser.name}!</p>
                  <button onClick={handleLogout} className="text-xs font-bold text-slate-400 hover:text-red-400">Çıkış Yap</button>
                </div>
                <button 
                  onClick={() => setState('upload')} 
                  className={`px-6 py-2.5 rounded-2xl text-sm font-black transition-all ${state === 'upload' ? 'bg-orange-400 text-white shadow-lg shadow-orange-100' : 'text-slate-400 hover:text-slate-600 hover:bg-white'}`}
                >
                  Yükle
                </button>
              </>
            ) : (
              <>
                <button onClick={() => setState('login')} className="text-slate-400 font-black text-sm hover:text-slate-800 transition-all px-4">Giriş Yap</button>
                <button onClick={() => setState('signup')} className="bg-blue-500 text-white px-6 py-2.5 rounded-2xl font-black text-sm hover:bg-blue-600 shadow-lg shadow-blue-100 transition-all">Kayıt Ol</button>
