import { GoogleGenAI, Type } from "@google/genai";
import { VocabularyItem } from "../types";

export const analyzeVocabulary = async (base64Data: string, mimeType: string): Promise<VocabularyItem[]> => {
  // MUST use this exact initialization
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Aşağıdaki dosyayı (görsel veya PDF) çok dikkatli incele. 
    İçindeki TÜM İngilizce kelimeleri, terimleri ve ifadeleri çıkar.
    Her bir kelime için şu bilgileri sağla:
    1. Kelimenin Türkçe anlamı.
    2. Okunuşu (pronunciation).
    3. 9 yaşında bir çocuğun anlayabileceği seviyede kısa bir İngilizce örnek cümle.
    4. Bu örnek cümlenin Türkçe çevirisi.
    5. Kelime türü (Noun, Verb, Adjective vb.).

    ÖNEMLİ: Yanıtı sadece saf JSON formatında döndür. Boşlukları veya gereksiz metinleri dahil etme.
    Maksimum 50 kelime çıkar.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              meaning: { type: Type.STRING },
              pronunciation: { type: Type.STRING },
              exampleSentence: { type: Type.STRING },
              exampleSentenceTurkish: { type: Type.STRING },
              category: { type: Type.STRING }
            },
            required: ["word", "meaning", "pronunciation", "exampleSentence", "exampleSentenceTurkish", "category"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];

    const parsed = JSON.parse(text);
    return (Array.isArray(parsed) ? parsed : []) as VocabularyItem[];
  } catch (error) {
    console.error("Gemini Analiz Hatası:", error);
    throw new Error("Dosya analiz edilirken bir hata oluştu. Lütfen dosyanın net ve okunur olduğundan emin olun.");
  }
};

export const generateQuiz = async (words: VocabularyItem[]): Promise<any[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const subset = [...words].sort(() => Math.random() - 0.5).slice(0, 10);

  const prompt = `Aşağıdaki kelimelerle ilgili 10 adet çoktan seçmeli İngilizce kelime sorusu hazırla: ${JSON.stringify(subset)}.
  Her soru için 4 şık ve bir doğru cevap belirt. Çocuklar için eğlenceli ve basit olsun.
  Yanıtı JSON array formatında ver.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Quiz Üretim Hatası:", error);
    return [];
  }
};

import React, { useState, useRef } from 'react';

interface FileUploadProps {
  onFileSelect: (base64: string, mimeType: string) => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect }) => {
  const [dragActive, setDragActive] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFile = (file: File) => {
    if (!file) return;

    // Check if file is of supported type
    const supportedTypes = ['image/jpeg', 'image/png', 'application/pdf'];
    if (!supportedTypes.includes(file.type)) {
      alert("Lütfen sadece JPG, PNG veya PDF dosyası yükleyin! 🎈");
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const result = e.target?.result as string;
      if (result && result.includes(',')) {
        const base64 = result.split(',')[1];
        onFileSelect(base64, file.type);
      }
    };
    reader.onerror = () => {
      console.error("Dosya okuma hatası");
    };
    reader.readAsDataURL(file);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFile(e.target.files[0]);
    }
  };

  const onButtonClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    inputRef.current?.click();
  };

  return (
    <div 
      onDragOver={(e) => { e.preventDefault(); setDragActive(true); }}
      onDragLeave={() => setDragActive(false)}
      onDrop={(e) => { e.preventDefault(); setDragActive(false); if (e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]); }}
      onClick={onButtonClick}
      className={`relative w-full max-w-2xl mx-auto p-16 border-4 border-dashed rounded-[3rem] transition-all duration-300 flex flex-col items-center justify-center space-y-6 cursor-pointer group ${
        dragActive ? 'border-indigo-500 bg-indigo-50/50 scale-[1.02]' : 'border-slate-200 bg-white hover:border-indigo-300 hover:bg-slate-50/50 shadow-xl shadow-slate-100/50'
      }`}
    >
      <div className="w-20 h-20 bg-indigo-100 rounded-[2rem] flex items-center justify-center text-indigo-600 group-hover:scale-110 transition-transform">
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-10 h-10">
          <path strokeLinecap="round" strokeLinejoin="round" d="M12 16.5V9.75m0 0l3 3m-3-3l-3 3M6.75 19.5a4.5 4.5 0 01-1.41-8.775 5.25 5.25 0 0110.233-2.33 3 3 0 013.758 3.848A3.752 3.752 0 0118 19.5H6.75z" />
        </svg>
      </div>
      <div className="text-center space-y-2">
        <h3 className="text-2xl font-black text-slate-800">Ders Notlarını Yükle</h3>
        <p className="text-slate-500 text-lg font-medium max-w-sm mx-auto">
          Görsel veya PDF dosyasını yüklemek için tıkla ya da buraya sürükle bırak!
        </p>
      </div>
      <div className="bg-indigo-600 text-white px-10 py-4 rounded-2xl font-black text-lg transition-colors shadow-lg shadow-indigo-100 group-hover:bg-indigo-700">
        Dosya Seç
      </div>
      <input 
        ref={inputRef}
        type="file" 
        className="hidden" 
        accept="image/jpeg,image/png,application/pdf" 
        onChange={handleChange} 
      />
      <div className="flex space-x-3 items-center">
         <span className="bg-slate-100 px-3 py-1 rounded-lg text-xs font-black text-slate-400">JPG</span>
         <span className="bg-slate-100 px-3 py-1 rounded-lg text-xs font-black text-slate-400">PNG</span>
         <span className="bg-slate-100 px-3 py-1 rounded-lg text-xs font-black text-slate-400">PDF</span>
      </div>
    </div>
  );
};

