const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  useEffect(() => {
    // Check current session
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Arkadaşım'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      }
    });

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Arkadaşım'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchUserWords = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .eq('user_id', userId);

      if (error) throw error;

      if (data) {
        const mappedWords: VocabularyItem[] = data.map(item => ({
          id: item.id,
          word: item.word,
          meaning: item.meaning,
          pronunciation: item.pronunciation,
          exampleSentence: item.exampleSentence,
          exampleSentenceTurkish: item.exampleSentenceTurkish,
          category: item.category
        }));
        setVocabItems(mappedWords);
      }
    } catch (err) {
      console.error('Error fetching words:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) {
      setError("Lütfen önce giriş yapın! 🍭");
      return;
    }
    setState('analyzing');
    setError(null);
    try {
      console.log(`Analyzing file of type: ${mimeType}`);
      const items = await analyzeVocabulary(base64, mimeType);

      if (!items || items.length === 0) {
        throw new Error("Yapay zeka bu dosyada hiç kelime bulamadı. 🐣 Lütfen görselin net olduğundan emin ol!");
      }

      const wordsToInsert = items.map(item => ({
        user_id: currentUser.id,
        word: item.word,
        meaning: item.meaning,
        pronunciation: item.pronunciation,
        exampleSentence: item.exampleSentence,
        exampleSentenceTurkish: item.exampleSentenceTurkish,
        category: item.category
      }));

      // Supabase insertion
      const { data, error: insertError } = await supabase
        .from('vocabulary')
        .insert(wordsToInsert)
        .select();

      if (insertError) {
        console.error("Supabase insert error:", insertError);
        throw new Error(`Kayıt sırasında bir hata oluştu: ${insertError.message}`);
      }

      if (data) {
        await fetchUserWords(currentUser.id);
      }

      setState('selection');
    } catch (err: any) {
      console.error("File processing error:", err);
      setError(err.message || "Dosya işlenirken bir sorun oluştu 🍭 Lütfen tekrar deneyin.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 4) {
      setError("Test için en az 4 kelime lazım! 🎈");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setError("Oyun hazırlanamadı 🎨");
      setState('selection');
    }
