  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;

    try {
      if (item.id) {
        const { error } = await supabase
          .from('vocabulary')
          .update({
            word: item.word,
            meaning: item.meaning,
            pronunciation: item.pronunciation,
            exampleSentence: item.exampleSentence,
            exampleSentenceTurkish: item.exampleSentenceTurkish,
            category: item.category
          })
          .eq('id', item.id);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('vocabulary')
          .insert([{
            user_id: currentUser.id,
            word: item.word,
            meaning: item.meaning,
            pronunciation: item.pronunciation,
            exampleSentence: item.exampleSentence,
            exampleSentenceTurkish: item.exampleSentenceTurkish,
            category: item.category
          }]);
        if (error) throw error;
      }

      fetchUserWords(currentUser.id);
      setQuizQuestions([]);
      setEditingItem(null);
    } catch (err: any) {
      setError("Kelime kaydedilemedi: " + err.message);
    }
  };

  const deleteWord = async (id: string) => {
    if (!currentUser) return;
    const { error } = await supabase
      .from('vocabulary')
      .delete()
      .eq('id', id);

    if (error) {
      console.error(error);
    } else {
      fetchUserWords(currentUser.id);
    }
    setQuizQuestions([]);
  };

  const handleEditClick = (item: VocabularyItem) => {
    setEditingItem(item);
    setIsModalOpen(true);
  };

