import { GoogleGenAI, Type } from "@google/genai";
import { VocabularyItem } from "../types";

export const analyzeVocabulary = async (base64Data: string, mimeType: string): Promise<VocabularyItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // prompt optimize edildi ve şemadaki 'category' kaldırıldı
  const prompt = `
    Aşağıdaki görsel veya PDF dokümanını bir İngilizce öğretmeni titizliğiyle incele.
    Doküman içerisindeki önemli İngilizce kelimeleri ve ifadeleri tespit et.
    Her bir kelime için şu bilgileri eksiksiz hazırla:
    1. word: Kelimenin kendisi (İngilizce).
    2. meaning: Kelimenin Türkçe anlamı.
    3. pronunciation: Kelimenin fonetik okunuşu (Örn: /apple/).
    4. exampleSentence: Kelimeyi içeren, günlük hayattan kısa bir İngilizce örnek cümle.
    5. exampleSentenceTurkish: Bu örnek cümlenin doğal bir Türkçe çevirisi.

    Yanıtı sadece belirtilen JSON formatında döndür. Maksimum 30 kelime çıkar.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              meaning: { type: Type.STRING },
              pronunciation: { type: Type.STRING },
              exampleSentence: { type: Type.STRING },
              exampleSentenceTurkish: { type: Type.STRING }
            },
            required: ["word", "meaning", "pronunciation", "exampleSentence", "exampleSentenceTurkish"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];

    const parsed = JSON.parse(text);
    return (Array.isArray(parsed) ? parsed : []) as VocabularyItem[];
  } catch (error) {
    console.error("Gemini Analiz Hatası:", error);
    throw new Error("Dosya analiz edilirken bir hata oluştu. Lütfen dosyanın net bir fotoğraf veya PDF olduğundan emin ol.");
  }
};

export const generateQuiz = async (words: VocabularyItem[]): Promise<any[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const subset = [...words].sort(() => Math.random() - 0.5).slice(0, 10);

  const prompt = `Aşağıdaki kelimelerle ilgili eğlenceli, çoktan seçmeli 10 soru hazırla: ${JSON.stringify(subset)}.
  JSON formatında döndür.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Quiz Üretim Hatası:", error);
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Arkadaşım'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Arkadaşım'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchUserWords = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .eq('user_id', userId);

      if (error) throw error;

      if (data) {
        const mappedWords: VocabularyItem[] = data.map(item => ({
          id: item.id,
          word: item.word,
          meaning: item.meaning,
          pronunciation: item.pronunciation,
          exampleSentence: item.exampleSentence,
          exampleSentenceTurkish: item.exampleSentenceTurkish
        }));
        setVocabItems(mappedWords);
      }
    } catch (err) {
      console.error('Error fetching words:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) {
      setError("Lütfen önce giriş yapın! 🍭");
      return;
    }
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);

      if (!items || items.length === 0) {
        throw new Error("Hiç kelime bulunamadı. Lütfen görselin net olduğundan emin ol!");
      }

      const wordsToInsert = items.map(item => ({
        user_id: currentUser.id,
        word: item.word,
        meaning: item.meaning,
        pronunciation: item.pronunciation,
        exampleSentence: item.exampleSentence,
        exampleSentenceTurkish: item.exampleSentenceTurkish
      }));

      const { data, error: insertError } = await supabase
        .from('vocabulary')
        .insert(wordsToInsert)
        .select();

      if (insertError) {
        throw new Error(`Veritabanı hatası: ${insertError.message}`);
      }

      if (data) {
        await fetchUserWords(currentUser.id);
      }

      setState('selection');
    } catch (err: any) {
      console.error("Hata:", err);
      setError(err.message || "Bir sorun oluştu. Lütfen tekrar dene.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 4) {
      setError("Test için en az 4 kelime lazım! 🎈");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setError("Oyun hazırlanamadı 🎨");
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;

    try {
      const payload = {
        word: item.word,
        meaning: item.meaning,
        pronunciation: item.pronunciation,
        exampleSentence: item.exampleSentence,
        exampleSentenceTurkish: item.exampleSentenceTurkish
      };

      if (item.id) {
        const { error } = await supabase
          .from('vocabulary')
          .update(payload)
          .eq('id', item.id);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('vocabulary')
          .insert([{ ...payload, user_id: currentUser.id }]);
        if (error) throw error;
      }

      fetchUserWords(currentUser.id);
      setEditingItem(null);
    } catch (err: any) {
      setError("Kaydedilemedi: " + err.message);
    }
  };

  const deleteWord = async (id: string) => {
    if (!currentUser) return;
