export default App;

import React, { useState, useEffect } from 'react';
import { VocabularyItem } from '../types';

interface AddWordModalProps {
  onAdd: (item: VocabularyItem) => void;
  onClose: () => void;
  initialData?: VocabularyItem | null;
}

const AddWordModal: React.FC<AddWordModalProps> = ({ onAdd, onClose, initialData }) => {
  const [formData, setFormData] = useState<Partial<VocabularyItem>>({
    word: '',
    meaning: '',
    pronunciation: '',
    exampleSentence: '',
    exampleSentenceTurkish: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    }
  }, [initialData]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.word || !formData.meaning) return;
    onAdd(formData as VocabularyItem);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-xl rounded-[4rem] shadow-3xl p-12 border-4 border-white animate-in zoom-in-95 duration-300 relative overflow-hidden">
        <div className="absolute -top-10 -left-10 w-40 h-40 bg-blue-50 rounded-full opacity-50"></div>
        <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-yellow-50 rounded-full opacity-50"></div>

        <div className="relative z-10">
          <div className="flex justify-between items-center mb-10">
            <h2 className="text-4xl font-black text-slate-800 tracking-tight">
              {initialData ? 'Düzenle ✏️' : 'Yeni Kelime 🎨'}
            </h2>
            <button onClick={onClose} className="bg-slate-50 text-slate-400 hover:text-slate-600 p-3 rounded-full hover:bg-slate-100 transition-all">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">İngilizcesi</label>
                <input 
                  required
                  className="w-full bg-slate-50 border-4 border-transparent rounded-[2rem] p-5 focus:border-blue-100 focus:bg-white outline-none text-xl font-bold text-slate-700 transition-all"
                  value={formData.word}
                  onChange={e => setFormData({...formData, word: e.target.value})}
                  placeholder="Apple"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">Okunuşu</label>
                <input 
                  className="w-full bg-slate-50 border-4 border-transparent rounded-[2rem] p-5 focus:border-blue-100 focus:bg-white outline-none text-xl font-bold text-slate-700 transition-all"
                  value={formData.pronunciation}
                  onChange={e => setFormData({...formData, pronunciation: e.target.value})}
                  placeholder="/æpl/"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">Türkçe Anlamı</label>
              <input 
                required
                className="w-full bg-slate-50 border-4 border-transparent rounded-[2rem] p-5 focus:border-blue-100 focus:bg-white outline-none text-xl font-bold text-slate-700 transition-all"
                value={formData.meaning}
                onChange={e => setFormData({...formData, meaning: e.target.value})}
                placeholder="Elma"
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">Örnek Cümle (İngilizce)</label>
              <input 
                className="w-full bg-slate-50 border-4 border-transparent rounded-[2rem] p-5 focus:border-blue-100 focus:bg-white outline-none text-lg font-medium text-slate-700 transition-all"
                value={formData.exampleSentence}
                onChange={e => setFormData({...formData, exampleSentence: e.target.value})}
                placeholder="I like eating red apples."
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-4">Cümle Çevirisi</label>
              <input 
                className="w-full bg-slate-50 border-4 border-transparent rounded-[2rem] p-5 focus:border-blue-100 focus:bg-white outline-none text-lg font-medium text-slate-700 transition-all"
                value={formData.exampleSentenceTurkish}
                onChange={e => setFormData({...formData, exampleSentenceTurkish: e.target.value})}
                placeholder="Kırmızı elma yemeyi severim."
              />
            </div>

            <button 
              type="submit"
              className="w-full py-6 bg-blue-500 hover:bg-blue-600 text-white rounded-[2.5rem] font-black text-2xl shadow-2xl shadow-blue-100 transition-all mt-6 active:scale-95"
            >
              {initialData ? 'Güncelle ✨' : 'Listeme Ekle! 🌈'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

