               <div className="absolute inset-0 w-full h-full" style={{ background: 'conic-gradient(#ff5f5f 0deg 90deg, #ffdc5f 90deg 180deg, #5f99ff 180deg 270deg, #ffffff 270deg 360deg)' }}></div>
