import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Arkadaşım'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Arkadaşım'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchUserWords = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false });

      if (error) throw error;

      if (data) {
        const mappedWords: VocabularyItem[] = data.map(item => ({
          id: item.id,
          word: item.word,
          meaning: item.meaning,
          pronunciation: item.pronunciation,
          exampleSentence: item.example_sentence || '',
          // Try both variants for backward compatibility
          exampleSentenceTurkish: item.example_sentence_tr || item.example_sentence_turkish || ''
        }));
        setVocabItems(mappedWords);
      }
    } catch (err: any) {
      console.error('Error fetching words:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) {
      setError("Lütfen önce giriş yapın! 🍭");
      return;
    }
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);

      if (!items || items.length === 0) {
        throw new Error("Dokümanda kelime bulamadım. Lütfen görselin net olduğundan emin ol!");
      }

      // Mapping for Supabase using 'example_sentence_tr' as the likely correct column name
      const wordsToInsert = items.map(item => ({
        user_id: currentUser.id,
        word: item.word,
        meaning: item.meaning,
        pronunciation: item.pronunciation,
        example_sentence: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish 
      }));

      const { data, error: insertError } = await supabase
        .from('vocabulary')
        .insert(wordsToInsert)
        .select();

      if (insertError) {
        // Fallback: If it fails, maybe the column name is still wrong, show a clearer error
        console.error("Supabase Insert Error:", insertError);
        throw new Error(`Kayıt hatası: ${insertError.message}. Veritabanı sütun isimleri uyumsuz görünüyor.`);
      }

      if (data) {
        await fetchUserWords(currentUser.id);
      }

      setState('selection');
    } catch (err: any) {
      console.error("Hata Detayı:", err);
      setError(err.message || "Bir sorun oluştu. Lütfen tekrar dene.");
      setState('upload');
    }
