import { GoogleGenAI, Type } from "@google/genai";
import { VocabularyItem } from "../types";

export const analyzeVocabulary = async (base64Data: string, mimeType: string): Promise<VocabularyItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Sen bir akademik İngilizce uzmanısın. Aşağıdaki dokümanı (Görsel veya PDF) analiz et.
    19 yaşındaki bir üniversite öğrencisinin dil gelişimine katkı sağlayacak en önemli kelimeleri seç.

    Her kelime için şunları hazırla:
    - word: Kelimenin İngilizce hali.
    - meaning: Kelimenin tam Türkçe karşılığı.
    - pronunciation: Fonetik okunuş (Örn: /kənˈtɛmpərəri/).
    - exampleSentence: Kelimeyi içeren akademik veya günlük düzgün bir İngilizce cümle.
    - exampleSentenceTurkish: Bu cümlenin doğal Türkçe çevirisi.

    Yanıtı sadece saf JSON formatında (ARRAY) döndür. Maksimum 20 kaliteli kelime seç.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              meaning: { type: Type.STRING },
              pronunciation: { type: Type.STRING },
              exampleSentence: { type: Type.STRING },
              exampleSentenceTurkish: { type: Type.STRING }
            },
            required: ["word", "meaning", "pronunciation", "exampleSentence", "exampleSentenceTurkish"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];

    const parsed = JSON.parse(text);
    return (Array.isArray(parsed) ? parsed : []) as VocabularyItem[];
  } catch (error) {
    console.error("Gemini Analiz Hatası:", error);
    throw new Error("Doküman analiz edilemedi. Lütfen net bir dosya yüklediğinden emin ol.");
  }
};

export const generateQuiz = async (words: VocabularyItem[]): Promise<any[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const subset = [...words].sort(() => Math.random() - 0.5).slice(0, 10);

  const prompt = `Aşağıdaki kelimelerle ilgili üniversite seviyesinde 10 adet çoktan seçmeli soru hazırla. JSON döndür: ${JSON.stringify(subset)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
