        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchUserWords = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false });

      if (error) throw error;

      if (data) {
        const mappedWords: VocabularyItem[] = data.map(item => {
          // Veritabanından okurken birleştirilmiş veriyi tekrar ayırmaya çalışıyoruz
          const fullExample = item.example_sentence || '';
          const parts = fullExample.split(' / ');
          return {
            id: item.id,
            word: item.word,
            meaning: item.meaning,
            pronunciation: item.pronunciation,
            exampleSentence: parts[0] || '',
            exampleSentenceTurkish: parts[1] || ''
          };
        });
        setVocabItems(mappedWords);
      }
    } catch (err: any) {
      console.error('Fetch Error:', err);
    }
  };

  const handleLogout = async () => {
