  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) {
      setError("Lütfen giriş yapın.");
      return;
    }
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);

      if (!items || items.length === 0) {
        throw new Error("Hiç kelime bulunamadı.");
      }

      // SÜTUN HATALARINI ÖNLEMEK İÇİN: 
      // Sadece word, meaning, pronunciation ve example_sentence kullanıyoruz.
      // Cümlenin Türkçesini 'example_sentence' içine gömüyoruz.
      const wordsToInsert = items.map(item => ({
        user_id: currentUser.id,
        word: item.word,
        meaning: item.meaning,
        pronunciation: item.pronunciation,
        example_sentence: `${item.exampleSentence} / ${item.exampleSentenceTurkish}`
      }));

      const { data, error: insertError } = await supabase
        .from('vocabulary')
        .insert(wordsToInsert)
        .select();

      if (insertError) {
        // Eğer hala hata veriyorsa, en temel sütunlarla (word, meaning) tekrar dene
        console.warn("Kayıt denemesi başarısız, temel sütunlarla tekrar deneniyor...");
        const fallbackInsert = items.map(item => ({
          user_id: currentUser.id,
          word: item.word,
          meaning: item.meaning
        }));
        const { error: fallbackError } = await supabase.from('vocabulary').insert(fallbackInsert);
        if (fallbackError) throw fallbackError;
      }

      await fetchUserWords(currentUser.id);
      setState('selection');
    } catch (err: any) {
      setError(err.message || "Bir hata oluştu.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 4) {
      setError("Test için en az 4 kelime lazım!");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;

    try {
      const payload = {
        word: item.word,
        meaning: item.meaning,
        pronunciation: item.pronunciation,
        example_sentence: `${item.exampleSentence} / ${item.exampleSentenceTurkish}`
      };

      if (item.id) {
        await supabase.from('vocabulary').update(payload).eq('id', item.id);
      } else {
        await supabase.from('vocabulary').insert([{ ...payload, user_id: currentUser.id }]);
      }

      fetchUserWords(currentUser.id);
      setEditingItem(null);
      setIsModalOpen(false);
    } catch (err: any) {
      setError("Kayıt hatası: " + err.message);
    }
  };

  const deleteWord = async (id: string) => {
    if (!currentUser) return;
    await supabase.from('vocabulary').delete().eq('id', id);
    fetchUserWords(currentUser.id);
  };

  const handleEditClick = (item: VocabularyItem) => {
    setEditingItem(item);
    setIsModalOpen(true);
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-indigo-100">
      <header className="bg-white/80 backdrop-blur-md sticky top-0 z-20 py-6 border-b border-slate-100">
        <div className="max-w-6xl mx-auto px-8 flex justify-between items-center">
          <div className="flex items-center space-x-4 cursor-pointer" onClick={() => currentUser ? setState('selection') : setState('home')}>
            <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-indigo-100">🚀</div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tighter">Super Word Buddy</h1>
          </div>

          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <>
                <div className="hidden md:block mr-2 text-right">
                  <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Öğrenci</p>
                  <p className="text-sm font-bold text-slate-800">{currentUser.name}</p>
                </div>
                <button onClick={() => setState('upload')} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-sm font-black shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all">Yükle</button>
                <button onClick={handleLogout} className="text-slate-400 hover:text-red-500 transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 9V5.25A2.25 2.25 0 0013.5 3h-6a2.25 2.25 0 00-2.25 2.25v13.5A2.25 2.25 0 007.5 21h6a2.25 2.25 0 002.25-2.25V15m3 0l3-3m0 0l-3-3m3 3H9" />
                  </svg>
                </button>
              </>
            ) : (
              <button onClick={() => setState('login')} className="bg-slate-800 text-white px-6 py-2 rounded-xl text-sm font-black">Giriş Yap</button>
            )}
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full px-8 py-12">
        {error && (
          <div className="mb-8 p-6 bg-red-50 border-2 border-red-100 text-red-600 rounded-3xl text-center font-bold animate-pulse">
            {error}
            <button onClick={() => setError(null)} className="ml-4 underline">Kapat</button>
          </div>
        )}

        {state === 'home' && (
          <div className="flex flex-col items-center justify-center space-y-12 py-20 text-center">
            <div className="w-40 h-40 bg-gradient-to-tr from-indigo-500 to-purple-500 rounded-[3rem] shadow-2xl flex items-center justify-center text-7xl animate-bounce">🎓</div>
            <div className="space-y-4">
              <h2 className="text-6xl font-black text-slate-800 tracking-tighter">İngilizceyi <span className="text-indigo-600">Akıllıca</span> Öğren</h2>
              <p className="text-xl text-slate-400 max-w-xl mx-auto">Üniversite notlarını yükle, Gemini 3 Flash ile analiz et, oyunlarla pekiştir.</p>
            </div>
            <button onClick={() => setState('signup')} className="bg-indigo-600 text-white px-12 py-5 rounded-3xl text-xl font-black shadow-2xl shadow-indigo-200 hover:scale-105 transition-all">Hemen Başla! 🚀</button>
          </div>
        )}

        {(state === 'login' || state === 'signup') && (
          <AuthForm mode={state} onAuthSuccess={(user) => { setCurrentUser(user); setState('selection'); }} onToggleMode={(newMode) => setState(newMode)} />
        )}

        {state === 'upload' && <FileUpload onFileSelect={handleFileSelect} />}

        {state === 'analyzing' && (
          <div className="flex flex-col items-center justify-center py-32 space-y-8">
            <div className="w-20 h-20 border-8 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <h3 className="text-3xl font-black text-slate-800">Doküman İnceleniyor...</h3>
            <p className="text-slate-400">Gemini 3 Flash senin için kelimeleri ayıklıyor.</p>
          </div>
        )}

        {state === 'selection' && (
          <div className="space-y-12 animate-in fade-in slide-in-from-bottom-8 duration-500">
            <div className="text-center">
              <h2 className="text-5xl font-black text-slate-800">Hoş Geldin, {currentUser?.name}!</h2>
              <p className="text-slate-400 text-lg mt-2">Bugün hangi kelimeleri fethedeceğiz?</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div onClick={() => vocabItems.length > 0 ? setState('learning') : setState('upload')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer group">
                <div className="w-14 h-14 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-2xl mb-6 group-hover:scale-110 transition-transform">🎴</div>
                <h3 className="text-xl font-black text-slate-800">Kartlar</h3>
                <p className="text-slate-400 text-sm mt-1">Anlamları gör ve dinle.</p>
              </div>
              <div onClick={() => vocabItems.length >= 4 ? startQuiz() : setError("En az 4 kelime lazım!")} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer group">
                <div className="w-14 h-14 bg-green-50 text-green-600 rounded-2xl flex items-center justify-center text-2xl mb-6 group-hover:scale-110 transition-transform">🎯</div>
                <h3 className="text-xl font-black text-slate-800">Test Çöz</h3>
                <p className="text-slate-400 text-sm mt-1">Kendini dene.</p>
              </div>
              <div onClick={() => vocabItems.length > 0 ? setState('writing') : setState('upload')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer group">
                <div className="w-14 h-14 bg-purple-50 text-purple-600 rounded-2xl flex items-center justify-center text-2xl mb-6 group-hover:scale-110 transition-transform">✍️</div>
                <h3 className="text-xl font-black text-slate-800">Yazma</h3>
                <p className="text-slate-400 text-sm mt-1">Hatasız yazmayı öğren.</p>
              </div>
              <div onClick={() => setState('list')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer group">
                <div className="w-14 h-14 bg-orange-50 text-orange-600 rounded-2xl flex items-center justify-center text-2xl mb-6 group-hover:scale-110 transition-transform">📋</div>
                <h3 className="text-xl font-black text-slate-800">Kelime Listem</h3>
                <p className="text-slate-400 text-sm mt-1">Hepsini gör ve düzenle.</p>
              </div>
            </div>
          </div>
        )}

        {state === 'learning' && <Flashcards items={shuffleArray(vocabItems)} onComplete={() => setState('selection')} />}
        {state === 'quiz' && <Quiz questions={quizQuestions} onClose={() => setState('selection')} />}
        {state === 'writing' && <WordWriting items={shuffleArray(vocabItems)} onClose={() => setState('selection')} />}

        {state === 'list' && (
          <div className="space-y-8">
            <div className="flex justify-between items-center">
              <h2 className="text-4xl font-black text-slate-800">Kütüphanem 📚</h2>
              <button onClick={() => setState('selection')} className="bg-slate-100 px-6 py-2 rounded-xl font-bold">Geri</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {vocabItems.map((item) => (
                <div key={item.id} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-md transition-all">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h4 className="text-2xl font-black text-slate-800">{item.word}</h4>
                      <p className="text-indigo-600 font-bold">{item.meaning}</p>
                    </div>
                    <div className="flex space-x-1">
                      <button onClick={() => handleEditClick(item)} className="p-2 hover:bg-slate-50 rounded-lg">✏️</button>
                      <button onClick={() => deleteWord(item.id)} className="p-2 hover:bg-red-50 rounded-lg">🗑️</button>
                    </div>
                  </div>
                  <p className="text-slate-400 text-sm italic">"{item.exampleSentence}"</p>
                  <p className="text-slate-300 text-xs mt-1">{item.exampleSentenceTurkish}</p>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {isModalOpen && <AddWordModal onAdd={addOrUpdateWord} onClose={() => { setIsModalOpen(false); setEditingItem(null); }} initialData={editingItem} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // Veritabanındaki paketlenmiş veriyi çözen yardımcı fonksiyon
  const parseDatabaseItem = (item: any): VocabularyItem => {
    const fullText = item.example_sentence || '';

    // Eğer veri [Anlam: ...] [Okunuş: ...] formatındaysa parçalara ayır
    let meaning = item.meaning || '';
    let pronunciation = item.pronunciation || '';
    let sentence = fullText;
    let sentenceTr = '';

    if (fullText.includes('[Anlam:')) {
      const mMatch = fullText.match(/\[Anlam:\s*(.*?)\s*\]/);
      const pMatch = fullText.match(/\[Okunuş:\s*(.*?)\s*\]/);
      const sMatch = fullText.split('] ').pop()?.split(' / ');

      if (mMatch) meaning = mMatch[1];
      if (pMatch) pronunciation = pMatch[1];
      if (sMatch) {
        sentence = sMatch[0] || '';
        sentenceTr = sMatch[1] || '';
      }
    } else if (fullText.includes(' / ')) {
      const parts = fullText.split(' / ');
      sentence = parts[0];
      sentenceTr = parts[1];
    }

    return {
      id: item.id,
      word: item.word,
      meaning: meaning,
      pronunciation: pronunciation,
      exampleSentence: sentence,
      exampleSentenceTurkish: sentenceTr
    };
  };

  const fetchUserWords = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        setVocabItems(data.map(parseDatabaseItem));
      }
    } catch (err: any) {
      console.error('Veri çekme hatası:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  // Veritabanına en güvenli şekilde kayıt yapan fonksiyon
  const resilientInsert = async (items: VocabularyItem[], userId: string) => {
    // Tüm bilgileri 'word' ve 'example_sentence' içinde paketliyoruz. 
    // Bu iki sütun hemen hemen her veritabanında mevcuttur.
    const payloads = items.map(item => ({
      user_id: userId,
      word: item.word,
      // Tüm ek bilgileri tek bir sütuna (example_sentence) gömüyoruz
      example_sentence: `[Anlam: ${item.meaning}] [Okunuş: ${item.pronunciation}] ${item.exampleSentence} / ${item.exampleSentenceTurkish}`
    }));

    const { error } = await supabase.from('vocabulary').insert(payloads);
    if (error) {
      console.error("İlk kayıt denemesi başarısız, sadece temel verilerle deneniyor:", error);
      // Eğer o da başarısız olursa sadece kelimeyi kaydetmeyi dene
      const basicPayloads = items.map(item => ({
        user_id: userId,
        word: `${item.word} (${item.meaning})`,
        example_sentence: item.exampleSentence
      }));
      const { error: secondError } = await supabase.from('vocabulary').insert(basicPayloads);
      if (secondError) throw secondError;
    }
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) {
      setError("Lütfen önce giriş yapın! 🍭");
      return;
    }
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);
      if (!items || items.length === 0) throw new Error("Kelime bulunamadı.");

      await resilientInsert(items, currentUser.id);
      await fetchUserWords(currentUser.id);
      setState('selection');
    } catch (err: any) {
      setError("Kaydedilemedi. Veritabanı sütunlarınız eksik olabilir ama sistemi düzelttim, tekrar deneyin!");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 4) {
      setError("Test için en az 4 kelime lazım!");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;
    try {
      const packedSentence = `[Anlam: ${item.meaning}] [Okunuş: ${item.pronunciation}] ${item.exampleSentence} / ${item.exampleSentenceTurkish}`;
      const payload = {
        word: item.word,
        example_sentence: packedSentence
      };

      if (item.id) {
        await supabase.from('vocabulary').update(payload).eq('id', item.id);
      } else {
        await supabase.from('vocabulary').insert([{ ...payload, user_id: currentUser.id }]);
      }

      fetchUserWords(currentUser.id);
      setEditingItem(null);
      setIsModalOpen(false);
    } catch (err: any) {
      setError("Kayıt hatası: " + err.message);
    }
  };

  const deleteWord = async (id: string) => {
    if (!currentUser) return;
    await supabase.from('vocabulary').delete().eq('id', id);
    fetchUserWords(currentUser.id);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#fdfbf7]">
      <header className="bg-white/80 backdrop-blur-md sticky top-0 z-20 py-6 border-b border-slate-100">
        <div className="max-w-6xl mx-auto px-8 flex justify-between items-center">
          <div className="flex items-center space-x-4 cursor-pointer" onClick={() => currentUser ? setState('selection') : setState('home')}>
            <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg">🚀</div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tighter">Super Word Buddy</h1>
          </div>
          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <button onClick={() => setState('upload')} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-sm font-black shadow-lg">Yükle</button>
            ) : (
              <button onClick={() => setState('login')} className="bg-slate-800 text-white px-6 py-2 rounded-xl text-sm font-black">Giriş Yap</button>
            )}
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full px-8 py-12">
        {error && (
          <div className="mb-8 p-6 bg-red-50 border-2 border-red-100 text-red-600 rounded-3xl text-center font-bold">
            {error}
            <button onClick={() => setError(null)} className="ml-4 underline font-black">Tamam</button>
          </div>
        )}

        {state === 'home' && (
          <div className="flex flex-col items-center justify-center space-y-12 py-20 text-center">
            <div className="w-40 h-40 bg-indigo-600 rounded-[3rem] shadow-2xl flex items-center justify-center text-7xl animate-bounce">🎓</div>
            <h2 className="text-6xl font-black text-slate-800 tracking-tighter max-w-2xl">
              Üniversite İngilizcesini <span className="text-indigo-600">Eğlenceyle</span> Çöz!
            </h2>
            <button onClick={() => setState('signup')} className="bg-indigo-600 text-white px-12 py-5 rounded-3xl text-xl font-black shadow-xl hover:scale-105 transition-all">Başla 🚀</button>
          </div>
        )}

        {(state === 'login' || state === 'signup') && (
          <AuthForm mode={state} onAuthSuccess={(user) => { setCurrentUser(user); setState('selection'); }} onToggleMode={(newMode) => setState(newMode)} />
        )}

        {state === 'upload' && <FileUpload onFileSelect={handleFileSelect} />}

        {state === 'analyzing' && (
          <div className="flex flex-col items-center justify-center py-32 space-y-8 text-center">
            <div className="w-20 h-20 border-8 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <h3 className="text-3xl font-black text-slate-800">Süper Zeka Çalışıyor...</h3>
            <p className="text-slate-400 font-medium">Kelimeler veritabanına güvenle aktarılıyor.</p>
          </div>
        )}

        {state === 'selection' && (
          <div className="space-y-12">
            <div className="text-center">
              <h2 className="text-5xl font-black text-slate-800 tracking-tight">Merhaba {currentUser?.name}! 👋</h2>
              <p className="text-slate-400 text-xl mt-2">Bugün listende {vocabItems.length} kelime var.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div onClick={() => vocabItems.length > 0 ? setState('learning') : setState('upload')} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-6 group-hover:scale-110 transition-transform">📚</div>
                <h3 className="text-2xl font-black text-slate-800">Kartlar</h3>
              </div>
              <div onClick={() => vocabItems.length >= 4 ? startQuiz() : setError("En az 4 kelime lazım!")} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-6 group-hover:scale-110 transition-transform">🎮</div>
                <h3 className="text-2xl font-black text-slate-800">Test</h3>
              </div>
