import { GoogleGenAI, Type } from "@google/genai";
import { VocabularyItem } from "../types";

export const analyzeVocabulary = async (base64Data: string, mimeType: string): Promise<VocabularyItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Sen bir akademik İngilizce uzmanısın. Aşağıdaki dokümanı (Görsel veya PDF) analiz et.
    19 yaşındaki bir üniversite öğrencisinin dil gelişimine katkı sağlayacak en önemli kelimeleri seç.

    Her kelime için tam olarak bu JSON yapısını kullan:
    - word: Kelimenin İngilizce hali.
    - meaning: Kelimenin tam Türkçe karşılığı.
    - exampleSentence: Kelimeyi içeren akademik/günlük düzgün bir İngilizce cümle.
    - exampleSentenceTurkish: Bu İngilizce cümlenin Türkçe çevirisi.

    Yanıtı sadece saf JSON formatında (ARRAY) döndür. Maksimum 15-20 kaliteli kelime seç.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              meaning: { type: Type.STRING },
              exampleSentence: { type: Type.STRING },
              exampleSentenceTurkish: { type: Type.STRING }
            },
            required: ["word", "meaning", "exampleSentence", "exampleSentenceTurkish"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];

    const parsed = JSON.parse(text);
    return (Array.isArray(parsed) ? parsed : []) as VocabularyItem[];
  } catch (error) {
    console.error("Gemini Analiz Hatası:", error);
    throw new Error("Doküman analiz edilemedi. Lütfen dosyanın net olduğundan emin ol.");
  }
};

export const generateQuiz = async (words: VocabularyItem[]): Promise<any[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const subset = [...words].sort(() => Math.random() - 0.5).slice(0, 10);

  const prompt = `Aşağıdaki kelimelerle ilgili üniversite seviyesinde 10 adet çoktan seçmeli soru hazırla. Sadece JSON döndür. Kelimeler: ${JSON.stringify(subset)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchUserWords = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        const mapped = data.map(item => ({
          id: item.id,
          word: item.english,
          meaning: item.turkish,
          exampleSentence: item.example_sentence_en,
          exampleSentenceTurkish: item.example_sentence_tr
        }));
        setVocabItems(mapped);
      }
    } catch (err: any) {
      console.error('Fetch error:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) return;
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);
      if (!items || items.length === 0) throw new Error("Hiç kelime bulunamadı.");

      const payloads = items.map(item => ({
        user_id: currentUser.id,
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish
      }));

      const { error: insertError } = await supabase.from('vocabulary').insert(payloads);
      if (insertError) throw insertError;

      await fetchUserWords(currentUser.id);
      setState('selection');
    } catch (err: any) {
      setError("Hata: " + err.message);
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 4) {
      setError("Test için en az 4 kelime lazım!");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;
    try {
      const payload = {
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish,
        user_id: currentUser.id
      };

      if (item.id) {
        await supabase.from('vocabulary').update(payload).eq('id', item.id);
      } else {
        await supabase.from('vocabulary').insert([payload]);
      }

      fetchUserWords(currentUser.id);
      setEditingItem(null);
      setIsModalOpen(false);
    } catch (err: any) {
      setError("Kayıt hatası: " + err.message);
    }
  };

  const deleteWord = async (id: string) => {
    if (!currentUser) return;
    await supabase.from('vocabulary').delete().eq('id', id);
    fetchUserWords(currentUser.id);
  };

  const handleEditClick = (item: VocabularyItem) => {
    setEditingItem(item);
    setIsModalOpen(true);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#fdfbf7]">
      <header className="bg-white/90 backdrop-blur-md sticky top-0 z-20 py-6 border-b border-slate-100">
        <div className="max-w-6xl mx-auto px-8 flex justify-between items-center">
          <div className="flex items-center space-x-4 cursor-pointer" onClick={() => currentUser ? setState('selection') : setState('home')}>
            <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg">🎓</div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tighter">Super Word Buddy</h1>
          </div>
          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <div className="flex items-center space-x-4">
                <span className="text-sm font-bold text-slate-600 hidden sm:block">{currentUser.name}</span>
                <button onClick={() => setState('upload')} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-sm font-black shadow-lg hover:bg-indigo-700 transition-all">Yükle</button>
                <button onClick={handleLogout} className="text-slate-400 hover:text-red-500">Çıkış</button>
              </div>
            ) : (
              <button onClick={() => setState('login')} className="bg-slate-800 text-white px-6 py-2 rounded-xl text-sm font-black">Giriş Yap</button>
            )}
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full px-8 py-12">
        {error && (
          <div className="mb-8 p-6 bg-red-50 border-2 border-red-100 text-red-600 rounded-3xl text-center font-bold">
            {error}
            <button onClick={() => setError(null)} className="ml-4 underline">Kapat</button>
          </div>
        )}

        {state === 'home' && (
          <div className="flex flex-col items-center justify-center space-y-12 py-20 text-center">
            <div className="w-40 h-40 bg-indigo-600 rounded-[3rem] shadow-2xl flex items-center justify-center text-7xl animate-bounce">🌍</div>
            <h2 className="text-6xl font-black text-slate-800 tracking-tighter">Akademik İngilizceyi <span className="text-indigo-600">Farket!</span></h2>
            <button onClick={() => setState('signup')} className="bg-indigo-600 text-white px-12 py-5 rounded-3xl text-xl font-black shadow-xl hover:scale-105 transition-all">Hemen Başla 🚀</button>
          </div>
        )}

        {(state === 'login' || state === 'signup') && (
          <AuthForm mode={state} onAuthSuccess={(user) => { setCurrentUser(user); setState('selection'); }} onToggleMode={(newMode) => setState(newMode)} />
        )}

        {state === 'upload' && <FileUpload onFileSelect={handleFileSelect} />}

        {state === 'analyzing' && (
          <div className="flex flex-col items-center justify-center py-32 space-y-8">
            <div className="w-20 h-20 border-8 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <h3 className="text-3xl font-black text-slate-800">Analiz Yapılıyor...</h3>
            <p className="text-slate-400">Gemini 3 Flash kelimeleri veritabanına işliyor.</p>
          </div>
        )}

        {state === 'selection' && (
          <div className="space-y-12 animate-in fade-in slide-in-from-bottom-8 duration-500">
            <div className="text-center">
              <h2 className="text-5xl font-black text-slate-800">Hoş Geldin, {currentUser?.name}! 👋</h2>
              <p className="text-slate-400 text-xl mt-2">Bugün kütüphanende {vocabItems.length} kelime var.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div onClick={() => vocabItems.length > 0 ? setState('learning') : setState('upload')} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-6 group-hover:scale-110 transition-transform">📚</div>
                <h3 className="text-2xl font-black text-slate-800">Kartlar</h3>
              </div>
              <div onClick={() => vocabItems.length >= 4 ? startQuiz() : setError("En az 4 kelime lazım!")} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-6 group-hover:scale-110 transition-transform">🎯</div>
                <h3 className="text-2xl font-black text-slate-800">Test</h3>
              </div>
              <div onClick={() => vocabItems.length > 0 ? setState('writing') : setState('upload')} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-6 group-hover:scale-110 transition-transform">✍️</div>
                <h3 className="text-2xl font-black text-slate-800">Yazma</h3>
              </div>
              <div onClick={() => setState('list')} className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-6 group-hover:scale-110 transition-transform">📋</div>
                <h3 className="text-2xl font-black text-slate-800">Listem</h3>
              </div>
            </div>
            <div className="flex justify-center mt-12">
              <button onClick={() => { setEditingItem(null); setIsModalOpen(true); }} className="bg-white border-2 border-slate-100 px-8 py-4 rounded-2xl font-black text-slate-500 hover:bg-slate-50 hover:border-indigo-200 transition-all">
                + Elinle Kelime Ekle
              </button>
            </div>
          </div>
        )}

        {state === 'learning' && <Flashcards items={shuffleArray(vocabItems)} onComplete={() => setState('selection')} />}
        {state === 'quiz' && <Quiz questions={quizQuestions} onClose={() => setState('selection')} />}
        {state === 'writing' && <WordWriting items={shuffleArray(vocabItems)} onClose={() => setState('selection')} />}

        {state === 'list' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex justify-between items-center">
              <h2 className="text-4xl font-black text-slate-800">Kütüphanem 🌟</h2>
              <button onClick={() => setState('selection')} className="bg-slate-100 px-8 py-3 rounded-2xl font-black">Geri Dön</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {vocabItems.map((item) => (
                <div key={item.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-md transition-all">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h4 className="text-2xl font-black text-slate-800">{item.word}</h4>
                      <p className="text-indigo-600 font-bold text-lg">{item.meaning}</p>
                    </div>
                    <div className="flex space-x-1">
                      <button onClick={() => handleEditClick(item)} className="p-2 text-slate-200 hover:text-indigo-500 transition-colors">✏️</button>
                      <button onClick={() => deleteWord(item.id)} className="p-2 text-slate-200 hover:text-red-500 transition-colors">🗑️</button>
                    </div>
                  </div>
                  <div className="pt-4 border-t border-slate-50 space-y-2">
                    <p className="text-slate-500 italic text-sm">"{item.exampleSentence}"</p>
                    <p className="text-slate-300 text-xs font-bold uppercase">{item.exampleSentenceTurkish}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {isModalOpen && <AddWordModal onAdd={addOrUpdateWord} onClose={() => { setIsModalOpen(false); setEditingItem(null); }} initialData={editingItem} />}
    </div>
  );
};

