import { GoogleGenAI, Type } from "@google/genai";
import { VocabularyItem } from "../types";

export const analyzeVocabulary = async (base64Data: string, mimeType: string): Promise<VocabularyItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Sen bir akademik İngilizce uzmanısın. Aşağıdaki üniversite düzeyindeki dokümanı analiz et.
    Kullanıcının kelime hazinesini (Basket) zenginleştirmek için en kaliteli 15-20 kelimeyi seç.

    Özellikle şunlara dikkat et:
    1. Sadece dokümandaki metni değil, o metnin konusuna dair akademik açıdan kritik yan kelimeleri de dahil et.
    2. 19 yaşındaki bir üniversite öğrencisinin IELTS, TOEFL veya akademik makale okuma süreçlerinde işine yarayacak sofistike kelimelere odaklan.

    Her kelime için bu JSON yapısını kullan:
    - word: Kelimenin İngilizce hali.
    - meaning: Kelimenin tam Türkçe karşılığı.
    - exampleSentence: Kelimeyi içeren akademik/günlük düzgün bir İngilizce cümle.
    - exampleSentenceTurkish: Bu İngilizce cümlenin Türkçe çevirisi.

    Yanıtı sadece saf JSON formatında (ARRAY) döndür.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              meaning: { type: Type.STRING },
              exampleSentence: { type: Type.STRING },
              exampleSentenceTurkish: { type: Type.STRING }
            },
            required: ["word", "meaning", "exampleSentence", "exampleSentenceTurkish"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];

    const parsed = JSON.parse(text);
    return (Array.isArray(parsed) ? parsed : []) as VocabularyItem[];
  } catch (error) {
    console.error("Gemini Analiz Hatası:", error);
    throw new Error("Analiz motoru şu an meşgul, lütfen dosyanı tekrar yüklemeyi dene.");
  }
};

export const generateQuiz = async (words: VocabularyItem[]): Promise<any[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  // Sepetin tamamından (words) rastgele 10 tanesini seçerek test oluşturuyoruz.
  const basketSubset = [...words].sort(() => Math.random() - 0.5).slice(0, 10);

  const prompt = `Aşağıdaki kelime sepetinden karma bir test hazırla. Üniversite seviyesinde 10 adet çoktan seçmeli soru olsun. Sadece JSON döndür. Kelimeler: ${JSON.stringify(basketSubset)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchUserWords(user.id);
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchUserWords = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        const mapped = data.map(item => ({
          id: item.id,
          word: item.english,
          meaning: item.turkish,
          exampleSentence: item.example_sentence_en,
          exampleSentenceTurkish: item.example_sentence_tr
        }));
        setVocabItems(mapped);
      }
    } catch (err: any) {
      console.error('Fetch error:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) return;
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);
      if (!items || items.length === 0) throw new Error("Dosyada işlenecek kelime bulunamadı.");

      const payloads = items.map(item => ({
        user_id: currentUser.id,
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish
      }));

      // Supabase'e ekleme yapıyoruz (üzerine yazmıyor, sepeti büyütüyor)
      const { error: insertError } = await supabase.from('vocabulary').insert(payloads);
      if (insertError) throw insertError;

      await fetchUserWords(currentUser.id);
      setState('selection');
    } catch (err: any) {
      setError("Sepet güncellenemedi: " + err.message);
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 4) {
      setError("Karma test için sepetinde en az 4 kelime olmalı!");
      return;
    }
    setState('analyzing');
    try {
      // Sepetteki TÜM kelimeler içinden rastgele bir test oluşturuyoruz
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;
    try {
      const payload = {
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish,
        user_id: currentUser.id
      };

      if (item.id) {
        await supabase.from('vocabulary').update(payload).eq('id', item.id);
      } else {
        await supabase.from('vocabulary').insert([payload]);
      }

      fetchUserWords(currentUser.id);
      setEditingItem(null);
      setIsModalOpen(false);
    } catch (err: any) {
      setError("Kelime sepetine eklenemedi: " + err.message);
    }
  };

  const deleteWord = async (id: string) => {
    if (!currentUser) return;
    await supabase.from('vocabulary').delete().eq('id', id);
    fetchUserWords(currentUser.id);
  };

  const handleEditClick = (item: VocabularyItem) => {
    setEditingItem(item);
    setIsModalOpen(true);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#f8fafc]">
      <header className="bg-white/90 backdrop-blur-md sticky top-0 z-20 py-5 border-b border-slate-200">
        <div className="max-w-6xl mx-auto px-6 flex justify-between items-center">
          <div className="flex items-center space-x-3 cursor-pointer" onClick={() => currentUser ? setState('selection') : setState('home')}>
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl shadow-lg">🚀</div>
            <h1 className="text-xl font-black text-slate-800 tracking-tight">Super Word Buddy</h1>
          </div>
          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <div className="flex items-center space-x-3">
                <div className="hidden sm:flex flex-col items-end mr-2">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Basket Size</span>
                  <span className="text-sm font-black text-indigo-600">{vocabItems.length} Kelime</span>
                </div>
                <button onClick={() => setState('upload')} className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-sm font-black shadow-lg hover:shadow-indigo-200 transition-all">Yeni Ekle</button>
                <button onClick={handleLogout} className="text-slate-400 hover:text-red-500 font-bold text-sm">Çıkış</button>
              </div>
            ) : (
              <button onClick={() => setState('login')} className="bg-slate-800 text-white px-5 py-2 rounded-xl text-sm font-black">Giriş Yap</button>
            )}
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full px-6 py-10">
        {error && (
          <div className="mb-8 p-5 bg-red-50 border border-red-100 text-red-600 rounded-2xl text-center font-bold">
            {error}
            <button onClick={() => setError(null)} className="ml-4 underline opacity-70">Anladım</button>
          </div>
        )}

        {state === 'home' && (
          <div className="flex flex-col items-center justify-center space-y-10 py-16 text-center">
            <div className="w-32 h-32 bg-gradient-to-tr from-indigo-500 to-purple-500 rounded-[2.5rem] shadow-2xl flex items-center justify-center text-6xl animate-pulse">🎓</div>
            <div className="space-y-4">
              <h2 className="text-5xl md:text-6xl font-black text-slate-900 tracking-tighter leading-tight">
                Akademik Kelime <br/><span className="text-indigo-600">Hazineni İnşa Et!</span>
              </h2>
              <p className="text-lg text-slate-500 max-w-lg mx-auto font-medium">
                Notlarını yükle, Gemini 3 Flash ile analiz et ve devasa sepetindeki tüm kelimeleri karma oyunlarla kalıcı hale getir.
              </p>
            </div>
            <button onClick={() => setState('signup')} className="bg-indigo-600 text-white px-10 py-4 rounded-2xl text-lg font-black shadow-xl hover:scale-105 transition-all">Ücretsiz Başla 🚀</button>
          </div>
        )}

        {(state === 'login' || state === 'signup') && (
          <AuthForm mode={state} onAuthSuccess={(user) => { setCurrentUser(user); setState('selection'); }} onToggleMode={(newMode) => setState(newMode)} />
        )}

        {state === 'upload' && <FileUpload onFileSelect={handleFileSelect} />}

        {state === 'analyzing' && (
          <div className="flex flex-col items-center justify-center py-24 space-y-6">
            <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <h3 className="text-2xl font-black text-slate-800">Sepet Genişletiliyor...</h3>
            <p className="text-slate-400 font-medium">Yeni kelimeler kütüphanene ekleniyor.</p>
          </div>
        )}

        {state === 'selection' && (
          <div className="space-y-12 animate-in fade-in slide-in-from-bottom-6 duration-500">
            <div className="text-center space-y-2">
              <h2 className="text-4xl font-black text-slate-900 tracking-tight italic">Word Basket</h2>
              <p className="text-slate-400 text-lg font-medium">Sepetinde toplam <span className="text-indigo-600 font-black">{vocabItems.length}</span> eşsiz kelime birikti.</p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              <div onClick={() => vocabItems.length > 0 ? setState('learning') : setState('upload')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">🎴</div>
                <h3 className="text-xl font-black text-slate-800">Karma Kartlar</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Sepetten rastgele seçim</p>
              </div>
              <div onClick={() => vocabItems.length >= 4 ? startQuiz() : setError("Test için en az 4 kelime lazım!")} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">🎯</div>
                <h3 className="text-xl font-black text-slate-800">Büyük Test</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Tüm geçmişi sına</p>
              </div>
              <div onClick={() => vocabItems.length > 0 ? setState('writing') : setState('upload')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">✍️</div>
                <h3 className="text-xl font-black text-slate-800">Yazma Kampı</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Hafızayı tazele</p>
              </div>
              <div onClick={() => setState('list')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">📋</div>
                <h3 className="text-xl font-black text-slate-800">Sepeti İncele</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Tüm kelimeleri gör</p>
              </div>
            </div>

            <div className="flex flex-col items-center pt-8 border-t border-slate-100">
              <p className="text-slate-400 text-sm mb-4 font-bold uppercase tracking-widest">Kendi Kelimeni Eklemek İster misin?</p>
              <button onClick={() => { setEditingItem(null); setIsModalOpen(true); }} className="bg-white border-2 border-slate-100 px-10 py-4 rounded-2xl font-black text-slate-600 hover:border-indigo-600 hover:text-indigo-600 transition-all shadow-sm">
                + Manuel Kelime Ekle
              </button>
            </div>
          </div>
        )}

        {state === 'learning' && <Flashcards items={shuffleArray(vocabItems)} onComplete={() => setState('selection')} />}
        {state === 'quiz' && <Quiz questions={quizQuestions} onClose={() => setState('selection')} />}
        {state === 'writing' && <WordWriting items={shuffleArray(vocabItems)} onClose={() => setState('selection')} />}

        {state === 'list' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
              <div>
                <h2 className="text-3xl font-black text-slate-900">Kelime Hazinem 💎</h2>
                <p className="text-slate-400 font-bold">Kayıtlı toplam {vocabItems.length} kelime bulunuyor.</p>
              </div>
              <button onClick={() => setState('selection')} className="bg-slate-800 text-white px-8 py-3 rounded-2xl font-black shadow-lg shadow-slate-200">Geri Dön</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {vocabItems.map((item) => (
                <div key={item.id} className="bg-white p-7 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-md transition-all group">
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex-1">
                      <h4 className="text-xl font-black text-slate-800 group-hover:text-indigo-600 transition-colors">{item.word}</h4>
                      <p className="text-indigo-600 font-bold">{item.meaning}</p>
                    </div>
                    <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => handleEditClick(item)} className="p-2 text-slate-300 hover:text-indigo-500 transition-colors">✏️</button>
                      <button onClick={() => deleteWord(item.id)} className="p-2 text-slate-300 hover:text-red-500 transition-colors">🗑️</button>
                    </div>
                  </div>
                  <div className="pt-4 border-t border-slate-50 space-y-2">
                    <p className="text-slate-500 italic text-sm line-clamp-2 hover:line-clamp-none transition-all">"{item.exampleSentence}"</p>
                    <p className="text-[10px] text-slate-300 font-black uppercase tracking-wider">{item.exampleSentenceTurkish}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {isModalOpen && <AddWordModal onAdd={addOrUpdateWord} onClose={() => { setIsModalOpen(false); setEditingItem(null); }} initialData={editingItem} />}
    </div>
  );
};

