export const generateQuiz = async (words: VocabularyItem[]): Promise<QuizQuestion[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const basketSubset = [...words].sort(() => Math.random() - 0.5).slice(0, 10);

  const prompt = `Aşağıdaki kelime sepetinden karma bir test hazırla. Üniversite seviyesinde 10 adet çoktan seçmeli soru olsun. 
  DOĞRU CEVAPLAR RASTGELE SIRADA OLSUN, HEP İLK ŞIK OLMASIN. Sadece JSON döndür. Kelimeler: ${JSON.stringify(basketSubset)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });

    const questions: QuizQuestion[] = JSON.parse(response.text || "[]");

    // Frontend tarafında da şıkları karıştırarak çift koruma sağlıyoruz
    return questions.map(q => ({
      ...q,
      options: shuffle(q.options)
    }));
  } catch (error) {
    console.error("Quiz üretim hatası:", error);
    return [];
  }
};

