import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords(); // Artık filtrelemeden tüm kelimeleri çekiyoruz
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // Ortak havuzdaki tüm kelimeleri çeken fonksiyon
  const fetchAllWords = async () => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        const mapped = data.map(item => ({
          id: item.id,
          word: item.english,
          meaning: item.turkish,
          exampleSentence: item.example_sentence_en,
          exampleSentenceTurkish: item.example_sentence_tr
        }));
        setVocabItems(mapped);
      }
    } catch (err: any) {
      console.error('Veri çekme hatası:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) return;
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);
      if (!items || items.length === 0) throw new Error("Dosyada kelime bulunamadı.");

      // TEKİLLEŞTİRME MANTIĞI: Veritabanında zaten olan kelimeleri ayıklıyoruz
      const existingWords = new Set(vocabItems.map(v => v.word.toLowerCase().trim()));

      const newUniqueItems = items.filter(item => 
        !existingWords.has(item.word.toLowerCase().trim())
      );

      if (newUniqueItems.length === 0) {
        setError("Bu dosyadaki tüm kelimeler havuzda zaten mevcut! ✨");
        setState('selection');
        return;
      }

      const payloads = newUniqueItems.map(item => ({
        user_id: currentUser.id,
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish
      }));

      const { error: insertError } = await supabase.from('vocabulary').insert(payloads);
      if (insertError) throw insertError;

      await fetchAllWords();
      setState('selection');
    } catch (err: any) {
      setError("Hata: " + err.message);
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 4) {
      setError("Test için havuzda en az 4 kelime olmalı!");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;

    // El ile eklemede de tekilleştirme yapıyoruz
    if (!item.id && vocabItems.some(v => v.word.toLowerCase().trim() === item.word.toLowerCase().trim())) {
      setError("Bu kelime zaten ortak havuzda var! 🌟");
      setIsModalOpen(false);
      return;
    }

    try {
      const payload = {
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish,
        user_id: currentUser.id
      };

      if (item.id) {
        await supabase.from('vocabulary').update(payload).eq('id', item.id);
      } else {
        await supabase.from('vocabulary').insert([payload]);
      }

      fetchAllWords();
      setEditingItem(null);
      setIsModalOpen(false);
    } catch (err: any) {
      setError("Kayıt hatası: " + err.message);
    }
  };

  const deleteWord = async (id: string) => {
    if (!currentUser) return;
    // Ortak havuzda sildirme yetkisi sadece ekleyene ya da herkese verilebilir.
    // Şimdilik sistemin bütünlüğü için herkese açık bırakıyoruz.
    await supabase.from('vocabulary').delete().eq('id', id);
    fetchAllWords();
  };

  const handleEditClick = (item: VocabularyItem) => {
    setEditingItem(item);
    setIsModalOpen(true);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#f8fafc]">
      <header className="bg-white/95 backdrop-blur-md sticky top-0 z-20 py-5 border-b border-slate-200">
        <div className="max-w-6xl mx-auto px-6 flex justify-between items-center">
          <div className="flex items-center space-x-3 cursor-pointer" onClick={() => currentUser ? setState('selection') : setState('home')}>
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl shadow-lg">🚀</div>
            <div className="flex flex-col">
              <h1 className="text-xl font-black text-slate-800 leading-none">Super Word Buddy</h1>
              <span className="text-[10px] font-black text-indigo-500 uppercase tracking-tighter">Academic Community</span>
            </div>
          </div>
          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <div className="flex items-center space-x-3">
                <div className="hidden sm:flex flex-col items-end mr-2">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none">Havuz Kapasitesi</span>
                  <span className="text-sm font-black text-indigo-600">{vocabItems.length} Kelime</span>
                </div>
                <button onClick={() => setState('upload')} className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-sm font-black shadow-lg hover:shadow-indigo-200 transition-all">Yeni Yükle</button>
                <button onClick={handleLogout} className="text-slate-400 hover:text-red-500 font-bold text-sm">Çıkış</button>
              </div>
            ) : (
              <button onClick={() => setState('login')} className="bg-slate-800 text-white px-5 py-2 rounded-xl text-sm font-black">Giriş Yap</button>
            )}
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full px-6 py-10">
        {error && (
          <div className="mb-8 p-5 bg-red-50 border border-red-100 text-red-600 rounded-2xl text-center font-bold animate-bounce">
            {error}
            <button onClick={() => setError(null)} className="ml-4 underline opacity-70">Kapat</button>
          </div>
        )}

        {state === 'home' && (
          <div className="flex flex-col items-center justify-center space-y-10 py-16 text-center">
            <div className="w-32 h-32 bg-gradient-to-tr from-indigo-500 to-purple-500 rounded-[2.5rem] shadow-2xl flex items-center justify-center text-6xl">🎓</div>
            <div className="space-y-4">
              <h2 className="text-5xl md:text-6xl font-black text-slate-900 tracking-tighter leading-tight">
                Ortak Akademik <br/><span className="text-indigo-600">Bilgi Havuzu!</span>
              </h2>
              <p className="text-lg text-slate-500 max-w-lg mx-auto font-medium">
                Üniversite arkadaşlarınla birlikte kelimeleri paylaş, Gemini ile analiz et ve devasa ortak sepetten hep beraber öğrenin.
              </p>
            </div>
            <button onClick={() => setState('signup')} className="bg-indigo-600 text-white px-10 py-4 rounded-2xl text-lg font-black shadow-xl hover:scale-105 transition-all">Havuca Katıl 🚀</button>
          </div>
        )}

        {(state === 'login' || state === 'signup') && (
          <AuthForm mode={state} onAuthSuccess={(user) => { setCurrentUser(user); setState('selection'); }} onToggleMode={(newMode) => setState(newMode)} />
        )}

        {state === 'upload' && <FileUpload onFileSelect={handleFileSelect} />}

        {state === 'analyzing' && (
          <div className="flex flex-col items-center justify-center py-24 space-y-6 text-center">
            <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <h3 className="text-2xl font-black text-slate-800">Ortak Havuz Güncelleniyor...</h3>
            <p className="text-slate-400 font-medium max-w-sm">Yeni kelimeler analiz ediliyor ve mevcut olanlarla karşılaştırılıyor.</p>
          </div>
        )}

        {state === 'selection' && (
          <div className="space-y-12 animate-in fade-in slide-in-from-bottom-6 duration-500">
            <div className="text-center space-y-2">
              <h2 className="text-4xl font-black text-slate-900 tracking-tight italic">Global Word Pool</h2>
              <p className="text-slate-400 text-lg font-medium">Şu an tüm arkadaşların için toplam <span className="text-indigo-600 font-black">{vocabItems.length}</span> kelime birikti.</p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              <div onClick={() => vocabItems.length > 0 ? setState('learning') : setState('upload')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">📚</div>
                <h3 className="text-xl font-black text-slate-800">Karma Kartlar</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Tüm havuzdan rastgele</p>
              </div>
              <div onClick={() => vocabItems.length >= 4 ? startQuiz() : setError("En az 4 kelime lazım!")} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">🎲</div>
                <h3 className="text-xl font-black text-slate-800">Büyük Test</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Her seferinde farklı şıklar</p>
              </div>
              <div onClick={() => vocabItems.length > 0 ? setState('writing') : setState('upload')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">✏️</div>
                <h3 className="text-xl font-black text-slate-800">Yazma Kampı</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Hafıza tazeleyici</p>
              </div>
              <div onClick={() => setState('list')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">🌍</div>
                <h3 className="text-xl font-black text-slate-800">Havuzu Gör</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Kim ne eklemiş incele</p>
              </div>
            </div>

            <div className="flex flex-col items-center pt-8 border-t border-slate-100">
              <p className="text-slate-400 text-sm mb-4 font-bold uppercase tracking-widest">Havuzda Olmayan Bir Kelime mi Var?</p>
              <button onClick={() => { setEditingItem(null); setIsModalOpen(true); }} className="bg-white border-2 border-slate-100 px-10 py-4 rounded-2xl font-black text-slate-600 hover:border-indigo-600 hover:text-indigo-600 transition-all shadow-sm">
                + Havuza Kelime Ekle
              </button>
            </div>
          </div>
        )}

        {state === 'learning' && <Flashcards items={shuffleArray(vocabItems)} onComplete={() => setState('selection')} />}
        {state === 'quiz' && <Quiz questions={quizQuestions} onClose={() => setState('selection')} />}
        {state === 'writing' && <WordWriting items={shuffleArray(vocabItems)} onClose={() => setState('selection')} />}

        {state === 'list' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
              <div>
                <h2 className="text-3xl font-black text-slate-900">Ortak Kütüphane 💎</h2>
                <p className="text-slate-400 font-bold">Toplam {vocabItems.length} akademik kelime hazır bekliyor.</p>
              </div>
              <button onClick={() => setState('selection')} className="bg-slate-800 text-white px-8 py-3 rounded-2xl font-black shadow-lg shadow-slate-200">Geri Dön</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {vocabItems.map((item) => (
                <div key={item.id} className="bg-white p-7 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-md transition-all group">
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex-1">
                      <h4 className="text-xl font-black text-slate-800 group-hover:text-indigo-600 transition-colors">{item.word}</h4>
                      <p className="text-indigo-600 font-bold">{item.meaning}</p>
                    </div>
                    <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => handleEditClick(item)} className="p-2 text-slate-300 hover:text-indigo-500 transition-colors">✏️</button>
                      <button onClick={() => deleteWord(item.id)} className="p-2 text-slate-300 hover:text-red-500 transition-colors">🗑️</button>
                    </div>
                  </div>
                  <div className="pt-4 border-t border-slate-50 space-y-2">
                    <p className="text-slate-500 italic text-sm line-clamp-2">"{item.exampleSentence}"</p>
                    <p className="text-[10px] text-slate-300 font-black uppercase tracking-wider">{item.exampleSentenceTurkish}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {isModalOpen && <AddWordModal onAdd={addOrUpdateWord} onClose={() => { setIsModalOpen(false); setEditingItem(null); }} initialData={editingItem} />}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { VocabularyItem, QuizQuestion } from "../types";

// Yardımcı fonksiyon: Diziyi karıştırır
const shuffle = <T>(array: T[]): T[] => {
  const newArray = [...array];
  for (let i = newArray.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
  }
  return newArray;
};

export const analyzeVocabulary = async (base64Data: string, mimeType: string): Promise<VocabularyItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Sen bir akademik İngilizce uzmanısın. Aşağıdaki üniversite düzeyindeki dokümanı analiz et.
    Kullanıcının kelime havuzunu hızla büyütmek için dokümandan en az 40-50 tane kaliteli kelime seç.

    Özellikle şunlara dikkat et:
    1. Metindeki temel kelimelerin yanı sıra, üniversite (19 yaş) seviyesindeki bir öğrencinin bilmesi gereken akademik (TOEFL/IELTS seviyesi) kelimelere odaklan.
    2. Dokümandaki kavramlarla ilişkili yan terimleri de ekle ki havuz zenginleşsin.
    3. Her kelime için İngilizce kelime, Türkçe anlamı, akademik İngilizce örnek cümle ve Türkçe çevirisini hazırla.

    Yanıtı sadece saf JSON formatında (ARRAY) döndür.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              meaning: { type: Type.STRING },
              exampleSentence: { type: Type.STRING },
              exampleSentenceTurkish: { type: Type.STRING }
            },
            required: ["word", "meaning", "exampleSentence", "exampleSentenceTurkish"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];

    const parsed = JSON.parse(text);
    return (Array.isArray(parsed) ? parsed : []) as VocabularyItem[];
  } catch (error) {
    console.error("Gemini Analiz Hatası:", error);
    throw new Error("Geniş kapsamlı analiz yapılırken bir hata oluştu. Lütfen tekrar deneyin.");
  }
};

export const generateQuiz = async (words: VocabularyItem[]): Promise<QuizQuestion[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const basketSubset = [...words].sort(() => Math.random() - 0.5).slice(0, 10);

  const prompt = `Aşağıdaki kelime sepetinden karma bir test hazırla. 
  Üniversite seviyesinde 10 adet çoktan seçmeli soru olsun. 
  ÖNEMLİ: Her sorunun tam olarak 5 ADET seçeneği (A, B, C, D, E) olmalı. 
  Doğru cevaplar şıklar arasında rastgele dağıtılmalıdır.
  Sadece JSON döndür. Kelimeler: ${JSON.stringify(basketSubset)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING }, minItems: 5, maxItems: 5 },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });

    const questions: QuizQuestion[] = JSON.parse(response.text || "[]");

    return questions.map(q => ({
      ...q,
      options: shuffle(q.options)
    }));
  } catch (error) {
    console.error("Quiz üretim hatası:", error);
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchAllWords = async () => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        const mapped = data.map(item => ({
          id: item.id,
          word: item.english,
          meaning: item.turkish,
          exampleSentence: item.example_sentence_en,
          exampleSentenceTurkish: item.example_sentence_tr
        }));
        setVocabItems(mapped);
      }
    } catch (err: any) {
      console.error('Veri çekme hatası:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) return;
    setState('analyzing');
    setError(null);
    try {
      const items = await analyzeVocabulary(base64, mimeType);
      if (!items || items.length === 0) throw new Error("Dosyada kelime bulunamadı.");

      const existingWords = new Set(vocabItems.map(v => v.word.toLowerCase().trim()));

      const newUniqueItems = items.filter(item => 
        !existingWords.has(item.word.toLowerCase().trim())
      );

      if (newUniqueItems.length === 0) {
        setError("Bu dosyadaki tüm kelimeler havuzda zaten mevcut! ✨");
        setState('selection');
        return;
      }

      const payloads = newUniqueItems.map(item => ({
        user_id: currentUser.id,
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish
      }));

      const { error: insertError } = await supabase.from('vocabulary').insert(payloads);
