                  <div className="pt-4 border-t border-slate-50 space-y-2">
                    <p className="text-slate-500 italic text-sm line-clamp-2">"{item.exampleSentence}"</p>
                    <p className="text-[10px] text-slate-300 font-black uppercase tracking-wider">{item.exampleSentenceTurkish}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {isModalOpen && <AddWordModal onAdd={addOrUpdateWord} onClose={() => { setIsModalOpen(false); setEditingItem(null); }} initialData={editingItem} />}
    </div>
  );
};

