import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  // Deploy sonrası en sık karşılaşılan hata: API Key eksikliği
  useEffect(() => {
    if (!process.env.API_KEY) {
      console.error("DİKKAT: API_KEY ortam değişkeni bulunamadı! Deploy ayarlarından eklemeyi unutmayın.");
      setError("Sistem yapılandırması eksik (API Key bulunamadı). Lütfen yönetici ile iletişime geçin.");
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchAllWords = async () => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        const mapped = data.map(item => ({
          id: item.id,
          word: item.english,
          meaning: item.turkish,
          exampleSentence: item.example_sentence_en,
          exampleSentenceTurkish: item.example_sentence_tr
        }));
        setVocabItems(mapped);
      }
    } catch (err: any) {
      console.error('Veri çekme hatası:', err);
      // RLS hatası genellikle deploy sonrası yaşanır
      if (err.message?.includes("row-level security")) {
        setError("Veritabanı erişim izni reddedildi. Lütfen Supabase RLS ayarlarını kontrol edin.");
      }
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) return;
    setState('analyzing');
    setError(null);
    try {
      await fetchAllWords();
      const items = await analyzeVocabulary(base64, mimeType);

      if (!items || items.length === 0) throw new Error("Dosyada işlenecek kelime bulunamadı.");

      const existingWords = new Set(vocabItems.map(v => v.word.toLowerCase().trim()));
      const newUniqueItems = items.filter(item => !existingWords.has(item.word.toLowerCase().trim()));

      if (newUniqueItems.length === 0) {
        setError("Bu dosyadaki tüm kelimeler havuzda zaten mevcut! ✨");
        setState('selection');
        return;
      }

      const payloads = newUniqueItems.map(item => ({
        user_id: currentUser.id,
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish
      }));

      const { error: insertError } = await supabase.from('vocabulary').insert(payloads);

      if (insertError) throw insertError;

      await fetchAllWords();
      setState('selection');
    } catch (err: any) {
      setError(err.message || "Bilinmeyen bir analiz hatası oluştu.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 5) {
      setError("Test için havuzda en az 5 kelime olmalı!");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;
    if (!item.id && vocabItems.some(v => v.word.toLowerCase().trim() === item.word.toLowerCase().trim())) {
      setError("Bu kelime zaten ortak havuzda var! 🌟");
      setIsModalOpen(false);
      return;
    }

    try {
      const payload = {
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish,
        user_id: currentUser.id
      };

      let opError;
      if (item.id) {
        const { error } = await supabase.from('vocabulary').update(payload).eq('id', item.id);
        opError = error;
      } else {
        const { error } = await supabase.from('vocabulary').insert([payload]);
        opError = error;
      }

      if (opError) throw opError;

      await fetchAllWords();
      setEditingItem(null);
      setIsModalOpen(false);
    } catch (err: any) {
      setError(err.message);
    }
  };

  const deleteWord = async (id: string) => {
    if (!currentUser) return;
    const { error } = await supabase.from('vocabulary').delete().eq('id', id);
    if (error) setError(error.message);
    else fetchAllWords();
  };

  const handleEditClick = (item: VocabularyItem) => {
    setEditingItem(item);
    setIsModalOpen(true);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#fdfbf7]">
      <header className="bg-white/95 backdrop-blur-md sticky top-0 z-20 py-5 border-b border-slate-200 shadow-sm">
        <div className="max-w-6xl mx-auto px-6 flex justify-between items-center">
          <div className="flex items-center space-x-3 cursor-pointer" onClick={() => currentUser ? setState('selection') : setState('home')}>
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl shadow-lg">🚀</div>
            <div className="flex flex-col">
              <h1 className="text-xl font-black text-slate-800 leading-none">Super Word Buddy</h1>
              <span className="text-[10px] font-black text-indigo-500 uppercase tracking-tighter">Academic Global Pool</span>
            </div>
          </div>
          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <div className="flex items-center space-x-3">
                <div className="hidden sm:flex flex-col items-end mr-2">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none">Global Havuz</span>
