            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl shadow-lg">🚀</div>
            <div className="flex flex-col">
              <h1 className="text-xl font-black text-slate-800 leading-none">Super Word Buddy</h1>
              <span className="text-[10px] font-black text-indigo-500 uppercase tracking-tighter">Academic Global Pool</span>
            </div>
