import React, { useState, useEffect } from 'react';
import { VocabularyItem } from '../types';

interface WordWritingProps {
  items: VocabularyItem[];
  onClose: () => void;
}

const WordWriting: React.FC<WordWritingProps> = ({ items, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [userInput, setUserInput] = useState<string[]>([]);
  const [scrambled, setScrambled] = useState<string[]>([]);
  const [isCorrect, setIsCorrect] = useState(false);
  const [usedIndices, setUsedIndices] = useState<number[]>([]);
  const [timerSeconds, setTimerSeconds] = useState(0);

  const current = items[currentIndex];

  useEffect(() => {
    initWord();
  }, [currentIndex]);

  // Zamanlayıcıyı başlatan effect
  useEffect(() => {
    if (isCorrect) return;

    const interval = setInterval(() => {
      setTimerSeconds(s => s + 1);
    }, 1000);

    return () => clearInterval(interval);
  }, [currentIndex, isCorrect]);

  const initWord = () => {
    const word = items[currentIndex].word.toUpperCase();
    const letters = word.split('').filter(l => l !== ' ');
    const shuffled = [...letters].sort(() => Math.random() - 0.5);
    setScrambled(shuffled);
    setUserInput(new Array(letters.length).fill(''));
    setUsedIndices([]);
    setIsCorrect(false);
    setTimerSeconds(0);
  };

  const handleLetterClick = (letter: string, index: number) => {
    if (usedIndices.includes(index) || isCorrect) return;

    const firstEmptyIndex = userInput.indexOf('');
    if (firstEmptyIndex !== -1) {
      const newInput = [...userInput];
      newInput[firstEmptyIndex] = letter;
      setUserInput(newInput);
      setUsedIndices([...usedIndices, index]);

      if (firstEmptyIndex === userInput.length - 1) {
        const result = newInput.join('');
        const target = current.word.toUpperCase().replace(/\s/g, '');
        if (result === target) {
          setIsCorrect(true);
        }
      }
    }
  };

  const clearLast = () => {
    if (isCorrect) return;
    const lastFilledIndex = userInput.map((v, i) => v !== '' ? i : -1).filter(v => v !== -1).pop();
    if (lastFilledIndex !== undefined) {
      const newInput = [...userInput];
      newInput[lastFilledIndex] = '';
      setUserInput(newInput);

      const newUsedIndices = [...usedIndices];
      newUsedIndices.pop();
      setUsedIndices(newUsedIndices);
    }
  };

  const revealAnswer = () => {
    const target = current.word.toUpperCase().replace(/\s/g, '').split('');
    setUserInput(target);
    setIsCorrect(true);
  };

  const nextWord = () => {
    if (currentIndex < items.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      onClose();
    }
  };

  return (
    <div className="w-full max-w-2xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-8">
      <div className="flex justify-between items-center px-6">
        <span className="text-lg font-black text-slate-300 uppercase tracking-widest">KELİME YAZMA {currentIndex + 1} / {items.length}</span>
        <button onClick={onClose} className="text-slate-400 font-bold hover:text-slate-600">Kapat ✖</button>
      </div>

      <div className="bg-white p-8 md:p-12 rounded-[3rem] md:rounded-[4rem] shadow-2xl border-4 border-white text-center">
        <div className="mb-4">
          <span className="text-sm font-black text-indigo-400 uppercase tracking-widest bg-indigo-50 px-4 py-1 rounded-full">TÜRKÇE ANLAMI</span>
        </div>
        <h2 className="text-3xl md:text-5xl font-black text-slate-800 mb-8 md:mb-12 tracking-tight">
          {current.meaning}
        </h2>

        {/* Word Placeholders */}
        <div className="flex flex-nowrap justify-center gap-1 sm:gap-3 mb-12 overflow-x-auto pb-4 scrollbar-hide max-w-full">
          {userInput.map((letter, idx) => (
            <div 
              key={idx} 
              className={`min-w-[2.5rem] sm:min-w-[3.5rem] h-12 sm:h-16 rounded-xl sm:rounded-2xl border-2 sm:border-4 flex items-center justify-center text-xl sm:text-3xl font-black transition-all flex-shrink-0 ${
                isCorrect ? 'bg-green-100 border-green-500 text-green-700' : 
                letter ? 'bg-white border-blue-400 text-blue-500' : 'bg-slate-50 border-slate-100'
              }`}
            >
              {letter}
            </div>
          ))}
        </div>

        {/* Scrambled Letters */}
        <div className="flex flex-wrap justify-center gap-2 sm:gap-4 mb-8">
          {scrambled.map((letter, idx) => (
            <button
              key={idx}
              disabled={usedIndices.includes(idx) || isCorrect}
              onClick={() => handleLetterClick(letter, idx)}
              className={`w-12 h-12 sm:w-14 sm:h-14 rounded-xl sm:rounded-2xl flex items-center justify-center text-xl sm:text-2xl font-black transition-all transform active:scale-95 ${
                usedIndices.includes(idx) 
                ? 'bg-slate-100 text-slate-300 cursor-not-allowed' 
                : 'bg-blue-50 text-blue-500 hover:bg-blue-100 hover:scale-110 shadow-lg shadow-blue-100/50'
              }`}
            >
              {letter}
            </button>
          ))}
        </div>

        <div className="flex flex-col items-center space-y-4">
          <button 
            onClick={clearLast}
            className="text-slate-400 font-bold hover:text-red-400 transition-colors flex items-center space-x-2"
            disabled={isCorrect}
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 9.75L14.25 12m0 0l2.25 2.25M14.25 12l2.25-2.25M14.25 12L12 14.25m-2.58 4.92l-6.375-6.375a1.125 1.125 0 010-1.59L9.42 4.83c.211-.211.498-.33.796-.33H19.5a2.25 2.25 0 012.25 2.25v10.5a2.25 2.25 0 01-2.25 2.25h-9.284c-.298 0-.585-.119-.796-.33z" />
            </svg>
            <span>Bir Harf Sil</span>
          </button>

          {/* 30 saniye dolunca beliren "Cevabı Gör" butonu */}
          {!isCorrect && timerSeconds >= 30 && (
            <button 
              onClick={revealAnswer}
              className="mt-4 px-8 py-4 bg-orange-100 text-orange-600 rounded-2xl font-black text-xl hover:bg-orange-200 transition-all animate-bounce shadow-lg shadow-orange-100"
            >
              Bulamadın mı? Cevabı Gör ✨
            </button>
          )}
        </div>
      </div>

      {isCorrect && (
        <div className="animate-in slide-in-from-top-4 duration-500">
          <div className="bg-green-500 p-8 rounded-[3rem] shadow-xl text-center text-white mb-6">
            <h3 className="text-3xl font-black mb-2">Harikasın! 🎉</h3>
            <p className="font-bold opacity-90">"{current.word.toUpperCase()}" doğru yazıldı!</p>
          </div>
          <button 
            onClick={nextWord}
            className="w-full py-6 bg-orange-400 text-white rounded-[2.5rem] font-black text-2xl hover:bg-orange-500 transition-all transform hover:scale-[1.02] shadow-2xl shadow-orange-100"
          >
            {currentIndex === items.length - 1 ? 'Oyunu Bitir ✨' : 'Sıradaki Kelime 🚀'}
          </button>
        </div>
      )}
    </div>
  );
};

export default WordWriting;

import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);

  useEffect(() => {
    if (!process.env.API_KEY) {
      console.error("DİKKAT: API_KEY ortam değişkeni bulunamadı!");
      setError("Sistem yapılandırması eksik (API Key bulunamadı).");
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchAllWords = async () => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        const mapped = data.map(item => ({
          id: item.id,
          word: item.english,
          meaning: item.turkish,
          exampleSentence: item.example_sentence_en,
          exampleSentenceTurkish: item.example_sentence_tr
        }));
        setVocabItems(mapped);
      }
    } catch (err: any) {
      console.error('Veri çekme hatası:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) return;
    setState('analyzing');
    setError(null);
    try {
      await fetchAllWords();
      const items = await analyzeVocabulary(base64, mimeType);

      if (!items || items.length === 0) throw new Error("Dosyada işlenecek kelime bulunamadı.");

      const existingWords = new Set(vocabItems.map(v => v.word.toLowerCase().trim()));
      const newUniqueItems = items.filter(item => !existingWords.has(item.word.toLowerCase().trim()));

      if (newUniqueItems.length === 0) {
        setError("Bu dosyadaki tüm kelimeler havuzda zaten mevcut! ✨");
        setState('selection');
        return;
      }

      const payloads = newUniqueItems.map(item => ({
        user_id: currentUser.id,
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish
      }));

      const { error: insertError } = await supabase.from('vocabulary').insert(payloads);

      if (insertError) throw insertError;

      await fetchAllWords();
      setState('selection');
    } catch (err: any) {
      setError(err.message || "Bilinmeyen bir analiz hatası oluştu.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 5) {
      setError("Test için havuzda en az 5 kelime olmalı!");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;
    if (!item.id && vocabItems.some(v => v.word.toLowerCase().trim() === item.word.toLowerCase().trim())) {
      setError("Bu kelime zaten ortak havuzda var! 🌟");
      setIsModalOpen(false);
      return;
    }

    try {
      const payload = {
        english: item.word,
        turkish: item.meaning,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish,
        user_id: currentUser.id
      };

      let opError;
      if (item.id) {
        const { error } = await supabase.from('vocabulary').update(payload).eq('id', item.id);
        opError = error;
      } else {
        const { error } = await supabase.from('vocabulary').insert([payload]);
        opError = error;
      }

      if (opError) throw opError;

      await fetchAllWords();
      setEditingItem(null);
      setIsModalOpen(false);
    } catch (err: any) {
      setError(err.message);
    }
  };

  const deleteWord = async (id: string) => {
    if (!currentUser) return;
    const { error } = await supabase.from('vocabulary').delete().eq('id', id);
    if (error) setError(error.message);
    else fetchAllWords();
  };

  const handleEditClick = (item: VocabularyItem) => {
    setEditingItem(item);
    setIsModalOpen(true);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#fdfbf7]">
      <header className="bg-white/95 backdrop-blur-md sticky top-0 z-20 py-5 border-b border-slate-200 shadow-sm">
        <div className="max-w-6xl mx-auto px-6 flex justify-between items-center">
