import React, { useState, useEffect } from 'react';
import { VocabularyItem } from '../types';

interface WordWritingProps {
  items: VocabularyItem[];
  onClose: () => void;
}

const WordWriting: React.FC<WordWritingProps> = ({ items, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [userInput, setUserInput] = useState<string[]>([]);
  const [scrambled, setScrambled] = useState<string[]>([]);
  const [isCorrect, setIsCorrect] = useState(false);
  const [usedIndices, setUsedIndices] = useState<number[]>([]);
  const [timerSeconds, setTimerSeconds] = useState(0);

  const current = items[currentIndex];

  useEffect(() => {
    initWord();
  }, [currentIndex]);

  useEffect(() => {
    if (isCorrect) return;

    const interval = setInterval(() => {
      setTimerSeconds(s => s + 1);
    }, 1000);

    return () => clearInterval(interval);
  }, [currentIndex, isCorrect]);

  const initWord = () => {
    const word = items[currentIndex].word.toUpperCase();
    const letters = word.split('').filter(l => l !== ' ');
    const shuffled = [...letters].sort(() => Math.random() - 0.5);
    setScrambled(shuffled);
    setUserInput(new Array(letters.length).fill(''));
    setUsedIndices([]);
    setIsCorrect(false);
    setTimerSeconds(0);
  };

  const handleLetterClick = (letter: string, index: number) => {
    if (usedIndices.includes(index) || isCorrect) return;

    const firstEmptyIndex = userInput.indexOf('');
    if (firstEmptyIndex !== -1) {
      const newInput = [...userInput];
      newInput[firstEmptyIndex] = letter;
      setUserInput(newInput);
      setUsedIndices([...usedIndices, index]);

      if (firstEmptyIndex === userInput.length - 1) {
        const result = newInput.join('');
        const target = current.word.toUpperCase().replace(/\s/g, '');
        if (result === target) {
          setIsCorrect(true);
        }
      }
    }
  };

  const clearLast = () => {
    if (isCorrect) return;
    const lastFilledIndex = userInput.map((v, i) => v !== '' ? i : -1).filter(v => v !== -1).pop();
    if (lastFilledIndex !== undefined) {
      const newInput = [...userInput];
      newInput[lastFilledIndex] = '';
      setUserInput(newInput);

      const newUsedIndices = [...usedIndices];
      newUsedIndices.pop();
      setUsedIndices(newUsedIndices);
    }
  };

  const revealAnswer = () => {
    const target = current.word.toUpperCase().replace(/\s/g, '').split('');
    setUserInput(target);
    setIsCorrect(true);
  };

  const nextWord = () => {
    if (currentIndex < items.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      onClose();
    }
  };

  // Dinamik kutu boyutu hesaplama - Harf sayısına göre daha agresif ölçekleme
  const boxSizeClass = userInput.length > 15 ? 'w-6 h-8 sm:w-8 sm:h-10 text-xs sm:text-lg' :
                       userInput.length > 12 ? 'w-8 h-10 sm:w-10 sm:h-12 text-lg' : 
                       userInput.length > 8 ? 'w-10 h-12 sm:w-14 sm:h-16 text-xl' : 
                       'w-12 h-14 sm:w-16 sm:h-20 text-2xl sm:text-4xl';

  return (
    <div className="w-full flex flex-col items-center space-y-10 animate-in fade-in slide-in-from-bottom-8">
      <div className="flex justify-between items-center px-6 w-full max-w-2xl">
        <span className="text-lg font-black text-slate-300 uppercase tracking-widest">KELİME YAZMA {currentIndex + 1} / {items.length}</span>
        <button onClick={onClose} className="text-slate-400 font-bold hover:text-slate-600">Kapat ✖</button>
      </div>

      {/* Ana Çerçeve - Kelimeye göre genişler, kaydırma çubuğu kesinlikle yok */}
      <div className="bg-white p-8 md:p-12 rounded-[3rem] md:rounded-[4rem] shadow-2xl border-4 border-white text-center w-fit min-w-[320px] max-w-full overflow-hidden flex flex-col items-center">
        <div className="mb-4">
          <span className="text-sm font-black text-indigo-400 uppercase tracking-widest bg-indigo-50 px-4 py-1 rounded-full">TÜRKÇE ANLAMI</span>
        </div>
        <h2 className="text-3xl md:text-5xl font-black text-slate-800 mb-8 md:mb-12 tracking-tight">
          {current.meaning}
        </h2>

        {/* Word Placeholders - Tek Satır, Taşma Yok, Kaydırma Çubuğu Yok */}
        <div className="flex flex-nowrap justify-center gap-1 sm:gap-2 mb-12 w-full px-2 overflow-hidden">
          {userInput.map((letter, idx) => (
            <div 
              key={idx} 
              className={`${boxSizeClass} rounded-lg sm:rounded-2xl border-2 sm:border-4 flex items-center justify-center font-black transition-all flex-shrink-1 ${
                isCorrect ? 'bg-green-100 border-green-500 text-green-700' : 
                letter ? 'bg-white border-blue-400 text-blue-500' : 'bg-slate-50 border-slate-100'
              }`}
            >
              {letter}
            </div>
          ))}
        </div>

        {/* Scrambled Letters - Mümkünse tek sıra veya sıkışık düzen */}
        <div className="flex flex-wrap justify-center gap-2 sm:gap-3 mb-10 w-full">
          {scrambled.map((letter, idx) => (
            <button
              key={idx}
              disabled={usedIndices.includes(idx) || isCorrect}
              onClick={() => handleLetterClick(letter, idx)}
              className={`w-10 h-10 sm:w-14 sm:h-14 rounded-xl sm:rounded-2xl flex items-center justify-center text-lg sm:text-2xl font-black transition-all transform active:scale-95 flex-shrink-0 ${
                usedIndices.includes(idx) 
                ? 'bg-slate-100 text-slate-200 cursor-not-allowed border-none shadow-none' 
                : 'bg-blue-50 text-blue-500 hover:bg-blue-100 hover:scale-110 shadow-lg shadow-blue-100/50 border-2 border-blue-100'
              }`}
            >
              {letter}
            </button>
          ))}
        </div>

        <div className="flex flex-col items-center space-y-6 w-full">
          <button 
            onClick={clearLast}
            className="text-slate-400 font-bold hover:text-red-400 transition-colors flex items-center space-x-2 bg-slate-50 px-4 py-2 rounded-full"
            disabled={isCorrect}
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 9.75L14.25 12m0 0l2.25 2.25M14.25 12l2.25-2.25M14.25 12L12 14.25m-2.58 4.92l-6.375-6.375a1.125 1.125 0 010-1.59L9.42 4.83c.211-.211.498-.33.796-.33H19.5a2.25 2.25 0 012.25 2.25v10.5a2.25 2.25 0 01-2.25 2.25h-9.284c-.298 0-.585-.119-.796-.33z" />
            </svg>
            <span>Bir Harf Sil</span>
          </button>

          {/* 30 saniye dolunca beliren "Cevabı Gör" butonu */}
          {!isCorrect && timerSeconds >= 30 && (
            <button 
              onClick={revealAnswer}
              className="px-8 py-4 bg-gradient-to-r from-orange-400 to-red-500 text-white rounded-[1.5rem] font-black text-xl hover:scale-105 transition-all animate-bounce shadow-xl shadow-orange-200 ring-4 ring-orange-50"
            >
              Bulamadın mı? Cevabı Gör ✨
            </button>
          )}
        </div>
      </div>

      {isCorrect && (
        <div className="animate-in slide-in-from-top-4 duration-500 max-w-2xl mx-auto w-full px-6">
          <div className="bg-green-500 p-8 rounded-[3rem] shadow-xl text-center text-white mb-6">
            <h3 className="text-3xl font-black mb-2">Harikasın! 🎉</h3>
            <p className="font-bold opacity-90">"{current.word.toUpperCase()}" doğru yazıldı!</p>
          </div>
          <button 
            onClick={nextWord}
            className="w-full py-6 bg-orange-400 text-white rounded-[2.5rem] font-black text-2xl hover:bg-orange-500 transition-all transform hover:scale-[1.02] shadow-2xl shadow-orange-100"
          >
            {currentIndex === items.length - 1 ? 'Oyunu Bitir ✨' : 'Sıradaki Kelime 🚀'}
          </button>
        </div>
      )}
    </div>
  );
};

