            </button>
          )}

          {!isCorrect && timerSeconds >= 30 && (
            <button 
              onClick={revealAnswer}
              className="px-8 py-4 bg-gradient-to-r from-orange-400 to-red-500 text-white rounded-[1.5rem] font-black text-xl hover:scale-105 transition-all animate-bounce shadow-xl shadow-orange-200 ring-4 ring-orange-50"
            >
              Bulamadın mı? Cevabı Gör ✨
