interface FlashcardsProps {
  items: VocabularyItem[];
  onComplete: () => void;
}

const Flashcards: React.FC<FlashcardsProps> = ({ items, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  const current = items[currentIndex];

  const speak = (text: string, lang: 'en-GB' | 'en-US') => {
    // Mevcut konuşmaları durdur
    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices();

    // Kadın seslerini ve yüksek kaliteli (Google/Premium) sesleri önceliklendir
    const preferredVoice = voices.find(v => 
      v.lang.includes(lang.replace('-', '_')) || v.lang.includes(lang)
    ) && voices.find(v => 
      (v.lang.includes(lang)) && 
      (v.name.includes('Female') || v.name.includes('Google') || v.name.includes('Samantha') || v.name.includes('Zira') || v.name.includes('Microsoft'))
    );

    if (preferredVoice) {
      utterance.voice = preferredVoice;
    }

    utterance.lang = lang;
    utterance.rate = 0.85; // Akademik netlik için hafif yavaşlatıldı
    utterance.pitch = 1.1; // Daha hoş ve net bir ton için hafif yükseltildi
    utterance.volume = 1.0; // Ses seviyesi maksimuma çekildi

    window.speechSynthesis.speak(utterance);
  };

  const nextCard = () => {
    if (currentIndex < items.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setIsFlipped(false);
    } else {
      onComplete();
    }
