          {/* Front side: English Word & Pronunciation */}
          <div className="absolute inset-0 bg-white rounded-[3rem] shadow-[0_20px_50px_rgba(0,0,0,0.05)] flex flex-col items-center justify-center p-8 border-4 border-blue-50 backface-hidden">
