          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
