              <div onClick={() => setState('stats')} className="bg-gradient-to-br from-indigo-500 to-purple-600 p-8 rounded-[2.5rem] shadow-lg hover:shadow-2xl hover:-translate-y-1 transition-all cursor-pointer text-center group text-white lg:col-span-2">
