                    </div>

                    {/* Pronunciation Buttons in List with Flags */}
                    <div className="flex space-x-2">
                      <button 
                        onClick={() => speak(item.word, 'en-GB')}
                        className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-sm border border-blue-100 overflow-hidden"
                        title="British"
                      >
                        <img src="https://flagcdn.com/w40/gb.png" className="w-6 h-auto rounded-sm shadow-xs" alt="UK" />
                      </button>
                      <button 
                        onClick={() => speak(item.word, 'en-US')}
                        className="w-10 h-10 bg-red-50 text-red-500 rounded-xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-sm border border-red-100 overflow-hidden"
                        title="American"
                      >
                        <img src="https://flagcdn.com/w40/us.png" className="w-6 h-auto rounded-sm shadow-xs" alt="US" />
                      </button>
                    </div>
                  </div>
                  <div className="pt-4 border-t border-slate-50 space-y-3">
                    <p className="text-slate-500 italic text-sm leading-relaxed">"{item.exampleSentence}"</p>
                    <p className="text-[11px] text-slate-400 font-bold uppercase tracking-wider">{item.exampleSentenceTurkish}</p>
                  </div>
                </div>
              ))}
            </div>

            {filteredVocab.length === 0 && (
              <div className="text-center py-20">
                <div className="text-6xl mb-4">🔍</div>
                <h3 className="text-2xl font-black text-slate-400">Aradığın kelime havuzda bulunamadı...</h3>
                <p className="text-slate-300 font-bold mt-2">Belki de sen eklemek istersin? ✨</p>
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="mt-auto py-12 bg-white border-t border-slate-100 flex flex-col items-center space-y-8">
        <div className="flex flex-col items-center space-y-4 px-6 text-center">
          <p className="text-indigo-600 font-bold italic text-sm sm:text-base">
            Beğendiysen belki bana bir kahve ısmarlarsın ;)
          </p>
          <a 
            href="https://buymeacoffee.com/suattayfuntopak" 
            target="_blank" 
            rel="noopener noreferrer"
            className="flex items-center space-x-2 bg-[#FFDD00] text-black px-6 py-3 rounded-xl font-bold hover:scale-105 transition-all shadow-lg hover:shadow-yellow-100"
          >
            <span className="text-2xl">☕</span>
            <span className="font-black" style={{ fontFamily: "'Cookie', cursive" }}>Buy me a coffee</span>
          </a>
        </div>
        <div className="border-t border-slate-50 w-full pt-8 flex justify-center">
          <p className="text-[10px] sm:text-xs text-slate-300 font-black uppercase tracking-[0.2em]">
            designed by <span className="text-slate-400">Suat Tayfun TOPAK</span>
          </p>
        </div>
      </footer>

      {isModalOpen && <AddWordModal onAdd={addOrUpdateWord} onClose={() => { setIsModalOpen(false); setEditingItem(null); }} initialData={editingItem} />}
    </div>
  );
};

