import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';
import { VocabularyItem } from '../types';

interface StatisticsProps {
  userId: string;
  vocabItems: VocabularyItem[];
}

const Statistics: React.FC<StatisticsProps> = ({ userId, vocabItems }) => {
  const [stats, setStats] = useState({
    totalWords: 0,
    dailyWords: 0,
    weeklyWords: 0,
    monthlyWords: 0,
    addedByMe: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    calculateStats();
  }, [vocabItems]);

  const calculateStats = async () => {
    setLoading(true);
    try {
      // Mevcut kelime listesi üzerinden tarih bazlı istatistik çıkarıyoruz
      const now = new Date();
      const startOfDay = new Date(now.setHours(0, 0, 0, 0));
      const startOfWeek = new Date(now.setDate(now.getDate() - now.getDay()));
      const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

      // Gerçek veri çekme simülasyonu/mantığı (vocabulary tablosundaki created_at'e göre)
      const { data, error } = await supabase
        .from('vocabulary')
        .select('created_at, user_id');

      if (data) {
        const counts = {
          totalWords: data.length,
          dailyWords: data.filter(d => new Date(d.created_at) >= startOfDay).length,
          weeklyWords: data.filter(d => new Date(d.created_at) >= startOfWeek).length,
          monthlyWords: data.filter(d => new Date(d.created_at) >= startOfMonth).length,
          addedByMe: data.filter(d => d.user_id === userId).length
        };
        setStats(counts);
      }
    } catch (err) {
      console.error('Stats error:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto w-full space-y-12 animate-in fade-in zoom-in-95 duration-500 pb-20">
      <div className="text-center space-y-4">
        <h2 className="text-5xl font-black text-slate-800 tracking-tight">Sana Özel İstatistikler 📊</h2>
        <p className="text-slate-400 font-bold text-lg uppercase tracking-widest">Akademik Başarı Yolculuğun</p>
      </div>

      {loading ? (
        <div className="flex justify-center py-20">
          <div className="w-12 h-12 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {/* Main Stat Card */}
          <div className="bg-white p-10 rounded-[3rem] shadow-xl border-4 border-indigo-50 flex flex-col items-center text-center col-span-1 md:col-span-2 lg:col-span-1">
            <span className="text-6xl mb-4">💎</span>
            <h3 className="text-slate-400 font-black text-xs uppercase tracking-[0.2em] mb-2">Global Havuz Katkın</h3>
            <span className="text-6xl font-black text-indigo-600">{stats.addedByMe}</span>
            <p className="text-slate-500 mt-4 text-sm font-medium">Senin sayende kütüphane büyüyor!</p>
          </div>

          <div className="bg-white p-10 rounded-[3rem] shadow-xl border-b-8 border-green-400 flex flex-col items-center text-center">
            <span className="text-4xl mb-4">📅</span>
            <h3 className="text-slate-400 font-black text-xs uppercase tracking-[0.2em] mb-2">Günlük Kelime</h3>
            <span className="text-5xl font-black text-slate-800">{stats.dailyWords}</span>
            <p className="text-slate-400 mt-4 text-xs font-bold">Bugün Eklenenler</p>
          </div>

          <div className="bg-white p-10 rounded-[3rem] shadow-xl border-b-8 border-blue-400 flex flex-col items-center text-center">
            <span className="text-4xl mb-4">🌊</span>
            <h3 className="text-slate-400 font-black text-xs uppercase tracking-[0.2em] mb-2">Haftalık Kelime</h3>
            <span className="text-5xl font-black text-slate-800">{stats.weeklyWords}</span>
            <p className="text-slate-400 mt-4 text-xs font-bold">Bu Hafta Eklenenler</p>
          </div>

          <div className="bg-white p-10 rounded-[3rem] shadow-xl border-b-8 border-purple-400 flex flex-col items-center text-center">
            <span className="text-4xl mb-4">🚀</span>
            <h3 className="text-slate-400 font-black text-xs uppercase tracking-[0.2em] mb-2">Aylık Kelime</h3>
            <span className="text-5xl font-black text-slate-800">{stats.monthlyWords}</span>
            <p className="text-slate-400 mt-4 text-xs font-bold">Bu Ay Eklenenler</p>
          </div>

          <div className="bg-gradient-to-tr from-indigo-600 to-indigo-800 p-10 rounded-[3rem] shadow-2xl flex flex-col items-center text-center text-white md:col-span-2 lg:col-span-2">
            <h3 className="font-black text-xs uppercase tracking-[0.2em] mb-4 opacity-60">Toplam Akademik Güç</h3>
            <div className="flex items-baseline space-x-2">
              <span className="text-8xl font-black">{stats.totalWords}</span>
              <span className="text-xl font-bold opacity-60">Kelime</span>
            </div>
            <p className="mt-6 font-medium italic opacity-80">
              "Kelimeler, bir insanın sahip olduğu en güçlü silahtır."
            </p>
          </div>
        </div>
      )}

      <div className="bg-orange-50 p-10 rounded-[3rem] border-2 border-orange-100 text-center">
        <h4 className="text-xl font-black text-orange-700 mb-2">Hedefine Ulaşmaya Az Kaldı! 🏆</h4>
        <p className="text-orange-600/70 font-medium">Bu hafta kütüphaneye en çok katkı sağlayan ilk 5 öğrenciden birisin.</p>
      </div>
    </div>
  );
};

