import React, { useState } from 'react';
import { QuizQuestion } from '../types';

interface QuizProps {
  questions: QuizQuestion[];
  onClose: (score: number, total: number) => void;
}

const Quiz: React.FC<QuizProps> = ({ questions, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [showResult, setShowResult] = useState(false);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);

  const isCorrectAnswer = (option: string, correct: string) => {
    return option.trim().toLowerCase() === correct.trim().toLowerCase();
  };

  const handleAnswer = (option: string) => {
    if (isAnswered) return;
    setSelectedOption(option);
    setIsAnswered(true);

    const correct = questions[currentIndex].correctAnswer;
    if (isCorrectAnswer(option, correct)) {
      setScore(s => s + 1);
    }
  };

  const nextQuestion = () => {
    if (currentIndex < questions.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setShowResult(true);
    }
  };

  if (showResult) {
    const percentage = Math.round((score / questions.length) * 100);
    let message = "Harika gidiyorsun! 🎉";
    let icon = "🌟";
    if (percentage === 100) { message = "Mükemmelsin! Şampiyon! 🏆"; icon = "🦁"; }
    else if (percentage < 50) { message = "Biraz daha çalışalım mı? 🧸"; icon = "📚"; }

    return (
      <div className="bg-white p-16 rounded-[4rem] shadow-2xl text-center max-w-lg mx-auto border-4 border-indigo-50 animate-in zoom-in-95 duration-500">
        <div className="text-7xl mb-8">{icon}</div>
        <h2 className="text-4xl font-black text-slate-800 mb-4 tracking-tight">{message}</h2>
        <p className="text-slate-400 text-xl font-medium mb-10">Havuzdaki kelimeleri iyice kavramışsın!</p>
        <div className="bg-indigo-50 p-10 rounded-[3rem] mb-12">
          <span className="text-7xl font-black text-indigo-500">%{percentage}</span>
          <p className="text-indigo-400 font-bold mt-2 uppercase tracking-widest">Başarı Oranın</p>
        </div>
        <button 
          onClick={() => onClose(score, questions.length)}
          className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-xl hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100"
        >
          Havuz Seçimine Dön
        </button>
      </div>
    );
  }

  const current = questions[currentIndex];
  const labels = ['A', 'B', 'C', 'D', 'E'];

  return (
    <div className="w-full max-w-2xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-8">
      <div className="flex justify-between items-center mb-4 px-6">
        <span className="text-lg font-black text-slate-300 uppercase tracking-widest">SORU {currentIndex + 1} / {questions.length}</span>
        <div className="flex items-center space-x-2 bg-yellow-50 px-5 py-2 rounded-full">
           <span className="text-lg">💎</span>
           <span className="text-yellow-600 font-black">SKOR: {score * 10}</span>
        </div>
      </div>

      <div className="bg-white p-10 md:p-14 rounded-[4rem] shadow-2xl border-4 border-white">
        <h3 className="text-3xl md:text-4xl font-black text-slate-800 mb-10 leading-tight text-center">
          {current.question}
        </h3>

        <div className="grid gap-4">
          {current.options.map((option, idx) => {
            const isCorrect = isCorrectAnswer(option, current.correctAnswer);
            const isSelected = option === selectedOption;

            let bgColor = 'bg-slate-50 border-slate-100 hover:border-indigo-400 hover:bg-indigo-50/30';

            if (isAnswered) {
              if (isCorrect) {
                bgColor = 'bg-green-100 border-green-500 text-green-700 ring-4 ring-green-50 z-10';
              } else if (isSelected) {
                bgColor = 'bg-red-100 border-red-500 text-red-700';
              } else {
                bgColor = 'bg-slate-50 border-slate-100 opacity-40';
              }
            }

            return (
              <button
                key={idx}
                disabled={isAnswered}
                onClick={() => handleAnswer(option)}
                className={`w-full text-left p-5 border-4 rounded-[2rem] text-lg font-bold transition-all flex items-center space-x-4 ${!isAnswered ? 'hover:scale-[1.02] active:scale-95 shadow-sm' : ''} ${bgColor}`}
              >
                <span className={`w-10 h-10 shrink-0 rounded-xl flex items-center justify-center font-black transition-colors ${isAnswered && isCorrect ? 'bg-green-500 text-white' : isAnswered && isSelected && !isCorrect ? 'bg-red-500 text-white' : 'bg-white text-slate-400 border border-slate-100'}`}>
                  {labels[idx]}
                </span>
                <span className="flex-1">{option}</span>
                {isAnswered && isCorrect && <span className="text-2xl animate-bounce">✓</span>}
                {isAnswered && isSelected && !isCorrect && <span className="text-2xl">✕</span>}
              </button>
            );
          })}
        </div>
      </div>

      {isAnswered && (
        <button 
          onClick={nextQuestion}
          className="w-full py-6 bg-orange-400 text-white rounded-[2.5rem] font-black text-2xl hover:bg-orange-500 transition-all transform hover:scale-[1.02] shadow-2xl shadow-orange-100 animate-in slide-in-from-top-4"
        >
          {currentIndex === questions.length - 1 ? 'Sonucu Gör ✨' : 'Sıradaki Soru 🚀'}
        </button>
      )}
    </div>
  );
};

export default Quiz;

import React, { useState, useEffect } from 'react';
import { VocabularyItem } from '../types';

interface WordWritingProps {
  items: VocabularyItem[];
  onClose: (score: number, total: number) => void;
}

const WordWriting: React.FC<WordWritingProps> = ({ items, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [userInput, setUserInput] = useState<string[]>([]);
  const [scrambled, setScrambled] = useState<string[]>([]);
  const [isCorrect, setIsCorrect] = useState(false);
  const [usedIndices, setUsedIndices] = useState<number[]>([]);
  const [timerSeconds, setTimerSeconds] = useState(0);
  const [successCount, setSuccessCount] = useState(0);

  const current = items[currentIndex];

  useEffect(() => {
    initWord();
  }, [currentIndex]);

  useEffect(() => {
    if (isCorrect) return;

    const interval = setInterval(() => {
      setTimerSeconds(s => s + 1);
    }, 1000);

    return () => clearInterval(interval);
  }, [currentIndex, isCorrect]);

  const initWord = () => {
    const word = items[currentIndex].word.toUpperCase();
    const letters = word.split('').filter(l => l !== ' ');
    const shuffled = [...letters].sort(() => Math.random() - 0.5);
    setScrambled(shuffled);
    setUserInput(new Array(letters.length).fill(''));
    setUsedIndices([]);
    setIsCorrect(false);
    setTimerSeconds(0);
  };

  const speak = (text: string, lang: 'en-GB' | 'en-US') => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices();
    const preferredVoice = voices.find(v => 
      (v.lang.includes(lang)) && 
      (v.name.includes('Female') || v.name.includes('Google') || v.name.includes('Samantha') || v.name.includes('Zira') || v.name.includes('Microsoft'))
    );
    if (preferredVoice) utterance.voice = preferredVoice;
    utterance.lang = lang;
    utterance.rate = 0.85; 
    utterance.pitch = 1.1; 
    utterance.volume = 1.0; 
    window.speechSynthesis.speak(utterance);
  };

  const handleLetterClick = (letter: string, index: number) => {
    if (usedIndices.includes(index) || isCorrect) return;

    const firstEmptyIndex = userInput.indexOf('');
    if (firstEmptyIndex !== -1) {
      const newInput = [...userInput];
      newInput[firstEmptyIndex] = letter;
      setUserInput(newInput);
      setUsedIndices([...usedIndices, index]);

      if (firstEmptyIndex === userInput.length - 1) {
        const result = newInput.join('');
        const target = current.word.toUpperCase().replace(/\s/g, '');
        if (result === target) {
          setIsCorrect(true);
          setSuccessCount(s => s + 1);
        }
      }
    }
  };

  const clearLast = () => {
    if (isCorrect) return;
    const lastFilledIndex = userInput.map((v, i) => v !== '' ? i : -1).filter(v => v !== -1).pop();
    if (lastFilledIndex !== undefined) {
      const newInput = [...userInput];
      newInput[lastFilledIndex] = '';
      setUserInput(newInput);

      const newUsedIndices = [...usedIndices];
      newUsedIndices.pop();
      setUsedIndices(newUsedIndices);
    }
  };

  const revealAnswer = () => {
    const target = current.word.toUpperCase().replace(/\s/g, '').split('');
    setUserInput(target);
    setIsCorrect(true);
  };

  const nextWord = () => {
    if (currentIndex < items.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      onClose(successCount, items.length);
    }
  };

  const boxSizeClass = userInput.length > 15 ? 'w-6 h-8 sm:w-8 sm:h-10 text-xs sm:text-lg' :
                       userInput.length > 12 ? 'w-8 h-10 sm:w-10 sm:h-12 text-lg' : 
                       userInput.length > 8 ? 'w-10 h-12 sm:w-14 sm:h-16 text-xl' : 
                       'w-12 h-14 sm:w-16 sm:h-20 text-2xl sm:text-4xl';

  return (
    <div className="w-full flex flex-col items-center space-y-10 animate-in fade-in slide-in-from-bottom-8">
      <div className="flex justify-between items-center px-6 w-full max-w-2xl">
        <span className="text-lg font-black text-slate-300 uppercase tracking-widest">KELİME YAZMA {currentIndex + 1} / {items.length}</span>
        <button onClick={() => onClose(successCount, items.length)} className="text-slate-400 font-bold hover:text-slate-600">Kapat ✖</button>
      </div>

      <div className="bg-white p-8 md:p-12 rounded-[3rem] md:rounded-[4rem] shadow-2xl border-4 border-white text-center w-fit min-w-[320px] max-w-full overflow-hidden flex flex-col items-center relative">
        <div className="mb-4">
          <span className="text-sm font-black text-indigo-400 uppercase tracking-widest bg-indigo-50 px-4 py-1 rounded-full">TÜRKÇE ANLAMI</span>
        </div>
        <h2 className="text-3xl md:text-5xl font-black text-slate-800 mb-8 md:mb-12 tracking-tight">
          {current.meaning}
        </h2>

        <div className="flex flex-nowrap justify-center gap-1 sm:gap-2 mb-12 w-full px-2 overflow-hidden">
          {userInput.map((letter, idx) => (
            <div 
              key={idx} 
              className={`${boxSizeClass} rounded-lg sm:rounded-2xl border-2 sm:border-4 flex items-center justify-center font-black transition-all flex-shrink-1 ${
                isCorrect ? 'bg-green-100 border-green-500 text-green-700' : 
                letter ? 'bg-white border-blue-400 text-blue-500' : 'bg-slate-50 border-slate-100'
              }`}
            >
              {letter}
            </div>
          ))}
        </div>

        {!isCorrect ? (
          <div className="flex flex-wrap justify-center gap-2 sm:gap-3 mb-10 w-full">
            {scrambled.map((letter, idx) => (
              <button
                key={idx}
                disabled={usedIndices.includes(idx) || isCorrect}
                onClick={() => handleLetterClick(letter, idx)}
                className={`w-10 h-10 sm:w-14 sm:h-14 rounded-xl sm:rounded-2xl flex items-center justify-center text-lg sm:text-2xl font-black transition-all transform active:scale-95 flex-shrink-0 ${
                  usedIndices.includes(idx) 
                  ? 'bg-slate-100 text-slate-200 cursor-not-allowed border-none shadow-none' 
                  : 'bg-blue-50 text-blue-500 hover:bg-blue-100 hover:scale-110 shadow-lg shadow-blue-100/50 border-2 border-blue-100'
                }`}
              >
                {letter}
              </button>
            ))}
          </div>
        ) : (
          <div className="flex justify-center items-center space-x-12 mb-10 animate-in zoom-in-95 duration-500">
            <div className="flex flex-col items-center space-y-2">
              <button 
                onClick={() => speak(current.word, 'en-GB')}
                className="w-16 h-16 bg-blue-50 text-blue-500 rounded-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-lg shadow-blue-100/50 border-2 border-blue-100"
              >
                <img src="https://flagcdn.com/w40/gb.png" className="w-6 rounded-sm" />
              </button>
            </div>
            <div className="flex flex-col items-center space-y-2">
              <button 
                onClick={() => speak(current.word, 'en-US')}
                className="w-16 h-16 bg-red-50 text-red-500 rounded-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-lg shadow-red-100/50 border-2 border-red-100"
              >
                <img src="https://flagcdn.com/w40/us.png" className="w-6 rounded-sm" />
              </button>
            </div>
          </div>
        )}

        <div className="flex flex-col items-center space-y-6 w-full">
          {!isCorrect && (
            <button 
              onClick={clearLast}
              className="text-slate-400 font-bold hover:text-red-400 transition-colors flex items-center space-x-2 bg-slate-50 px-4 py-2 rounded-full"
            >
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 9.75L14.25 12m0 0l2.25 2.25M14.25 12l2.25-2.25M14.25 12L12 14.25m-2.58 4.92l-6.375-6.375a1.125 1.125 0 010-1.59L9.42 4.83c.211-.211.498-.33.796-.33H19.5a2.25 2.25 0 012.25 2.25v10.5a2.25 2.25 0 01-2.25 2.25h-9.284c-.298 0-.585-.119-.796-.33z" />
              </svg>
              <span>Harf Sil</span>
            </button>
          )}

          {!isCorrect && timerSeconds >= 30 && (
            <button onClick={revealAnswer} className="px-8 py-4 bg-orange-400 text-white rounded-2xl font-black">Cevabı Gör ✨</button>
          )}
        </div>
      </div>

      {isCorrect && (
        <button onClick={nextWord} className="w-full max-w-2xl py-6 bg-orange-400 text-white rounded-[2.5rem] font-black text-2xl shadow-xl">
          {currentIndex === items.length - 1 ? 'Kampı Bitir ✨' : 'Sıradaki Kelime 🚀'}
        </button>
      )}
    </div>
  );
};

export default WordWriting;

import React, { useState } from 'react';
import { VocabularyItem } from '../types';

interface FlashcardsProps {
  items: VocabularyItem[];
  onComplete: (totalReviewed: number) => void;
}

const Flashcards: React.FC<FlashcardsProps> = ({ items, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  const current = items[currentIndex];

  const speak = (text: string, lang: 'en-GB' | 'en-US') => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices();
    const preferredVoice = voices.find(v => 
      (v.lang.includes(lang)) && 
      (v.name.includes('Female') || v.name.includes('Google') || v.name.includes('Samantha') || v.name.includes('Zira') || v.name.includes('Microsoft'))
    );
    if (preferredVoice) utterance.voice = preferredVoice;
    utterance.lang = lang;
    utterance.rate = 0.85; 
    utterance.pitch = 1.1; 
    utterance.volume = 1.0; 
    window.speechSynthesis.speak(utterance);
  };

  const nextCard = () => {
    if (currentIndex < items.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setIsFlipped(false);
    } else {
      onComplete(items.length);
    }
  };

  const prevCard = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
      setIsFlipped(false);
    }
  };

  return (
    <div className="flex flex-col items-center space-y-8 w-full max-w-lg mx-auto p-4 animate-in fade-in duration-500">
      <div className="w-full flex justify-between items-center px-4">
        <span className="text-sm font-bold text-orange-400 bg-orange-50 px-3 py-1 rounded-full">KART {currentIndex + 1} / {items.length}</span>
        <div className="h-3 w-32 bg-slate-100 rounded-full overflow-hidden border border-slate-200">
          <div 
            className="h-full bg-gradient-to-r from-blue-400 to-indigo-400 transition-all duration-500" 
            style={{ width: `${((currentIndex + 1) / items.length) * 100}%` }}
          />
        </div>
      </div>

      <div 
        className="relative w-full h-[450px] cursor-pointer perspective-1000"
        onClick={() => setIsFlipped(!isFlipped)}
      >
        <div className={`relative w-full h-full transition-all duration-500 transform-style-3d ${isFlipped ? 'rotate-y-180' : ''}`}>
          <div className="absolute inset-0 bg-white rounded-[3rem] shadow-xl flex flex-col items-center justify-center p-8 border-4 border-blue-50 backface-hidden">
            <span className="text-sm font-bold text-slate-300 uppercase tracking-widest mb-2">İNGİLİZCE</span>
            <h2 className="text-6xl font-black text-slate-800 mb-8 tracking-tight text-center">{current.word}</h2>
            <div className="flex space-x-8 mb-12">
              <div className="flex flex-col items-center space-y-3">
                <button onClick={(e) => { e.stopPropagation(); speak(current.word, 'en-GB'); }} className="w-16 h-16 bg-blue-50 text-blue-500 rounded-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all">
                  <img src="https://flagcdn.com/w40/gb.png" className="w-8" />
                </button>
              </div>
              <div className="flex flex-col items-center space-y-3">
                <button onClick={(e) => { e.stopPropagation(); speak(current.word, 'en-US'); }} className="w-16 h-16 bg-red-50 text-red-500 rounded-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all">
                  <img src="https://flagcdn.com/w40/us.png" className="w-8" />
                </button>
              </div>
            </div>
            <p className="text-slate-300 font-bold text-sm mt-auto">Çevirmek için tıkla ✨</p>
          </div>
          <div className="absolute inset-0 bg-gradient-to-br from-indigo-500 to-purple-500 rounded-[3rem] shadow-xl flex flex-col items-center justify-center p-10 text-white backface-hidden rotate-y-180 overflow-y-auto">
            <span className="text-sm font-bold text-white/50 uppercase tracking-widest mb-4">TÜRKÇE ANLAMI</span>
            <h3 className="text-5xl font-black mb-10 text-center">{current.meaning}</h3>
            <div className="space-y-6 w-full">
              <div className="bg-white/10 backdrop-blur-md p-6 rounded-[2rem] w-full border border-white/20">
                <p className="text-center italic text-xl font-medium leading-relaxed">"{current.exampleSentence}"</p>
              </div>
            </div>
            <p className="text-white/40 text-xs mt-auto pt-6 font-bold">Geri dönmek için tıkla 🧚</p>
          </div>
        </div>
      </div>

      <div className="flex space-x-4 w-full px-2">
        <button onClick={prevCard} disabled={currentIndex === 0} className="flex-1 py-5 bg-white border-2 border-slate-100 rounded-[2rem] font-black text-slate-500 disabled:opacity-30 transition-all">Önceki</button>
        <button onClick={nextCard} className="flex-1 py-5 bg-orange-400 text-white rounded-[2rem] font-black text-lg shadow-xl">
          {currentIndex === items.length - 1 ? 'Harika! Bitir' : 'Sıradaki Kelime'}
        </button>
      </div>
    </div>
  );
};

export default Flashcards;

import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';
import { VocabularyItem } from '../types';

interface StatisticsProps {
  userId: string;
  vocabItems: VocabularyItem[];
}

interface ActivityLog {
  activity_type: string;
  score: number;
  total_items: number;
  created_at: string;
}

const Statistics: React.FC<StatisticsProps> = ({ userId, vocabItems }) => {
  const [loading, setLoading] = useState(true);
  const [wordStats, setWordStats] = useState({
    total: 0,
    addedByMe: 0,
    daily: 0
  });
  const [activityLogs, setActivityLogs] = useState<ActivityLog[]>([]);

  useEffect(() => {
    fetchData();
  }, [vocabItems]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const now = new Date();
      const startOfDay = new Date(now.setHours(0,0,0,0)).toISOString();

      // Kelime istatistiklerini hesapla
      const { data: vocabData } = await supabase.from('vocabulary').select('created_at, user_id');
      if (vocabData) {
        setWordStats({
          total: vocabData.length,
          addedByMe: vocabData.filter(v => v.user_id === userId).length,
          daily: vocabData.filter(v => v.created_at >= startOfDay).length
        });
      }

      // Kullanıcı aktivitelerini çek (Tablo adının user_activities olduğu varsayılır)
      const { data: logData } = await supabase
        .from('user_activities')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false });

      if (logData) setActivityLogs(logData);

    } catch (err) {
      console.error('Stats loading error:', err);
    } finally {
      setLoading(false);
    }
  };

  const calculatePerformance = (type: string) => {
    const logs = activityLogs.filter(l => l.activity_type === type);
    if (logs.length === 0) return 0;
    const totalScore = logs.reduce((acc, curr) => acc + (curr.score / curr.total_items), 0);
    return Math.round((totalScore / logs.length) * 100);
  };

  return (
    <div className="max-w-5xl mx-auto w-full space-y-12 animate-in fade-in zoom-in-95 duration-500 pb-24">
      <div className="text-center space-y-4">
        <h2 className="text-5xl font-black text-slate-800 tracking-tight">Sana Özel İstatistikler 📊</h2>
        <p className="text-slate-400 font-bold text-lg uppercase tracking-[0.3em]">Senin Başarı Panelin</p>
      </div>

      {loading ? (
        <div className="flex justify-center py-20">
          <div className="w-16 h-16 border-8 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">

          {/* Main word counter */}
          <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 p-10 rounded-[3rem] shadow-2xl text-white flex flex-col items-center text-center col-span-1 md:col-span-2">
            <h3 className="font-black text-xs uppercase tracking-widest mb-6 opacity-60">Global Havuz Durumu</h3>
            <div className="flex items-center space-x-8">
               <div className="text-center">
                 <span className="text-7xl font-black block">{wordStats.total}</span>
                 <span className="text-xs font-bold uppercase opacity-60">Toplam Kelime</span>
               </div>
               <div className="h-16 w-px bg-white/20"></div>
               <div className="text-center">
                 <span className="text-7xl font-black block text-orange-400">{wordStats.addedByMe}</span>
                 <span className="text-xs font-bold uppercase opacity-60">Senin Katkın</span>
               </div>
            </div>
          </div>

          <div className="bg-white p-10 rounded-[3rem] shadow-xl border-b-8 border-orange-400 flex flex-col items-center justify-center text-center">
            <span className="text-4xl mb-2">🔥</span>
            <span className="text-4xl font-black text-slate-800">{wordStats.daily}</span>
            <h3 className="text-slate-400 font-black text-[10px] uppercase tracking-widest mt-2">Bugün Eklenenler</h3>
          </div>

          {/* Performance Sections */}
          <div className="bg-white p-8 rounded-[3rem] shadow-lg border border-slate-100 flex flex-col items-center text-center space-y-4">
            <div className="w-16 h-16 bg-green-50 rounded-2xl flex items-center justify-center text-3xl">🎓</div>
            <h4 className="font-black text-slate-800">Quiz Başarı Oranı</h4>
            <div className="relative w-24 h-24 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-100" />
                <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={251.2} strokeDashoffset={251.2 - (251.2 * calculatePerformance('quiz')) / 100} className="text-green-500" />
              </svg>
              <span className="absolute text-xl font-black text-green-600">%{calculatePerformance('quiz')}</span>
            </div>
            <p className="text-[10px] font-bold text-slate-400">Toplam {activityLogs.filter(l => l.activity_type === 'quiz').length} Test</p>
          </div>

          <div className="bg-white p-8 rounded-[3rem] shadow-lg border border-slate-100 flex flex-col items-center text-center space-y-4">
            <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center text-3xl">✍️</div>
            <h4 className="font-black text-slate-800">Yazma Doğruluğu</h4>
            <div className="relative w-24 h-24 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
