import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';
import { VocabularyItem } from '../types';

interface StatisticsProps {
  userId: string;
  vocabItems: VocabularyItem[];
}

interface ActivityLog {
  activity_type: string;
  score: number;
  total_items: number;
  created_at: string;
}

const Statistics: React.FC<StatisticsProps> = ({ userId, vocabItems }) => {
  const [loading, setLoading] = useState(true);
  const [wordStats, setWordStats] = useState({
    total: 0,
    addedByMe: 0
  });
  const [activityLogs, setActivityLogs] = useState<ActivityLog[]>([]);

  useEffect(() => {
    fetchData();
  }, [userId, vocabItems]);

  const fetchData = async () => {
    if (!userId) return;
    setLoading(true);
    try {
      // Kelime istatistiklerini hesapla
      const { data: vocabData } = await supabase.from('vocabulary').select('user_id');
      if (vocabData) {
        setWordStats({
          total: vocabData.length,
          addedByMe: vocabData.filter(v => v.user_id === userId).length
        });
      }

      // Kullanıcı aktivitelerini çek
      const { data: logData } = await supabase
        .from('user_activities')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false });

      if (logData) setActivityLogs(logData);

    } catch (err) {
      console.error('Stats loading error:', err);
    } finally {
      setLoading(false);
    }
  };

  const calculatePerformance = (type: string) => {
    const logs = activityLogs.filter(l => l.activity_type === type);
    if (logs.length === 0) return 0;
    const totalScore = logs.reduce((acc, curr) => acc + (curr.score / curr.total_items), 0);
    return Math.round((totalScore / logs.length) * 100);
  };

  const getDetails = (type: string) => {
    const logs = activityLogs.filter(l => l.activity_type === type);
    const totalCorrect = logs.reduce((acc, curr) => acc + curr.score, 0);
    const totalItems = logs.reduce((acc, curr) => acc + curr.total_items, 0);
    const totalWrong = totalItems - totalCorrect;
    return { totalCorrect, totalWrong };
  };

  const quizDetails = getDetails('quiz');
  const writingDetails = getDetails('writing');

  return (
    <div className="max-w-5xl mx-auto w-full space-y-12 animate-in fade-in zoom-in-95 duration-500 pb-24">
      <div className="text-center space-y-4">
        <h2 className="text-5xl font-black text-slate-800 tracking-tight">Sana Özel İstatistikler 📊</h2>
        <p className="text-slate-400 font-bold text-lg uppercase tracking-[0.3em]">Senin Başarı Panelin</p>
      </div>

      {loading ? (
        <div className="flex justify-center py-20">
          <div className="w-16 h-16 border-8 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">

          {/* Main word counter */}
          <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 p-10 rounded-[3rem] shadow-2xl text-white flex flex-col items-center text-center col-span-1 md:col-span-3">
            <h3 className="font-black text-xs uppercase tracking-widest mb-6 opacity-60">Global Havuz Durumu</h3>
            <div className="flex items-center space-x-12 sm:space-x-24">
               <div className="text-center">
                 <span className="text-6xl sm:text-7xl font-black block">{wordStats.total}</span>
                 <span className="text-xs font-bold uppercase opacity-60">Toplam Kelime</span>
               </div>
               <div className="h-16 w-px bg-white/20"></div>
               <div className="text-center">
                 <span className="text-6xl sm:text-7xl font-black block text-orange-400">{wordStats.addedByMe}</span>
                 <span className="text-xs font-bold uppercase opacity-60">Senin Katkın</span>
               </div>
            </div>
          </div>

          {/* 1. Flashcards (Left) */}
          <div className="bg-white p-8 rounded-[3rem] shadow-lg border border-slate-100 flex flex-col items-center text-center h-full min-h-[340px]">
            <div className="w-16 h-16 bg-purple-50 rounded-2xl flex items-center justify-center text-3xl mb-4">📚</div>
            <h4 className="font-black text-slate-800 mb-6">Flashcards</h4>
            <div className="text-6xl font-black text-purple-600 mb-2">
              {activityLogs.filter(l => l.activity_type === 'flashcards').reduce((acc, curr) => acc + curr.total_items, 0)}
            </div>
            <div className="flex-grow"></div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pb-2">Toplam Gözden Geçirilen</p>
          </div>

          {/* 2. Test Başarı Oranı (Middle) */}
          <div className="bg-white p-8 rounded-[3rem] shadow-lg border border-slate-100 flex flex-col items-center text-center h-full min-h-[340px]">
            <div className="w-16 h-16 bg-green-50 rounded-2xl flex items-center justify-center text-3xl mb-4">🎓</div>
            <h4 className="font-black text-slate-800 mb-4">Test Başarı Oranı</h4>
            <div className="relative w-24 h-24 flex items-center justify-center mb-6">
              <svg className="w-full h-full transform -rotate-90">
                <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-100" />
                <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={251.2} strokeDashoffset={251.2 - (251.2 * calculatePerformance('quiz')) / 100} className="text-green-500" />
              </svg>
              <span className="absolute text-xl font-black text-green-600">%{calculatePerformance('quiz')}</span>
            </div>
            <div className="flex space-x-4 items-center mt-auto pb-2">
              <div className="flex items-center space-x-1 bg-green-50 px-3 py-1 rounded-full">
                <span className="text-green-500 font-black">✓</span>
                <span className="text-xs font-black text-green-700">{quizDetails.totalCorrect}</span>
              </div>
              <div className="flex items-center space-x-1 bg-red-50 px-3 py-1 rounded-full">
                <span className="text-red-500 font-black">✕</span>
                <span className="text-xs font-black text-red-700">{quizDetails.totalWrong}</span>
              </div>
            </div>
          </div>

          {/* 3. Yazma Doğruluğu (Right) */}
          <div className="bg-white p-8 rounded-[3rem] shadow-lg border border-slate-100 flex flex-col items-center text-center h-full min-h-[340px]">
            <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center text-3xl mb-4">✍️</div>
            <h4 className="font-black text-slate-800 mb-4">Yazma Doğruluğu</h4>
            <div className="relative w-24 h-24 flex items-center justify-center mb-6">
              <svg className="w-full h-full transform -rotate-90">
                <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-100" />
                <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={251.2} strokeDashoffset={251.2 - (251.2 * calculatePerformance('writing')) / 100} className="text-blue-500" />
              </svg>
              <span className="absolute text-xl font-black text-blue-600">%{calculatePerformance('writing')}</span>
            </div>
            <div className="flex space-x-4 items-center mt-auto pb-2">
              <div className="flex items-center space-x-1 bg-green-50 px-3 py-1 rounded-full">
                <span className="text-green-500 font-black">✓</span>
                <span className="text-xs font-black text-green-700">{writingDetails.totalCorrect}</span>
              </div>
              <div className="flex items-center space-x-1 bg-red-50 px-3 py-1 rounded-full">
                <span className="text-red-500 font-black">✕</span>
                <span className="text-xs font-black text-red-700">{writingDetails.totalWrong}</span>
              </div>
            </div>
          </div>

          {/* Activity Timeline */}
          <div className="bg-white p-10 rounded-[3rem] shadow-xl border border-slate-50 col-span-1 md:col-span-3">
            <h4 className="font-black text-slate-800 mb-8 flex items-center space-x-2">
               <span>📅</span>
               <span>Son Aktivitelerin</span>
            </h4>
            <div className="space-y-4">
              {activityLogs.slice(0, 5).map((log, idx) => (
                <div key={idx} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <div className="flex items-center space-x-4">
                    <span className="text-xl">
                      {log.activity_type === 'quiz' ? '🎓' : log.activity_type === 'writing' ? '✍️' : '📚'}
                    </span>
                    <div>
                      <p className="font-black text-slate-700 uppercase text-xs">
                        {log.activity_type === 'quiz' ? 'Test Çözüldü' : log.activity_type === 'writing' ? 'Yazma Kampı' : 'Kart Çalışması'}
                      </p>
                      <p className="text-[10px] text-slate-400 font-bold">{new Date(log.created_at).toLocaleString('tr-TR')}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-black text-indigo-600">Skor: {log.score} / {log.total_items}</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Başarı: %{Math.round((log.score/log.total_items)*100)}</p>
                  </div>
                </div>
              ))}
              {activityLogs.length === 0 && (
                <p className="text-center py-10 text-slate-300 font-bold italic">Henüz kaydedilmiş bir çalışma verisi bulunmuyor. Hadi başla! 🚀</p>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Statistics;

