      if (vocabData) {
        setWordStats({
          total: vocabData.length,
          addedByMe: vocabData.filter(v => v.user_id === userId).length
        });
      }

      // 2. Kullanıcı aktivitelerini çek (UserId bazlı kesin filtreleme)
      const { data: logData, error: logError } = await supabase
        .from('user_activities')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false });

      if (logError) throw logError;
      if (logData) {
