        >
          {currentIndex === questions.length - 1 ? 'Sonucu Gör ✨' : 'Sıradaki Soru 🚀'}
        </button>
      )}
    </div>
  );
};

export default Quiz;

import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';
import Statistics from './components/Statistics';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (!process.env.API_KEY) {
      setError("Sistem yapılandırması eksik (API Key bulunamadı).");
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchAllWords = async () => {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        const mapped = data.map(item => ({
          id: item.id,
          word: item.english,
          meaning: item.turkish,
          partOfSpeech: item.part_of_speech || '',
          exampleSentence: item.example_sentence_en,
          exampleSentenceTurkish: item.example_sentence_tr
        }));
        setVocabItems(mapped);
      }
    } catch (err: any) {
      console.error('Veri çekme hatası:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const logActivity = async (type: string, score: number, total: number) => {
    if (!currentUser) return;
    try {
      const { error } = await supabase.from('user_activities').insert([{
        user_id: currentUser.id,
        activity_type: type,
        score: score,
        total_items: total
      }]);
      if (error) throw error;
    } catch (e) {
      console.error("Aktivite kaydedilemedi", e);
    }
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const speak = (text: string, lang: 'en-GB' | 'en-US') => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices();

    const preferredVoice = voices.find(v => {
      const matchesLang = v.lang.includes(lang);
      if (lang === 'en-GB') {
        return matchesLang && (v.name.includes('Male') || v.name.includes('George') || v.name.includes('Arthur'));
      } else {
        return matchesLang && (v.name.includes('Female') || v.name.includes('Samantha') || v.name.includes('Zira') || v.name.includes('Susan'));
      }
    }) || voices.find(v => v.lang.includes(lang));

    if (preferredVoice) utterance.voice = preferredVoice;
    utterance.lang = lang;
    utterance.rate = 0.85; 
    utterance.pitch = 1.0; 
    utterance.volume = 1.0; 
    window.speechSynthesis.speak(utterance);
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) return;
    setState('analyzing');
    setError(null);
    try {
      await fetchAllWords();
      const items = await analyzeVocabulary(base64, mimeType);

      if (!items || items.length === 0) throw new Error("Dosyada işlenecek kelime bulunamadı.");

      const existingWords = new Set(vocabItems.map(v => v.word.toLowerCase().trim()));
      const newUniqueItems = items.filter(item => !existingWords.has(item.word.toLowerCase().trim()));

      if (newUniqueItems.length === 0) {
        setError("Bu dosyadaki tüm kelimeler havuzda zaten mevcut! ✨");
        setState('selection');
        return;
      }

      const payloads = newUniqueItems.map(item => ({
        user_id: currentUser.id,
        english: item.word,
        turkish: item.meaning,
        part_of_speech: item.partOfSpeech,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish
      }));

      const { error: insertError } = await supabase.from('vocabulary').insert(payloads);

      if (insertError) throw insertError;

      await fetchAllWords();
      setState('selection');
    } catch (err: any) {
      setError(err.message || "Bilinmeyen bir analiz hatası oluştu.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 5) {
      setError("Test için havuzda en az 5 kelime olmalı!");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;
    if (!item.id && vocabItems.some(v => v.word.toLowerCase().trim() === item.word.toLowerCase().trim())) {
      setError("Bu kelime zaten ortak havuzda var! 🌟");
      setIsModalOpen(false);
      return;
    }

    try {
      const payload = {
        english: item.word,
        turkish: item.meaning,
        part_of_speech: item.partOfSpeech,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish,
        user_id: currentUser.id
      };

      let opError;
      if (item.id) {
        const { error } = await supabase.from('vocabulary').update(payload).eq('id', item.id);
        opError = error;
      } else {
        const { error } = await supabase.from('vocabulary').insert([payload]);
        opError = error;
      }

      if (opError) throw opError;

      await fetchAllWords();
      setEditingItem(null);
      setIsModalOpen(false);
    } catch (err: any) {
      setError(err.message);
    }
  };

  const filteredVocab = vocabItems.filter(item => 
    item.word.toLowerCase().includes(searchTerm.toLowerCase()) || 
    item.meaning.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen flex flex-col bg-[#fdfbf7]">
      <header className="bg-white/95 backdrop-blur-md sticky top-0 z-20 py-5 border-b border-slate-200 shadow-sm">
        <div className="max-w-6xl mx-auto px-6 flex justify-between items-center">
          <div className="flex items-center space-x-3 cursor-pointer" onClick={() => currentUser ? setState('selection') : setState('home')}>
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl shadow-lg">🚀</div>
            <div className="flex flex-col">
              <h1 className="text-xl font-black text-slate-800 leading-none">Super Word Buddy</h1>
              <span className="text-[10px] font-black text-indigo-500 uppercase tracking-tighter">Academic Global Pool</span>
            </div>
          </div>
          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <div className="flex items-center space-x-2 sm:space-x-4">
                <div className="hidden sm:flex flex-col items-end mr-2">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none">Global Havuz</span>
                  <span className="text-sm font-black text-indigo-600">{vocabItems.length} Kelime</span>
                </div>
                <button 
                  onClick={() => { setState('selection'); setSearchTerm(''); }} 
                  className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-50 hover:bg-indigo-50 text-2xl transition-all shadow-inner border border-slate-100"
                  title="Ana Menü"
                >🏠</button>
                <button onClick={() => setState('upload')} className="bg-indigo-600 text-white px-4 sm:px-5 py-2 rounded-xl text-sm font-black shadow-lg hover:bg-indigo-700 transition-all whitespace-nowrap">Hızlı Yükle</button>
                <span className="hidden md:inline-block text-sm font-bold text-slate-600 italic">
                  Hoş geldin <span className="text-[#FF0000] font-black">{currentUser.name}</span>
                </span>
                <button onClick={handleLogout} className="text-slate-400 hover:text-red-500 font-bold text-sm">Çıkış</button>
              </div>
            ) : (
              <button onClick={() => setState('login')} className="bg-slate-800 text-white px-5 py-2 rounded-xl text-sm font-black">Giriş Yap</button>
            )}
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full px-6 py-10">
        {error && (
          <div className="mb-8 p-6 bg-red-50 border-2 border-red-100 text-red-600 rounded-[2rem] text-center font-bold animate-in slide-in-from-top-4 duration-300 shadow-lg shadow-red-50">
            <div className="flex items-center justify-center space-x-3">
              <span className="text-2xl">🚨</span>
              <p>{error}</p>
            </div>
            <button onClick={() => setError(null)} className="mt-4 text-xs font-black uppercase tracking-widest bg-white px-4 py-2 rounded-full border border-red-100 hover:bg-red-100 transition-colors">Anladım</button>
          </div>
        )}

        {state === 'home' && (
          <div className="flex flex-col items-center justify-center space-y-10 py-16 text-center">
            <div className="w-32 h-32 bg-gradient-to-tr from-indigo-500 to-purple-500 rounded-[2.5rem] shadow-2xl flex items-center justify-center text-6xl">🎓</div>
            <div className="space-y-4">
              <h2 className="text-5xl md:text-6xl font-black text-slate-900 tracking-tighter leading-tight">
                Üniversite Arkadaşlarınla Birlikte <br/><span className="text-indigo-600">Kelime Dağarcığını Genişlet!</span>
              </h2>
              <p className="text-lg text-slate-500 max-w-xl mx-auto font-medium leading-relaxed">
                Bu uygulama akademik gelişim için tasarlanmıştır. Ortak kütüphane sayesinde yeni kelimeleri keşfedin ve birlikte öğrenin.
              </p>
            </div>
            <button onClick={() => setState('signup')} className="bg-indigo-600 text-white px-10 py-4 rounded-2xl text-lg font-black shadow-xl hover:scale-105 transition-all">
              Topluluğa Katılmak İçin Kayıt Ol! 🚀
            </button>
          </div>
        )}

        {(state === 'login' || state === 'signup') && (
          <AuthForm mode={state} onAuthSuccess={(user) => { setCurrentUser(user); setState('selection'); }} onToggleMode={(newMode) => setState(newMode)} />
        )}

        {state === 'upload' && <FileUpload onFileSelect={handleFileSelect} />}

        {state === 'analyzing' && (
          <div className="flex flex-col items-center justify-center py-24 space-y-6 text-center animate-pulse">
            <div className="w-20 h-20 border-8 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Veriler İşleniyor...</h3>
            <p className="text-slate-400 font-medium max-w-sm">Akademik kelimeler global havuza eklenmek üzere analiz ediliyor.</p>
          </div>
        )}

        {state === 'selection' && (
          <div className="space-y-12 animate-in fade-in slide-in-from-bottom-6 duration-500">
            <div className="text-center space-y-2">
              <h2 className="text-4xl font-black text-slate-900 tracking-tight italic">Common Academic Knowledge</h2>
              <p className="text-slate-400 text-lg font-medium">Toplam <span className="text-indigo-600 font-black">{vocabItems.length}</span> kelimelik devasa bir kaynağımız var.</p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              <div onClick={() => vocabItems.length > 0 ? setState('learning') : setState('upload')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">📚</div>
                <h3 className="text-xl font-black text-slate-800">Flashcards</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Kelime Kartları</p>
              </div>
              <div onClick={() => vocabItems.length >= 5 ? startQuiz() : setError("En az 5 kelime lazım!")} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">🎓</div>
                <h3 className="text-xl font-black text-slate-800">Kendini Test Et</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Gerçek Sınav Modu</p>
              </div>
              <div onClick={() => vocabItems.length > 0 ? setState('writing') : setState('upload')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">✍️</div>
                <h3 className="text-xl font-black text-slate-800">Yazma Kampı</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Spelling Pratiği</p>
              </div>
              <div onClick={() => setState('list')} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer text-center group">
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform">🌍</div>
                <h3 className="text-xl font-black text-slate-800">Havuzu Tara</h3>
                <p className="text-xs text-slate-400 mt-2 font-bold">Tüm Liste</p>
              </div>
            </div>

            <div className="flex flex-col items-center pt-8 border-t border-slate-100">
              <p className="text-slate-400 text-sm mb-4 font-bold uppercase tracking-widest">Havuzda Eksik Bir Şey mi Gördün?</p>
              <button onClick={() => { setEditingItem(null); setIsModalOpen(true); }} className="bg-white border-2 border-slate-100 px-10 py-4 rounded-2xl font-black text-slate-600 hover:border-indigo-600 hover:text-indigo-600 transition-all shadow-sm">
                + Manuel Kelime Ekle
              </button>
            </div>
          </div>
        )}

        {state === 'learning' && <Flashcards items={shuffleArray(vocabItems)} onComplete={async (total) => { await logActivity('flashcards', total, total); setState('selection'); }} />}
        {state === 'quiz' && <Quiz questions={quizQuestions} onClose={async (score, total) => { await logActivity('quiz', score, total); setState('selection'); }} />}
        {state === 'writing' && <WordWriting items={shuffleArray(vocabItems)} onClose={async (score, total) => { await logActivity('writing', score, total); setState('selection'); }} />}
        {state === 'stats' && <Statistics userId={currentUser?.id || ''} vocabItems={vocabItems} />}

        {state === 'list' && (
          <div className="space-y-10 animate-in fade-in duration-500">
            <div className="max-w-3xl mx-auto space-y-6">
              <h2 className="text-4xl font-black text-slate-900 text-center tracking-tight">Akademik Havuzu Tara 💎</h2>

              <div className="relative group">
                <div className="absolute inset-y-0 left-6 flex items-center pointer-events-none">
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-6 h-6 text-slate-300 group-focus-within:text-indigo-500 transition-colors">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" />
