                    </div>

                    <div className="flex space-x-2">
                      <button 
                        onClick={() => speak(item.word, 'en-GB')}
                        className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-sm border border-blue-100 overflow-hidden"
                        title="British"
                      >
                        <img src="https://flagcdn.com/w40/gb.png" className="w-6 h-auto rounded-sm shadow-xs" alt="UK" />
                      </button>
                      <button 
                        onClick={() => speak(item.word, 'en-US')}
                        className="w-10 h-10 bg-red-50 text-red-500 rounded-xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-sm border border-red-100 overflow-hidden"
                        title="American"
