          <button onClick={handleAccept} className="bg-white text-black px-8 py-2 rounded-lg text-sm font-black hover:bg-gray-200 transition-colors uppercase tracking-widest">Kabul Et</button>
        </div>
      </div>
    </div>
  );
};

