import React, { useState } from 'react';
import { QuizQuestion, QuizOption } from '../types';

interface QuizProps {
  questions: QuizQuestion[];
  onClose: (score: number, total: number) => void;
}

const Quiz: React.FC<QuizProps> = ({ questions, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [showResult, setShowResult] = useState(false);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [activeMeaningIdx, setActiveMeaningIdx] = useState<number | null>(null);

  const speak = (text: string, lang: 'en-GB' | 'en-US') => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices();

    const preferredVoice = voices.find(v => {
      const matchesLang = v.lang.includes(lang);
      if (lang === 'en-GB') {
        return matchesLang && (v.name.includes('Male') || v.name.includes('George') || v.name.includes('Arthur'));
      } else {
        return matchesLang && (v.name.includes('Female') || v.name.includes('Samantha') || v.name.includes('Zira') || v.name.includes('Susan'));
      }
    }) || voices.find(v => v.lang.includes(lang));

    if (preferredVoice) utterance.voice = preferredVoice;
    utterance.lang = lang;
    utterance.rate = 0.85; 
    utterance.pitch = 1.0; 
    utterance.volume = 1.0; 
    window.speechSynthesis.speak(utterance);
  };

  const isCorrectAnswer = (optionText: string, correct: string) => {
    return optionText.trim().toLowerCase() === correct.trim().toLowerCase();
  };

  const handleAnswer = (option: QuizOption) => {
    if (isAnswered) return;
    setSelectedOption(option.text);
    setIsAnswered(true);

    const correct = questions[currentIndex].correctAnswer;
    if (isCorrectAnswer(option.text, correct)) {
      setScore(s => s + 1);
    }
  };

  const nextQuestion = () => {
    if (currentIndex < questions.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setSelectedOption(null);
      setIsAnswered(false);
      setActiveMeaningIdx(null);
    } else {
      setShowResult(true);
    }
  };

  const speakQuestion = (lang: 'en-GB' | 'en-US') => {
    const questionText = questions[currentIndex].question;
    // Her türlü alt çizgiyi (bir veya daha fazla) "bla bla" olarak değiştir
    const readableText = questionText.replace(/_+/g, "bla bla");
    speak(readableText, lang);
  };

  if (showResult) {
    const percentage = Math.round((score / questions.length) * 100);
    let message = "Harika gidiyorsun! 🎉";
    let icon = "🌟";
    if (percentage === 100) { message = "Mükemmelsin! Şampiyon! 🏆"; icon = "🦁"; }
    else if (percentage < 50) { message = "Biraz daha çalışalım mı? 🧸"; icon = "📚"; }

    return (
      <div className="bg-white p-16 rounded-[4rem] shadow-2xl text-center max-w-lg mx-auto border-4 border-indigo-50 animate-in zoom-in-95 duration-500">
        <div className="text-7xl mb-8">{icon}</div>
        <h2 className="text-4xl font-black text-slate-800 mb-4 tracking-tight">{message}</h2>
        <p className="text-slate-400 text-xl font-medium mb-10">Havuzdaki kelimeleri iyice kavramışsın!</p>
        <div className="bg-indigo-50 p-10 rounded-[3rem] mb-12">
          <span className="text-7xl font-black text-indigo-500">%{percentage}</span>
          <p className="text-indigo-400 font-bold mt-2 uppercase tracking-widest">Başarı Oranın</p>
        </div>
        <button 
          onClick={() => onClose(score, questions.length)}
          className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] font-black text-xl hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100"
        >
          Havuz Seçimine Dön
        </button>
      </div>
    );
  }

  const current = questions[currentIndex];
  const labels = ['A', 'B', 'C', 'D', 'E'];

  return (
    <div className="w-full max-w-3xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-8 relative" onClick={() => setActiveMeaningIdx(null)}>
      <div className="flex justify-between items-center mb-4 px-6">
        <span className="text-lg font-black text-slate-300 uppercase tracking-widest">SORU {currentIndex + 1} / {questions.length}</span>
        <div className="flex items-center space-x-2 bg-yellow-50 px-5 py-2 rounded-full">
           <span className="text-lg">💎</span>
           <span className="text-yellow-600 font-black">SKOR: {score * 10}</span>
        </div>
      </div>

      <div className="bg-white p-10 md:p-14 rounded-[4rem] shadow-2xl border-4 border-white" onClick={(e) => e.stopPropagation()}>
        <div className="text-center mb-8">
          <h3 className="text-2xl md:text-4xl font-black text-slate-800 mb-6 leading-tight break-words">
            {current.question}
          </h3>

          <div className="flex justify-center space-x-4">
             <button 
               onClick={() => speakQuestion('en-GB')}
               className="flex items-center space-x-2 bg-blue-50 hover:bg-blue-100 px-4 py-2 rounded-xl transition-all border border-blue-100"
               title="Listen Question (Male)"
             >
               <img src="https://flagcdn.com/w40/gb.png" className="w-6 h-auto rounded-sm" alt="UK" />
               <span className="text-xs font-black text-blue-600 uppercase tracking-tighter">Listen (UK)</span>
             </button>
             <button 
               onClick={() => speakQuestion('en-US')}
               className="flex items-center space-x-2 bg-red-50 hover:bg-red-100 px-4 py-2 rounded-xl transition-all border border-red-100"
               title="Listen Question (Female)"
             >
               <img src="https://flagcdn.com/w40/us.png" className="w-6 h-auto rounded-sm" alt="US" />
               <span className="text-xs font-black text-red-600 uppercase tracking-tighter">Listen (US)</span>
             </button>
          </div>
        </div>

        <div className="grid gap-4">
          {current.options.map((option, idx) => {
            const isCorrect = isCorrectAnswer(option.text, current.correctAnswer);
            const isSelected = option.text === selectedOption;

            let bgColor = 'bg-slate-50 border-slate-100 hover:border-indigo-400 hover:bg-indigo-50/30';

            if (isAnswered) {
              if (isCorrect) {
                bgColor = 'bg-green-100 border-green-500 text-green-700 ring-4 ring-green-50 z-10';
              } else if (isSelected) {
                bgColor = 'bg-red-100 border-red-500 text-red-700';
              } else {
                bgColor = 'bg-slate-50 border-slate-100 opacity-40';
              }
            }

            return (
              <div key={idx} className="relative group">
                <button
                  disabled={isAnswered}
                  onClick={() => handleAnswer(option)}
                  className={`w-full text-left p-5 border-4 rounded-[2rem] text-lg font-bold transition-all flex items-center space-x-4 ${!isAnswered ? 'hover:scale-[1.01] active:scale-95 shadow-sm' : ''} ${bgColor}`}
                >
