import React, { useState } from 'react';
import { VocabularyItem } from '../types';

interface FlashcardsProps {
  items: VocabularyItem[];
  onComplete: (totalReviewed: number) => void;
}

const Flashcards: React.FC<FlashcardsProps> = ({ items, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  const current = items[currentIndex];

  const speak = (text: string, lang: 'en-GB' | 'en-US') => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices();

    const preferredVoice = voices.find(v => {
      const matchesLang = v.lang.includes(lang);
      if (lang === 'en-GB') {
        return matchesLang && (v.name.includes('Male') || v.name.includes('George') || v.name.includes('Arthur'));
      } else {
        return matchesLang && (v.name.includes('Female') || v.name.includes('Samantha') || v.name.includes('Zira') || v.name.includes('Susan'));
      }
    }) || voices.find(v => v.lang.includes(lang));

    if (preferredVoice) utterance.voice = preferredVoice;
    utterance.lang = lang;
    utterance.rate = 0.85; 
    utterance.pitch = 1.0; 
    utterance.volume = 1.0; 
    window.speechSynthesis.speak(utterance);
  };

  const nextCard = () => {
    if (currentIndex < items.length - 1) {
      setCurrentIndex(currentIndex + 1);
      setIsFlipped(false);
    } else {
      onComplete(items.length);
    }
  };

  const prevCard = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
      setIsFlipped(false);
    }
  };

  return (
    <div className="flex flex-col items-center space-y-8 w-full max-w-lg mx-auto p-4 animate-in fade-in duration-500">
      <div className="w-full flex justify-between items-center px-4">
        <span className="text-sm font-bold text-orange-400 bg-orange-50 px-3 py-1 rounded-full">KART {currentIndex + 1} / {items.length}</span>
        <div className="h-3 w-32 bg-slate-100 rounded-full overflow-hidden border border-slate-200">
          <div 
            className="h-full bg-gradient-to-r from-blue-400 to-indigo-400 transition-all duration-500" 
            style={{ width: `${((currentIndex + 1) / items.length) * 100}%` }}
          />
        </div>
      </div>

      <div 
        className="relative w-full h-[450px] cursor-pointer perspective-1000"
        onClick={() => setIsFlipped(!isFlipped)}
      >
        <div className={`relative w-full h-full transition-all duration-500 transform-style-3d ${isFlipped ? 'rotate-y-180' : ''}`}>
          {/* ÖN YÜZ (İngilizce) */}
          <div className="absolute inset-0 bg-white rounded-[3rem] shadow-xl flex flex-col items-center p-8 border-4 border-blue-50 backface-hidden">
            <span className="text-sm font-bold text-slate-300 uppercase tracking-widest mb-2 shrink-0">İNGİLİZCE</span>

            <div className="flex-1 flex flex-col items-center justify-center w-full text-center">
              <h2 className="text-6xl font-black text-slate-800 mb-2 tracking-tight">{current.word}</h2>
              {current.partOfSpeech && (
                <span className="mb-10 text-xs font-black text-slate-400 uppercase tracking-widest italic bg-slate-50 px-4 py-1.5 rounded-xl border border-slate-100">
                  ({current.partOfSpeech})
                </span>
              )}
              <div className="flex space-x-8">
                <button 
                  onClick={(e) => { e.stopPropagation(); speak(current.word, 'en-GB'); }} 
                  className="w-16 h-16 bg-blue-50 text-blue-500 rounded-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-md border border-blue-100"
                >
                  <img src="https://flagcdn.com/w40/gb.png" className="w-8 rounded-sm" alt="UK" />
                </button>
                <button 
                  onClick={(e) => { e.stopPropagation(); speak(current.word, 'en-US'); }} 
                  className="w-16 h-16 bg-red-50 text-red-500 rounded-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-md border border-red-100"
                >
                  <img src="https://flagcdn.com/w40/us.png" className="w-8 rounded-sm" alt="US" />
                </button>
              </div>
            </div>

            <p className="text-slate-300 font-bold text-sm shrink-0">Çevirmek için tıkla ✨</p>
          </div>

          {/* ARKA YÜZ (Türkçe) */}
          <div className="absolute inset-0 bg-gradient-to-br from-indigo-500 to-purple-500 rounded-[3rem] shadow-xl flex flex-col items-center p-8 text-white backface-hidden rotate-y-180 overflow-y-auto">
            <span className="text-sm font-bold text-white/50 uppercase tracking-widest mb-4 shrink-0">TÜRKÇE ANLAMI</span>

            <div className="flex-1 flex flex-col items-center justify-center w-full">
              <div className="flex flex-col items-center mb-8">
                <h3 className="text-5xl font-black text-center leading-tight">{current.meaning}</h3>
                {current.partOfSpeech && (
                  <span className="mt-3 px-4 py-1.5 bg-white/20 rounded-xl text-xs font-black uppercase tracking-widest backdrop-blur-sm border border-white/10">
                    ({current.partOfSpeech})
                  </span>
                )}
              </div>
              <div className="space-y-6 w-full">
                <div className="bg-white/10 backdrop-blur-md p-6 rounded-[2rem] w-full border border-white/20 shadow-lg">
                  <p className="text-center italic text-xl font-medium leading-relaxed">"{current.exampleSentence}"</p>
                  <div className="mt-4 pt-4 border-t border-white/20">
                    <p className="text-center text-sm font-bold opacity-80">{current.exampleSentenceTurkish}</p>
                  </div>
                </div>
              </div>
            </div>

            <p className="text-white/40 text-xs pt-6 font-bold shrink-0">Geri dönmek için tıkla 🧚</p>
