// Yardımcı fonksiyon: Diziyi karıştırır
const shuffle = <T>(array: T[]): T[] => {
  const newArray = [...array];
  for (let i = newArray.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
  }
  return newArray;
};

// JSON içindeki Markdown bloklarını ve gereksiz karakterleri temizleyen fonksiyon
const cleanJsonResponse = (text: string): string => {
  if (!text) return "[]";
  let cleaned = text.replace(/```json\s?|```/g, "").trim();
  const startIdx = cleaned.indexOf('[');
  const endIdx = cleaned.lastIndexOf(']');
  if (startIdx !== -1 && endIdx !== -1) {
    cleaned = cleaned.substring(startIdx, endIdx + 1);
  }
  return cleaned;
};

export const analyzeVocabulary = async (base64Data: string, mimeType: string): Promise<VocabularyItem[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Sen bir akademik İngilizce uzmanısın. Aşağıdaki akademik dokümanı analiz et.
    Dokümandan en az 40-50 tane kaliteli akademik kelime seç.

    KRİTİK TALİMAT:
    - "meaning" (anlam) alanı KESİNLİKLE VE SADECE TÜRKÇE OLMALIDIR. 
    - "wordTypeEn" alanı kelimenin İngilizce türünü belirtmelidir (noun, verb, adjective, adverb vb.).
    - "wordTypeTr" alanı kelimenin Türkçe türünü belirtmelidir (isim, fiil, sıfat, zarf vb.).
    - Kelime akademik İngilizce olsun, ancak "meaning" alanı her zaman doğru ve anlaşılır bir Türkçe çeviri olsun.
    - Örnek cümleler akademik düzeyde olsun (IELTS/TOEFL seviyesi).

    Yanıtı sadece saf JSON formatında (ARRAY) döndür.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              meaning: { type: Type.STRING },
              wordTypeEn: { type: Type.STRING },
              wordTypeTr: { type: Type.STRING },
              exampleSentence: { type: Type.STRING },
              exampleSentenceTurkish: { type: Type.STRING }
            },
            required: ["word", "meaning", "wordTypeEn", "wordTypeTr", "exampleSentence", "exampleSentenceTurkish"]
          }
        }
      }
    });

    const text = response.text;
    const cleanText = cleanJsonResponse(text);
    const parsed = JSON.parse(cleanText);
    return (Array.isArray(parsed) ? parsed : []) as VocabularyItem[];
  } catch (error) {
    console.error("Gemini Analiz Hatası:", error);
    throw new Error("Analiz sırasında teknik bir sorun oluştu.");
  }
};

export const generateQuiz = async (words: VocabularyItem[]): Promise<QuizQuestion[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const basketSubset = [...words].sort(() => Math.random() - 0.5).slice(0, 10);

  const prompt = `Aşağıdaki kelime sepetinden profesyonel bir test hazırla. 
  Öğrencileri sıkmamak için soruları A2'den B2 seviyesine kadar KARIŞIK zorlukta hazırla.
  Her bir şık (option) için kelimenin kendisini (text), Türkçe anlamını (meaning), İngilizce türünü (wordTypeEn) ve Türkçe türünü (wordTypeTr) mutlaka ekle.
  Sorular hem temel kavramları hem de ileri düzey akademik kullanımları içermeli.
  Cevap anahtarı net olsun. Sadece JSON döndür. 
  Kelimeler: ${JSON.stringify(basketSubset)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { 
                type: Type.ARRAY, 
                items: { 
                  type: Type.OBJECT,
                  properties: {
                    text: { type: Type.STRING },
                    meaning: { type: Type.STRING },
                    wordTypeEn: { type: Type.STRING },
                    wordTypeTr: { type: Type.STRING }
                  }
                }, 
                minItems: 5, 
                maxItems: 5 
              },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });

    const cleanText = cleanJsonResponse(response.text || "[]");
    const questions: QuizQuestion[] = JSON.parse(cleanText);

    return questions.map(q => ({
      ...q,
      options: shuffle(q.options)
    }));
  } catch (error) {
    console.error("Quiz üretim hatası:", error);
    return [];
  }
};

