const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (!process.env.API_KEY) {
      setError("Sistem yapılandırması eksik (API Key bulunamadı).");
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchAllWords = async () => {
    try {
      // Supabase'in 1000 kayıt limitini aşmak için döngülü çekim (chunking) yapıyoruz.
      let allData: any[] = [];
      let from = 0;
      let to = 999;
      let finished = false;

      while (!finished) {
        const { data, error } = await supabase
          .from('vocabulary')
          .select('id, english, turkish, word_type_en, word_type_tr, example_sentence_en, example_sentence_tr, created_at, user_id')
          .order('created_at', { ascending: false })
          .range(from, to);

        if (error) throw error;

        if (data && data.length > 0) {
          allData = [...allData, ...data];
          if (data.length < 1000) {
            finished = true;
          } else {
            from += 1000;
            to += 1000;
          }
        } else {
          finished = true;
        }
      }

      const mapped = allData.map(item => ({
        id: item.id,
        word: item.english,
        meaning: item.turkish,
        wordTypeEn: item.word_type_en || '',
        wordTypeTr: item.word_type_tr || '',
        exampleSentence: item.example_sentence_en,
        exampleSentenceTurkish: item.example_sentence_tr
      }));
      setVocabItems(mapped);
    } catch (err: any) {
      console.error('Veri çekme hatası:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const logActivity = async (type: string, score: number, total: number) => {
    if (!currentUser) return;
    try {
      const { error } = await supabase.from('user_activities').insert([{
        user_id: currentUser.id,
        activity_type: type,
        score: score,
        total_items: total
      }]);
      if (error) throw error;
    } catch (e) {
      console.error("Aktivite kaydedilemedi", e);
    }
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const speak = (text: string, lang: 'en-GB' | 'en-US') => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices();

    const preferredVoice = voices.find(v => {
      const matchesLang = v.lang.includes(lang);
      if (lang === 'en-GB') {
        return matchesLang && (v.name.includes('Male') || v.name.includes('George') || v.name.includes('Arthur'));
      } else {
        return matchesLang && (v.name.includes('Female') || v.name.includes('Samantha') || v.name.includes('Zira') || v.name.includes('Susan'));
      }
    }) || voices.find(v => v.lang.includes(lang));

    if (preferredVoice) utterance.voice = preferredVoice;
    utterance.lang = lang;
    utterance.rate = 0.85; 
    utterance.pitch = 1.0; 
    utterance.volume = 1.0; 
    window.speechSynthesis.speak(utterance);
  };

  const handleFileSelect = async (base64: string, mimeType: string) => {
    if (!currentUser) return;
    setState('analyzing');
    setError(null);
    try {
      await fetchAllWords();
      const items = await analyzeVocabulary(base64, mimeType);

      if (!items || items.length === 0) throw new Error("Dosyada işlenecek kelime bulunamadı.");

      const existingWords = new Set(vocabItems.map(v => v.word.toLowerCase().trim()));
      const newUniqueItems = items.filter(item => !existingWords.has(item.word.toLowerCase().trim()));

      if (newUniqueItems.length === 0) {
        setError("Bu dosyadaki tüm kelimeler havuzda zaten mevcut! ✨");
        setState('selection');
        return;
      }

      const payloads = newUniqueItems.map(item => ({
        user_id: currentUser.id,
        english: item.word,
        turkish: item.meaning,
        word_type_en: item.wordTypeEn,
        word_type_tr: item.wordTypeTr,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish
      }));

      const { error: insertError } = await supabase.from('vocabulary').insert(payloads);

      if (insertError) throw insertError;

      await fetchAllWords();
      setState('selection');
    } catch (err: any) {
      console.error("Yükleme Hatası Details:", err);
      setError("Yükleme başarısız oldu. Lütfen tekrar deneyin veya sistem yöneticisine başvurun.");
      setState('upload');
    }
  };

  const startQuiz = async () => {
    if (vocabItems.length < 5) {
      setError("Test için havuzda en az 5 kelime olmalı!");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;
    if (!item.id && vocabItems.some(v => v.word.toLowerCase().trim() === item.word.toLowerCase().trim())) {
      setError("Bu kelime zaten ortak havuzda var! 🌟");
      setIsModalOpen(false);
      return;
    }

    try {
      const payload = {
        english: item.word,
        turkish: item.meaning,
        word_type_en: item.wordTypeEn,
        word_type_tr: item.wordTypeTr,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish,
        user_id: currentUser.id
      };

      let opError;
      if (item.id) {
        const { error } = await supabase.from('vocabulary').update(payload).eq('id', item.id);
        opError = error;
      } else {
        const { error } = await supabase.from('vocabulary').insert([payload]);
        opError = error;
      }

      if (opError) throw opError;

      await fetchAllWords();
      setEditingItem(null);
      setIsModalOpen(false);
    } catch (err: any) {
      setError(err.message);
    }
  };

  const filteredVocab = vocabItems.filter(item => 
    item.word.toLowerCase().includes(searchTerm.toLowerCase()) || 
    item.meaning.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
