// --- GAME 1: WORD SHOOTER ---
const WordShooterGame: React.FC<{ vocabItems: VocabularyItem[]; onBack: () => void }> = ({ vocabItems, onBack }) => {
  const [targetWord, setTargetWord] = useState<VocabularyItem | null>(null);
  const [fallingWords, setFallingWords] = useState<{ id: number; item: VocabularyItem; x: number; y: number }[]>([]);
  const [score, setScore] = useState(0);
  const [gameOver, setGameOver] = useState(false);

  useEffect(() => {
    if (vocabItems.length === 0) return;
    nextLevel();
    const interval = setInterval(() => {
      setFallingWords(old => {
        const updated = old.map(w => ({ ...w, y: w.y + 0.8 }));
        if (updated.some(w => w.y > 80)) setGameOver(true);
        return updated;
      });
    }, 50);
    return () => clearInterval(interval);
  }, [vocabItems]);

  const nextLevel = () => {
    const subset = [...vocabItems].sort(() => Math.random() - 0.5).slice(0, 4);
    const target = subset[Math.floor(Math.random() * subset.length)];
    setTargetWord(target);
    setFallingWords(subset.map((item, i) => ({
      id: Math.random(),
      item,
      x: 10 + (i * 20),
      y: -10
    })));
  };

  const handleShoot = (id: number, word: string) => {
    if (word === targetWord?.word) {
      setScore(s => s + 10);
      nextLevel();
    } else {
      setScore(s => Math.max(0, s - 5));
    }
  };

  if (gameOver) {
    return (
      <div className="text-center space-y-8 animate-in zoom-in-95">
        <h2 className="text-6xl font-black text-red-500">Oyun Bitti! 💀</h2>
        <p className="text-3xl font-black">Skorun: {score}</p>
        <button onClick={() => { setScore(0); setGameOver(false); nextLevel(); }} className="px-10 py-4 bg-indigo-600 text-white rounded-2xl font-black">Tekrar Dene</button>
        <br/>
        <button onClick={onBack} className="text-slate-400 font-bold uppercase">Menüye Dön</button>
      </div>
    );
  }

  return (
    <div className="relative w-full max-w-2xl mx-auto h-[600px] bg-slate-900 rounded-[3rem] overflow-hidden border-8 border-slate-800 shadow-2xl">
      <div className="absolute top-4 left-4 text-white font-black z-10">SKOR: {score}</div>
      <button onClick={onBack} className="absolute top-4 right-4 text-white/50 font-bold z-10">Çıkış</button>

      {fallingWords.map(w => (
        <button 
          key={w.id}
          onClick={() => handleShoot(w.id, w.item.word)}
          className="absolute bg-white text-slate-800 px-4 py-2 rounded-xl font-black shadow-lg transition-transform hover:scale-110"
          style={{ left: `${w.x}%`, top: `${w.y}%` }}
        >
          {w.item.word}
        </button>
      ))}

      <div className="absolute bottom-0 left-0 right-0 p-8 bg-indigo-600 text-white text-center">
        <p className="text-xs uppercase tracking-widest font-black opacity-60 mb-1">Aşağıdaki Anlamın Karşılığını Vur!</p>
        <h3 className="text-3xl font-black">{targetWord?.meaning}</h3>
      </div>
    </div>
  );
};

// --- GAME 2: PAIR MATCH ---
const MatchGame: React.FC<{ vocabItems: VocabularyItem[]; onBack: () => void }> = ({ vocabItems, onBack }) => {
  const [cards, setCards] = useState<{ id: number; text: string; matchId: string; type: 'en' | 'tr'; isFlipped: boolean; isMatched: boolean }[]>([]);
  const [selected, setSelected] = useState<number[]>([]);
  const [score, setScore] = useState(0);

  useEffect(() => {
    initGame();
  }, []);

  const initGame = () => {
    const subset = [...vocabItems].sort(() => Math.random() - 0.5).slice(0, 6);
    const pairs: any[] = [];
    subset.forEach(item => {
      pairs.push({ id: Math.random(), text: item.word, matchId: item.id, type: 'en', isFlipped: false, isMatched: false });
      pairs.push({ id: Math.random(), text: item.meaning, matchId: item.id, type: 'tr', isFlipped: false, isMatched: false });
    });
    setCards(pairs.sort(() => Math.random() - 0.5));
  };

  const handleCardClick = (idx: number) => {
    if (selected.length === 2 || cards[idx].isFlipped || cards[idx].isMatched) return;

    const newSelected = [...selected, idx];
    const newCards = [...cards];
    newCards[idx].isFlipped = true;
    setCards(newCards);
    setSelected(newSelected);

    if (newSelected.length === 2) {
      const first = cards[newSelected[0]];
      const second = cards[newSelected[1]];

      if (first.matchId === second.matchId) {
        setScore(s => s + 20);
        setTimeout(() => {
          const matchedCards = [...cards];
          matchedCards[newSelected[0]].isMatched = true;
          matchedCards[newSelected[1]].isMatched = true;
          setCards(matchedCards);
          setSelected([]);
        }, 600);
      } else {
        setTimeout(() => {
          const resetCards = [...cards];
          resetCards[newSelected[0]].isFlipped = false;
          resetCards[newSelected[1]].isFlipped = false;
          setCards(resetCards);
          setSelected([]);
        }, 1000);
      }
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-10 animate-in fade-in">
      <div className="flex justify-between items-center">
        <h3 className="text-3xl font-black text-slate-800">Eşleşme Kartları 🧩</h3>
        <span className="bg-indigo-600 text-white px-5 py-2 rounded-xl font-black">PUAN: {score}</span>
      </div>

      <div className="grid grid-cols-3 sm:grid-cols-4 gap-4">
        {cards.map((card, i) => (
          <div 
            key={card.id} 
            onClick={() => handleCardClick(i)}
            className={`h-24 sm:h-32 rounded-2xl flex items-center justify-center p-2 text-center text-sm font-black cursor-pointer transition-all border-4 ${
              card.isMatched ? 'opacity-0 scale-90 pointer-events-none' : 
              card.isFlipped ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-slate-100 text-transparent'
            }`}
          >
            {card.isFlipped ? card.text : '❓'}
          </div>
        ))}
      </div>

      <div className="text-center">
        <button onClick={onBack} className="text-slate-400 font-bold uppercase">Menüye Dön</button>
      </div>
    </div>
  );
};

// --- GAME 3: CLOZE (SENTENCE) ---
const ClozeGame: React.FC<{ vocabItems: VocabularyItem[]; onBack: () => void }> = ({ vocabItems, onBack }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [items, setItems] = useState<VocabularyItem[]>([]);
  const [options, setOptions] = useState<string[]>([]);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);

  useEffect(() => {
    const shuffled = [...vocabItems].filter(v => v.exampleSentence.includes(v.word)).sort(() => Math.random() - 0.5).slice(0, 10);
    setItems(shuffled);
    if (shuffled.length > 0) setupOptions(shuffled[0]);
  }, [vocabItems]);

  const setupOptions = (item: VocabularyItem) => {
    const others = vocabItems.filter(v => v.id !== item.id).sort(() => Math.random() - 0.5).slice(0, 3).map(v => v.word);
    setOptions([...others, item.word].sort(() => Math.random() - 0.5));
  };

  const handleSelect = (opt: string) => {
    if (feedback) return;
    if (opt === items[currentIdx].word) {
      setFeedback('correct');
      setTimeout(() => {
        if (currentIdx < items.length - 1) {
          setCurrentIdx(currentIdx + 1);
          setupOptions(items[currentIdx + 1]);
          setFeedback(null);
        } else {
          alert("Oyun Bitti! Harikasın ✨");
          onBack();
        }
      }, 1500);
    } else {
      setFeedback('wrong');
      setTimeout(() => setFeedback(null), 1000);
    }
  };

  if (items.length === 0) return <div className="text-center p-20 font-black">Yükleniyor... (Kelime havuzu yetersiz olabilir)</div>;

  const current = items[currentIdx];
  const displaySentence = current.exampleSentence.replace(new RegExp(current.word, 'gi'), '__________');

  return (
    <div className="max-w-2xl mx-auto space-y-12 animate-in fade-in">
      <div className="text-center space-y-4">
        <h3 className="text-3xl font-black text-slate-800">Cümle Tamamlama 📝</h3>
        <p className="text-indigo-600 font-bold italic">"{current.exampleSentenceTurkish}"</p>
      </div>

      <div className="bg-white p-12 rounded-[4rem] border-4 border-indigo-50 shadow-2xl text-center">
        <h4 className="text-2xl md:text-3xl font-medium leading-relaxed text-slate-700">
           {displaySentence}
        </h4>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {options.map((opt, i) => (
          <button 
            key={i} 
            onClick={() => handleSelect(opt)}
            className={`py-5 rounded-[2rem] font-black text-xl transition-all shadow-md ${
              feedback === 'correct' && opt === current.word ? 'bg-green-500 text-white scale-105' :
              feedback === 'wrong' && opt !== current.word ? 'bg-slate-50 opacity-50' :
              'bg-white border-2 border-slate-100 hover:bg-indigo-50 hover:border-indigo-200'
            }`}
          >
            {opt}
          </button>
        ))}
      </div>

      {feedback === 'correct' && <div className="text-center text-4xl animate-bounce">🎯 Tebrikler!</div>}

      <div className="text-center pt-10">
        <button onClick={onBack} className="text-slate-400 font-bold uppercase">Menüye Dön</button>
      </div>
    </div>
  );
};

