  const prompt = `Aşağıdaki kelimelerden 5 soruluk A2-B1 seviyesinde test hazırla. Yanlış şıkları da listeden seç.
  JSON döndür: ${JSON.stringify(basketSubset)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: { 
                type: Type.ARRAY, 
                items: { 
                  type: Type.OBJECT,
                  properties: {
                    text: { type: Type.STRING },
                    meaning: { type: Type.STRING },
                    wordTypeEn: { type: Type.STRING },
                    wordTypeTr: { type: Type.STRING }
                  }
                }, 
                minItems: 5, 
                maxItems: 5 
              },
              correctAnswer: { type: Type.STRING },
              word: { type: Type.STRING }
            },
            required: ["question", "options", "correctAnswer", "word"]
          }
        }
      }
    });

    const cleanText = cleanJsonResponse(response.text || "[]");
    const questions: QuizQuestion[] = JSON.parse(cleanText);

    return questions.map(q => ({
      ...q,
      options: shuffle(q.options)
    }));
  } catch (error) {
    console.error("Quiz üretim hatası:", error);
    return [];
  }
};

export const generateTutorMaterial = async (base64Data: string, mimeType: string): Promise<TutorMaterial & { sources?: any[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Dokümanı incele ve ana konuyu anla. Ardından İNTERNETTEN (Google Search kullanarak) bu konuyla ilgili ek akademik bilgiler ve güncel içerikler bul. 
    Kullanıcıya şunları sun: 
    1. Özet (TR) - İnternet bulgularıyla harmanlanmış.
    2. 10 Anahtar Kelime (Anlam, Eş-Zıt Anlam).
    3. 5 MCQ Soru (Açıklamalı).

    Sadece JSON döndür.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: prompt }
        ]
      },
      config: {
        tools: [{ googleSearch: {} }],
        thinkingConfig: { thinkingBudget: 0 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            keyVocabulary: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  word: { type: Type.STRING },
                  meaning: { type: Type.STRING },
                  synonym: { type: Type.STRING },
                  antonym: { type: Type.STRING }
                }
              }
            },
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  question: { type: Type.STRING },
                  options: { type: Type.ARRAY, items: { type: Type.STRING } },
                  answer: { type: Type.STRING },
                  explanation: { type: Type.STRING }
                }
              }
            }
          }
        }
      }
    });

    const cleanText = cleanJsonResponse(response.text || "{}");
    const result = JSON.parse(cleanText);
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    return { ...result, sources };
  } catch (error) {
    console.error("Tutor Analiz Hatası:", error);
    throw new Error("Ders materyali işlenirken bir sorun oluştu.");
  }
};

