            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-3">İlgili Kaynaklar 🌐</span>
            <div className="flex flex-wrap gap-2">
              {material.sources.map((chunk, idx) => (
                chunk.web && (
                  <a key={idx} href={chunk.web.uri} target="_blank" rel="noopener noreferrer" className="text-xs font-bold text-indigo-500 bg-white px-3 py-1 rounded-full border border-indigo-100 hover:bg-indigo-50 transition-colors">
                    🔗 {chunk.web.title || "Kaynak"}
                  </a>
                )
              ))}
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {material.keyVocabulary.map((v, i) => (
            <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-md transition-all">
              <div className="flex justify-between items-start mb-3">
                <h4 className="text-2xl font-black text-indigo-600">{v.word}</h4>
                <span className="bg-indigo-50 text-indigo-500 px-3 py-1 rounded-lg text-xs font-black uppercase tracking-tighter">{v.meaning}</span>
              </div>
              <div className="flex space-x-4 mt-4 text-xs font-bold">
                <div className="flex-1 p-2 bg-green-50 rounded-xl text-green-700">Synonym: <span className="block font-black uppercase mt-1">{v.synonym}</span></div>
                <div className="flex-1 p-2 bg-red-50 rounded-xl text-red-700">Antonym: <span className="block font-black uppercase mt-1">{v.antonym}</span></div>
              </div>
            </div>
          ))}
        </div>

        <div className="space-y-6">
          <h3 className="text-2xl font-black text-slate-800">Materyali Ne Kadar Anladın? 🧐</h3>
          {material.questions.map((q, qIdx) => (
            <div key={qIdx} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm">
              <p className="text-lg font-black text-slate-800 mb-6">{qIdx + 1}. {q.question}</p>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {q.options.map((opt, oIdx) => {
                  const isSelected = selectedAnswers[qIdx] === opt;
                  const isCorrect = opt === q.answer;
                  const show = showResult[qIdx];

                  let btnClass = "p-4 rounded-2xl font-bold text-left transition-all border-2 ";
                  if (!show) btnClass += "bg-slate-50 border-transparent hover:bg-indigo-50 hover:border-indigo-100";
                  else if (isCorrect) btnClass += "bg-green-100 border-green-500 text-green-700";
                  else if (isSelected && !isCorrect) btnClass += "bg-red-100 border-red-500 text-red-700";
                  else btnClass += "bg-slate-50 border-transparent opacity-50";

                  return (
                    <button key={oIdx} onClick={() => checkAnswer(qIdx, opt)} disabled={show} className={btnClass}>
                      {opt}
                    </button>
                  );
                })}
              </div>
              {showResult[qIdx] && (
                <div className="mt-6 p-4 bg-indigo-50 rounded-2xl border border-indigo-100 animate-in slide-in-from-top-2">
                  <p className="text-sm font-bold text-indigo-600 italic">💡 {q.explanation}</p>
                </div>
              )}
            </div>
          ))}
        </div>

        <button onClick={onFinish} className="w-full py-6 bg-slate-800 text-white rounded-[2rem] font-black text-2xl shadow-xl hover:bg-slate-900 transition-all">
          Bu Seansı Bitir ✨
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in duration-500">
      <div className="text-center space-y-4">
        <h2 className="text-5xl font-black text-slate-800 tracking-tight">Ders Çalıştırıcı 🧠</h2>
      </div>

      <div className="mt-10">
        <FileUpload 
          onFileSelect={handleFile} 
          customInstruction="Görsel veya PDF dosyasını yüklemek için tıkla ya da buraya sürükle bırak! Sonrasında ders çalışmanın keyfine var :)"
        />
      </div>

      <div className="flex justify-center pt-8">
        <button onClick={onBack} className="text-slate-400 font-bold hover:text-slate-600 transition-colors uppercase tracking-widest text-sm">← Ana Menüye Dön</button>
      </div>
    </div>
  );
};

