        <p className="text-xs uppercase tracking-[0.2em] font-black opacity-60 mb-2">Vurman Gereken Kelime Anlamı:</p>
        <h3 className="text-4xl font-black">{targetWord?.meaning}</h3>
      </div>
    </div>
  );
};

// --- GAME 2: PAIR MATCH ---
const MatchGame: React.FC<{ vocabItems: VocabularyItem[]; onBack: () => void }> = ({ vocabItems, onBack }) => {
  const [cards, setCards] = useState<{ id: number; text: string; matchId: string; type: 'en' | 'tr'; isFlipped: boolean; isMatched: boolean }[]>([]);
  const [selected, setSelected] = useState<number[]>([]);
  const [score, setScore] = useState(0);
  const [gameFinished, setGameFinished] = useState(false);

  useEffect(() => {
    initGame();
  }, []);

  const initGame = () => {
    const subset = [...vocabItems].sort(() => Math.random() - 0.5).slice(0, 6);
    const pairs: any[] = [];
    subset.forEach(item => {
      pairs.push({ id: Math.random(), text: item.word, matchId: item.id, type: 'en', isFlipped: false, isMatched: false });
      pairs.push({ id: Math.random(), text: item.meaning, matchId: item.id, type: 'tr', isFlipped: false, isMatched: false });
    });
    setCards(pairs.sort(() => Math.random() - 0.5));
    setGameFinished(false);
    setSelected([]);
  };

  const handleCardClick = (idx: number) => {
    if (selected.length === 2 || cards[idx].isFlipped || cards[idx].isMatched) return;

    const newSelected = [...selected, idx];
    const newCards = [...cards];
    newCards[idx].isFlipped = true;
    setCards(newCards);
    setSelected(newSelected);

    if (newSelected.length === 2) {
      const first = cards[newSelected[0]];
      const second = cards[newSelected[1]];

      if (first.matchId === second.matchId) {
        setScore(s => s + 20);
        setTimeout(() => {
          const matchedCards = [...cards];
          matchedCards[newSelected[0]].isMatched = true;
          matchedCards[newSelected[1]].isMatched = true;
          setCards(matchedCards);
          setSelected([]);
          if (matchedCards.every(c => c.isMatched)) setGameFinished(true);
        }, 600);
      } else {
        setTimeout(() => {
          const resetCards = [...cards];
          resetCards[newSelected[0]].isFlipped = false;
          resetCards[newSelected[1]].isFlipped = false;
          setCards(resetCards);
          setSelected([]);
        }, 800);
      }
    }
  };

  if (gameFinished) {
    return (
      <div className="text-center space-y-8 animate-in zoom-in-95 bg-white p-16 rounded-[4rem] shadow-2xl max-w-xl mx-auto border-4 border-indigo-50">
        <h2 className="text-6xl font-black text-indigo-500">Tebrikler! 🎉</h2>
        <p className="text-2xl font-bold text-slate-600">Hafızan süper, tüm kelimeleri eşleştirdin!</p>
        <div className="flex flex-col space-y-4 pt-6">
          <button onClick={initGame} className="px-10 py-5 bg-indigo-600 text-white rounded-[2rem] font-black text-xl shadow-xl hover:scale-105 transition-all">Yeni Oyun ✨</button>
          <button onClick={onBack} className="text-slate-400 font-bold uppercase tracking-widest text-sm">Menüye Dön</button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto space-y-10 animate-in fade-in">
      <div className="flex justify-between items-center bg-white p-6 rounded-[2rem] shadow-sm">
        <h3 className="text-3xl font-black text-slate-800">Kelime Eşleştir 🧩</h3>
        <span className="bg-indigo-600 text-white px-6 py-2 rounded-full font-black shadow-lg">SKOR: {score}</span>
      </div>

      <div className="grid grid-cols-3 sm:grid-cols-4 gap-4">
        {cards.map((card, i) => (
          <div 
            key={card.id} 
            onClick={() => handleCardClick(i)}
            className={`h-24 sm:h-32 rounded-[2rem] flex items-center justify-center p-3 text-center text-sm font-black cursor-pointer transition-all border-4 ${
              card.isMatched ? 'opacity-0 scale-90 pointer-events-none' : 
              card.isFlipped ? 'bg-indigo-50 border-indigo-200 text-indigo-600 shadow-inner' : 'bg-white border-slate-100 text-transparent shadow-xl hover:border-indigo-100'
            }`}
          >
            {card.isFlipped ? card.text : '❓'}
          </div>
        ))}
      </div>

      <div className="text-center">
        <button onClick={onBack} className="text-slate-400 font-bold hover:text-slate-600 transition-colors uppercase tracking-widest text-xs">← Vazgeç ve Dön</button>
      </div>
    </div>
  );
};

// --- GAME 3: CLOZE (SENTENCE) ---
const ClozeGame: React.FC<{ vocabItems: VocabularyItem[]; onBack: () => void }> = ({ vocabItems, onBack }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [items, setItems] = useState<VocabularyItem[]>([]);
  const [options, setOptions] = useState<string[]>([]);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [wrongSelections, setWrongSelections] = useState<string[]>([]);
  const [mistakeCount, setMistakeCount] = useState(0);
  const [gameOver, setGameOver] = useState(false);

  useEffect(() => {
    const shuffled = [...vocabItems].filter(v => v.exampleSentence.includes(v.word)).sort(() => Math.random() - 0.5).slice(0, 20);
    setItems(shuffled);
    if (shuffled.length > 0) setupOptions(shuffled[0]);
  }, [vocabItems]);

  const setupOptions = (item: VocabularyItem) => {
    const others = vocabItems.filter(v => v.id !== item.id).sort(() => Math.random() - 0.5).slice(0, 3).map(v => v.word);
    setOptions([...others, item.word].sort(() => Math.random() - 0.5));
    setWrongSelections([]);
  };

  const handleSelect = (opt: string) => {
    if (feedback === 'correct' || wrongSelections.includes(opt)) return;

    if (opt === items[currentIdx].word) {
      setFeedback('correct');
      setTimeout(() => {
        if (currentIdx < items.length - 1 && currentIdx < 19) {
          setCurrentIdx(currentIdx + 1);
          setupOptions(items[currentIdx + 1]);
          setFeedback(null);
        } else {
          setGameOver(true);
        }
      }, 1200);
    } else {
      setFeedback('wrong');
      setMistakeCount(m => m + 1);
      setWrongSelections(prev => [...prev, opt]);
      setTimeout(() => setFeedback(null), 800);
    }
  };

  const resetGame = () => {
    const shuffled = [...vocabItems].filter(v => v.exampleSentence.includes(v.word)).sort(() => Math.random() - 0.5).slice(0, 20);
    setItems(shuffled);
    setCurrentIdx(0);
    setMistakeCount(0);
    setGameOver(false);
    setFeedback(null);
    if (shuffled.length > 0) setupOptions(shuffled[0]);
  };

  if (items.length === 0) return <div className="text-center p-20 font-black">Yükleniyor...</div>;

  if (gameOver) {
    return (
      <div className="text-center space-y-8 animate-in zoom-in-95 bg-white p-16 rounded-[4rem] shadow-2xl max-w-xl mx-auto border-4 border-green-50">
        <h2 className="text-6xl font-black text-green-500">Tebrikler! ✨</h2>
        <div className="space-y-4">
          <p className="text-2xl font-bold text-slate-700">Tüm cümleleri başarıyla tamamladın!</p>
          <div className="grid grid-cols-2 gap-4 text-slate-400 font-bold uppercase text-sm">
            <div className="bg-slate-50 p-4 rounded-2xl">
              <span className="block text-2xl text-green-500">{currentIdx + 1}</span>
              Cümle
            </div>
            <div className="bg-slate-50 p-4 rounded-2xl">
              <span className="block text-2xl text-red-400">{mistakeCount}</span>
              Yanlış Deneme
            </div>
          </div>
        </div>
        <div className="flex flex-col space-y-4 pt-6">
          <button onClick={resetGame} className="px-10 py-5 bg-green-500 text-white rounded-[2rem] font-black text-xl shadow-xl hover:scale-105 transition-all">Yeni Oyun ✨</button>
          <button onClick={onBack} className="text-slate-400 font-bold uppercase tracking-widest text-sm">Menüye Dön</button>
        </div>
      </div>
    );
  }

  const current = items[currentIdx];
  const displaySentence = current.exampleSentence.replace(new RegExp(current.word, 'gi'), '__________');

  return (
    <div className="max-w-2xl mx-auto space-y-12 animate-in fade-in">
      <div className="flex justify-between items-center px-4">
        <h3 className="text-3xl font-black text-slate-800">Cümle Tamamlama 📝</h3>
        <span className="bg-green-500 text-white px-5 py-2 rounded-full font-black text-sm uppercase tracking-widest">{currentIdx + 1} / 20</span>
      </div>

      <div className="text-center px-4">
        <p className="text-indigo-600 font-bold italic text-xl">"{current.exampleSentenceTurkish}"</p>
      </div>

      <div className="bg-white p-12 rounded-[4rem] border-4 border-green-50 shadow-2xl text-center relative overflow-hidden">
        <h4 className="text-2xl md:text-3xl font-medium leading-relaxed text-slate-700">
           {displaySentence}
        </h4>
        {feedback === 'correct' && <div className="absolute inset-0 bg-green-500/10 flex items-center justify-center animate-in fade-in"><span className="text-6xl animate-bounce">🎯</span></div>}
      </div>

      <div className="grid grid-cols-2 gap-4">
        {options.map((opt, i) => {
          const isWrong = wrongSelections.includes(opt);
          const isCorrect = feedback === 'correct' && opt === current.word;

          let btnClass = "py-6 rounded-[2.5rem] font-black text-xl transition-all shadow-md border-4 ";
          if (isCorrect) btnClass += "bg-green-500 border-green-300 text-white scale-105";
          else if (isWrong) btnClass += "bg-red-50 border-red-100 text-red-300 pointer-events-none";
          else btnClass += "bg-white border-slate-50 hover:border-green-200 hover:bg-green-50/30";

          return (
            <button key={i} onClick={() => handleSelect(opt)} className={btnClass}>
              {opt}
            </button>
          );
        })}
      </div>

      <div className="text-center">
        <button onClick={onBack} className="text-slate-400 font-bold uppercase tracking-widest text-xs">← Oyunun Bırak</button>
      </div>
    </div>
  );
};

