                <div className="text-5xl mb-4 group-hover:rotate-12 transition-transform">🧠</div>
                <h3 className="text-xl font-black">Auto Word Trainer</h3>
                <p className="text-xs text-white/70 mt-2 font-bold">Her 15 Dakikada Bir Kelime</p>
              </div>
              <div onClick={() => setState('games')} className="bg-gradient-to-br from-orange-400 to-pink-500 p-8 rounded-[2.5rem] shadow-xl hover:scale-[1.03] transition-all cursor-pointer text-center group text-white">
                <div className="text-5xl mb-4 group-hover:animate-bounce transition-transform">🎮</div>
                <h3 className="text-xl font-black">Play Game</h3>
                <p className="text-xs text-white/70 mt-2 font-bold">Eğlenerek Öğren</p>
              </div>
            </div>

            <div className="flex flex-col items-center pt-8 border-t border-slate-100">
              <p className="text-slate-400 text-sm mb-4 font-bold uppercase tracking-widest">Havuzda Eksik Bir Şey mi Gördün?</p>
              <button onClick={() => { setEditingItem(null); setIsModalOpen(true); }} className="bg-white border-2 border-slate-100 px-10 py-4 rounded-2xl font-black text-slate-600 hover:border-indigo-600 hover:text-indigo-600 transition-all shadow-sm">
