import React, { useState, useEffect } from 'react';
import { AppState, VocabularyItem, QuizQuestion, User } from './types';
import { analyzeVocabulary, generateQuiz } from './services/geminiService';
import { supabase } from './services/supabaseClient';
import FileUpload from './components/FileUpload';
import Flashcards from './components/Flashcards';
import Quiz from './components/Quiz';
import AddWordModal from './components/AddWordModal';
import WordWriting from './components/WordWriting';
import AuthForm from './components/AuthForm';
import Statistics from './components/Statistics';
import CookieConsent from './components/CookieConsent';
import TutorView from './components/TutorView';
import GamesHub from './components/GamesHub';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [vocabItems, setVocabItems] = useState<VocabularyItem[]>([]);
  const [totalPoolCount, setTotalPoolCount] = useState<number>(0);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VocabularyItem | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        const user: User = {
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.name || 'Öğrenci'
        };
        setCurrentUser(user);
        fetchAllWords();
        setState('selection');
      } else {
        setCurrentUser(null);
        setVocabItems([]);
        setTotalPoolCount(0);
        setState('home');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchAllWords = async () => {
    try {
      const { count, error: countError } = await supabase
        .from('vocabulary')
        .select('*', { count: 'exact', head: true });

      if (!countError && count !== null) {
        setTotalPoolCount(count);
      }

      let allData: any[] = [];
      let from = 0;
      let to = 999;
      let finished = false;

      while (!finished) {
        const { data, error: fetchError } = await supabase
          .from('vocabulary')
          .select('id, english, turkish, word_type_en, word_type_tr, example_sentence_en, example_sentence_tr, created_at, user_id')
          .order('created_at', { ascending: false })
          .range(from, to);

        if (fetchError) throw fetchError;

        if (data && data.length > 0) {
          allData = [...allData, ...data];
          if (data.length < 1000) {
            finished = true;
          } else {
            from += 1000;
            to += 1000;
          }
        } else {
          finished = true;
        }
      }

      const mapped = allData.map(item => ({
        id: item.id,
        word: item.english || '',
        meaning: item.turkish || '',
        wordTypeEn: item.word_type_en || '',
        wordTypeTr: item.word_type_tr || '',
        exampleSentence: item.example_sentence_en || '',
        exampleSentenceTurkish: item.example_sentence_tr || ''
      }));
      setVocabItems(mapped);
    } catch (err: any) {
      console.error('Veri çekme hatası:', err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const speak = (text: string, lang: 'en-GB' | 'en-US') => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices();
    const preferredVoice = voices.find(v => v.lang.includes(lang)) || voices[0];
    if (preferredVoice) utterance.voice = preferredVoice;
    utterance.lang = lang;
    utterance.rate = 0.9;
    window.speechSynthesis.speak(utterance);
  };

  const logActivity = async (type: string, score: number, total: number) => {
    if (!currentUser) return;
    try {
      await supabase.from('user_activities').insert([{
        user_id: currentUser.id,
        activity_type: type,
        score: score,
        total_items: total
      }]);
    } catch (e) {
      console.error("Aktivite kaydedilemedi", e);
    }
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  };

  const startQuiz = async () => {
    if (vocabItems.length < 5) {
      setError("Test için havuzda en az 5 kelime olmalı!");
      return;
    }
    setState('analyzing');
    try {
      const questions = await generateQuiz(vocabItems);
      setQuizQuestions(questions);
      setState('quiz');
    } catch (err) {
      setState('selection');
    }
  };

  const addOrUpdateWord = async (item: VocabularyItem) => {
    if (!currentUser) return;
    try {
      const payload = {
        english: item.word,
        turkish: item.meaning,
        word_type_en: item.wordTypeEn,
        word_type_tr: item.wordTypeTr,
        example_sentence_en: item.exampleSentence,
        example_sentence_tr: item.exampleSentenceTurkish,
        user_id: currentUser.id
      };
      if (item.id) {
        await supabase.from('vocabulary').update(payload).eq('id', item.id);
      } else {
        await supabase.from('vocabulary').insert([payload]);
      }
      await fetchAllWords();
      setEditingItem(null);
      setIsModalOpen(false);
    } catch (err: any) {
      setError(err.message);
    }
  };

  // Kesin filtreleme: Sadece veritabanından gelen ve harf eşleşmesi olan kelimeler.
  const filteredVocab = searchTerm.trim() === '' 
    ? vocabItems 
    : vocabItems.filter(item => 
        item.word.toLowerCase().includes(searchTerm.toLowerCase()) || 
        item.meaning.toLowerCase().includes(searchTerm.toLowerCase())
      );

  return (
    <div className="min-h-screen flex flex-col bg-[#fdfbf7]">
      <header className="bg-white/95 backdrop-blur-md sticky top-0 z-20 py-5 border-b border-slate-200 shadow-sm">
        <div className="max-w-6xl mx-auto px-6 flex justify-between items-center">
          <div className="flex items-center space-x-3 cursor-pointer" onClick={() => currentUser ? setState('selection') : setState('home')}>
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl shadow-lg">🚀</div>
            <div className="flex flex-col">
              <h1 className="text-xl font-black text-slate-800 leading-none">Super Word Buddy</h1>
              <span className="text-[10px] font-black text-indigo-500 uppercase tracking-tighter">Academic Global Pool</span>
            </div>
          </div>
          <nav className="flex items-center space-x-4">
            {currentUser ? (
              <div className="flex items-center space-x-4">
                <div className="hidden sm:flex flex-col items-end">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none">Global Havuz</span>
                  <span className="text-sm font-black text-indigo-600">{totalPoolCount.toLocaleString('tr-TR')} Kelime</span>
                </div>
                <button 
                  onClick={() => { setState('selection'); setSearchTerm(''); }} 
                  className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-50 hover:bg-indigo-50 text-2xl transition-all shadow-inner border border-slate-100"
                >🏠</button>
                <button onClick={() => setState('upload')} className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-sm font-black shadow-lg hover:bg-indigo-700 transition-all">Hızlı Yükle</button>
                <button onClick={handleLogout} className="text-slate-400 hover:text-red-500 font-bold text-sm">Çıkış</button>
              </div>
            ) : (
              <button onClick={() => setState('login')} className="bg-slate-800 text-white px-5 py-2 rounded-xl text-sm font-black">Giriş Yap</button>
            )}
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-6xl mx-auto w-full px-6 py-10">
        {error && (
          <div className="mb-8 p-6 bg-red-50 border-2 border-red-100 text-red-600 rounded-[2rem] text-center font-bold shadow-lg">
            <p>{error}</p>
            <button onClick={() => setError(null)} className="mt-4 text-xs font-black uppercase bg-white px-4 py-2 rounded-full border border-red-100">Anladım</button>
          </div>
        )}

        {state === 'home' && (
          <div className="flex flex-col items-center justify-center py-20 text-center space-y-8">
            <div className="text-8xl">🎓</div>
            <h2 className="text-5xl md:text-6xl font-black text-slate-900 tracking-tighter">Birlikte Kelime <br/><span className="text-indigo-600">Dağarcığını Genişlet!</span></h2>
            <button onClick={() => setState('signup')} className="bg-indigo-600 text-white px-10 py-4 rounded-2xl text-lg font-black shadow-xl hover:scale-105 transition-all">Topluluğa Katıl 🚀</button>
          </div>
        )}

        {(state === 'login' || state === 'signup') && <AuthForm mode={state} onAuthSuccess={(user) => { setCurrentUser(user); setState('selection'); }} onToggleMode={(newMode) => setState(newMode)} />}

        {state === 'selection' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in duration-500">
             <div onClick={() => setState('learning')} className="bg-blue-500 p-10 rounded-[2.5rem] shadow-xl hover:scale-105 transition-all cursor-pointer text-center text-white">
                <div className="text-5xl mb-4">📚</div>
                <h3 className="text-2xl font-black">Flashcards</h3>
             </div>
             <div onClick={startQuiz} className="bg-orange-500 p-10 rounded-[2.5rem] shadow-xl hover:scale-105 transition-all cursor-pointer text-center text-white">
                <div className="text-5xl mb-4">🎓</div>
                <h3 className="text-2xl font-black">Kendini Test Et</h3>
             </div>
             <div onClick={() => setState('list')} className="bg-rose-500 p-10 rounded-[2.5rem] shadow-xl hover:scale-105 transition-all cursor-pointer text-center text-white">
                <div className="text-5xl mb-4">🌍</div>
                <h3 className="text-2xl font-black">Global Kelime Havuzu</h3>
             </div>
             <div onClick={() => setState('writing')} className="bg-emerald-500 p-10 rounded-[2.5rem] shadow-xl hover:scale-105 transition-all cursor-pointer text-center text-white">
                <div className="text-5xl mb-4">✍️</div>
                <h3 className="text-2xl font-black">Yazma Kampı</h3>
             </div>
             <div onClick={() => setState('tutor')} className="bg-indigo-500 p-10 rounded-[2.5rem] shadow-xl hover:scale-105 transition-all cursor-pointer text-center text-white">
                <div className="text-5xl mb-4">🧠</div>
                <h3 className="text-2xl font-black">Auto Trainer</h3>
             </div>
             <div onClick={() => setState('games')} className="bg-pink-500 p-10 rounded-[2.5rem] shadow-xl hover:scale-105 transition-all cursor-pointer text-center text-white">
                <div className="text-5xl mb-4">🎮</div>
                <h3 className="text-2xl font-black">Oyunlar</h3>
             </div>
          </div>
        )}

        {state === 'list' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
              <h2 className="text-3xl font-black text-slate-800">Global Kelime Havuzu</h2>
              <div className="relative w-full md:w-96">
                <input 
                  type="text" 
                  placeholder="Kelime veya anlam ara..." 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full bg-white border-2 border-slate-200 rounded-2xl px-6 py-4 pl-12 focus:border-indigo-500 outline-none transition-all shadow-sm"
                />
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-xl opacity-40">🔍</span>
                {searchTerm && (
                  <button onClick={() => setSearchTerm('')} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600">✕</button>
                )}
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredVocab.length > 0 ? (
                filteredVocab.map((item) => (
                  <div key={item.id} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-lg transition-all">
                    <div className="flex justify-between items-start mb-4">
                      <div className="flex flex-col">
                        <h4 className="text-2xl font-black text-slate-800">{item.word}</h4>
                        <span className="text-[10px] font-black text-slate-400 uppercase italic">({item.wordTypeEn})</span>
                      </div>
                      <div className="flex space-x-2">
                        <button onClick={() => speak(item.word, 'en-GB')} className="w-8 h-8 rounded-lg border border-slate-100 overflow-hidden hover:scale-110 transition-transform">
                          <img src="https://flagcdn.com/w40/gb.png" className="w-full h-full object-cover" alt="UK" />
                        </button>
                        <button onClick={() => speak(item.word, 'en-US')} className="w-8 h-8 rounded-lg border border-slate-100 overflow-hidden hover:scale-110 transition-transform">
                          <img src="https://flagcdn.com/w40/us.png" className="w-full h-full object-cover" alt="US" />
                        </button>
                      </div>
                    </div>
                    <p className="text-indigo-600 font-black text-lg mb-4">{item.meaning}</p>
                    <div className="pt-4 border-t border-slate-50 space-y-2">
                      <p className="text-xs text-slate-600 font-bold italic leading-relaxed">"{item.exampleSentence}"</p>
                      <p className="text-[10px] text-slate-400 font-medium">{item.exampleSentenceTurkish}</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="col-span-full py-20 text-center space-y-6">
                  <div className="text-7xl animate-bounce">🏜️</div>
                  <p className="text-slate-500 text-xl font-black max-w-sm mx-auto">Aradığınız kelime henüz kelime havuzuna eklenmemiş</p>
                </div>
              )}
            </div>
            <div className="flex justify-center pt-8">
              <button onClick={() => setState('selection')} className="text-slate-400 font-bold hover:text-slate-600 uppercase tracking-widest text-sm">← Ana Menüye Dön</button>
            </div>
          </div>
        )}

        {state === 'analyzing' && <div className="flex flex-col items-center justify-center py-20 text-center space-y-6"><div className="w-16 h-16 border-8 border-t-indigo-600 border-indigo-100 rounded-full animate-spin"></div><h3 className="text-2xl font-black text-slate-800">Yükleniyor...</h3></div>}
        {state === 'upload' && <FileUpload onFileSelect={(b, m) => { /* Logic */ }} />}
        {state === 'learning' && <Flashcards items={shuffleArray(vocabItems).slice(0, 40)} onComplete={(t) => { logActivity('flashcards', t, t); setState('selection'); }} />}
        {state === 'quiz' && <Quiz questions={quizQuestions} onClose={(s, t) => { logActivity('quiz', s, t); setState('selection'); }} />}
        {state === 'writing' && <WordWriting items={shuffleArray(vocabItems)} onClose={(s, t) => { logActivity('writing', s, t); setState('selection'); }} />}
        {state === 'tutor' && <TutorView vocabItems={vocabItems} onBack={() => setState('selection')} onAnalyzing={() => setState('analyzing')} onFinish={() => setState('selection')} />}
        {state === 'games' && <GamesHub vocabItems={vocabItems} onBack={() => setState('selection')} />}
      </main>

      <footer className="mt-auto py-10 bg-white border-t border-slate-100 text-center">
         <a href="https://buymeacoffee.com/suattayfuntopak" target="_blank" rel="noopener noreferrer" className="inline-flex items-center space-x-3 bg-yellow-400 px-6 py-3 rounded-xl font-bold hover:scale-105 transition-all shadow-lg">
            <span>☕</span>
            <span>Buy me a coffee</span>
          </a>
      </footer>

      <CookieConsent />
      {isModalOpen && <AddWordModal onAdd={addOrUpdateWord} onClose={() => setIsModalOpen(false)} />}
    </div>
  );
};

